SLOW_TESTS = []


def slow(test):
    """Marks a test of the slow set."""
    SLOW_TESTS.append(test.__qualname__)
    return unittest.skipIf(FAST, "slow set: left out of the fast run (GSS_FAST=1)")(test)


def build_pe(imports=(), section=b".text", strings=b"", dotnet=False, flags=0x60000020,
             signed=False):
    """A tiny but well-formed PE32 with one section and an import table.
    ``imports``: names imported from kernel32, or ``{library: [names]}``
    (``"#12"`` imports by ordinal)."""
    rva, raw_ptr = 0x1000, 0x200
    libraries = imports if isinstance(imports, dict) else {"kernel32.dll": list(imports)}
    body = bytearray(b"\x90" * 16)
    desc_off = len(body)
    body += b"\0" * (20 * (len(libraries) + 1))         # descriptors + terminator
    for n, (library, names) in enumerate(libraries.items()):
        thunk_off = len(body)
        body += b"\0" * (4 * (len(names) + 1))
        name_off = len(body)
        body += library.encode() + b"\0"
        for i, name in enumerate(names):
            if name.startswith("#"):
                struct.pack_into("<I", body, thunk_off + 4 * i, 0x80000000 | int(name[1:]))
                continue
            struct.pack_into("<I", body, thunk_off + 4 * i, rva + len(body))
            body += b"\0\0" + name.encode() + b"\0"
        struct.pack_into("<IIIII", body, desc_off + 20 * n, rva + thunk_off, 0, 0, rva + name_off,
                         rva + thunk_off)
    body += strings
    body += b"\0" * (-len(body) % 0x200)

    dirs = [(0, 0)] * 16
    dirs[1] = (rva + desc_off, 20 * (len(libraries) + 1))
    if dotnet:
        dirs[14] = (rva, 72)
    if signed:                                          # a (fake) Authenticode directory
        dirs[4] = (raw_ptr + len(body), 16)
    opt = struct.pack("<HBBIIIIIIIIIHHHHHHIIIIHHIIIIII", 0x10B, 14, 0, len(body), 0, 0, rva,
                      rva, 0, 0x400000, 0x1000, 0x200, 6, 0, 0, 0, 6, 0, 0,
                      rva + 0x1000, 0x200, 0, 3, 0, 0x100000, 0x1000, 0x100000, 0x1000, 0, 16)
    opt += b"".join(struct.pack("<II", *d) for d in dirs)
    coff = struct.pack("<HHIIIHH", 0x14C, 1, 0, 0, 0, len(opt), 0x0102)
    sec = struct.pack("<8sIIIIIIHHI", section, len(body), rva, len(body), raw_ptr, 0, 0, 0, 0, flags)
    head = b"MZ" + b"\0" * 58 + struct.pack("<I", 0x40) + b"PE\0\0" + coff + opt + sec
    return head + b"\0" * (raw_ptr - len(head)) + bytes(body)


def benchmark_tool():
    """``tools/fp_benchmark.py`` as a module. Its launcher check runs without the
    Windows antimalware engine here, so that a test never depends on what
    Defender thinks of a test file."""
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "fp_benchmark", os.path.join(ROOT, "tools", "fp_benchmark.py"))
    tool = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(tool)
    tool.LAUNCHER_AMSI = False
    return tool


def active(findings, rule_id=None):
    return [f for f in findings if not f.suppressed and (rule_id is None or f.rule_id == rule_id)]


def watch_programs(test):
    """The programs started while the test runs (``subprocess.Popen``, which ``run`` uses too):
    a list that fills as they start."""
    import subprocess
    started, real = [], subprocess.Popen

    def popen(args, *rest, **kwargs):
        started.append(args)
        return real(args, *rest, **kwargs)

    subprocess.Popen = popen
    test.addCleanup(setattr, subprocess, "Popen", real)
    return started


