def build_png(extra_chunks=(), raw_between=b""):
    """A structurally valid 1x1 PNG; ``extra_chunks`` are ``(type, data)``,
    ``raw_between`` is put between two chunks without being one."""
    def chunk(kind, data):
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data))
    out = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", 1, 1, 8, 2, 0, 0, 0))
    for kind, data in extra_chunks:
        out += chunk(kind, data)
    out += raw_between
    return out + chunk(b"IDAT", zlib.compress(b"\0\xff\0\0")) + chunk(b"IEND", b"")


def build_ogg(payloads):
    out = b""
    for number, payload in enumerate(payloads):
        table = bytes([255] * (len(payload) // 255) + [len(payload) % 255])
        out += (b"OggS\0" + bytes([2 if number == 0 else 0]) + struct.pack("<QIII", number, 7, number, 0)
                + bytes([len(table)]) + table + payload)
    return out


class MediaStructureTests(unittest.TestCase):
    """Media files are read by their structure; only a file of an unknown format goes
    through a sliding window (since 2026-10-23)."""

    PE = build_pe(["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread",
                   "ExitProcess", "Sleep", "CloseHandle"])
    COMMAND = b"cmd.exe /c powershell -nop -w hidden -enc AAAA"
    BAT = b"@echo off\r\nset X=1\r\npowershell -nop -w hidden -enc AAAA\r\n"

    @staticmethod
    def noise(count):
        return bytes(b for b in os.urandom(3 * count) if b >= 0x80)[:count]     # nothing printable

    def test_container_boundaries(self):
        from gamescan.unpack import media
        png = build_png()
        self.assertEqual(media.parse(png)[:2], ("PNG image", len(png)))
        self.assertEqual(media.parse(png + b"tail").end, len(png))
        broken = bytearray(png)
        broken[40] ^= 0xFF                                    # damages the IDAT chunk
        info = media.parse(bytes(broken))
        self.assertIn("not a valid chunk at offset 33", info.problem)
        self.assertEqual(info.end, 33)
        ogg = build_ogg([b"\x01vorbis" + self.noise(40), self.noise(700), self.noise(300)])
        self.assertEqual(media.parse(ogg)[:2], ("Ogg audio", len(ogg)))
        self.assertEqual(media.parse(ogg + b"PK\x03\x04").end, len(ogg))
        jpeg = (b"\xff\xd8\xff\xe0\x00\x10JFIF\0" + b"\0" * 9 + b"\xff\xfe\x00\x07hello"
                + b"\xff\xda\x00\x08" + b"\0" * 6 + b"\x12\xff\x00\x34\xff\xd0\x56" + b"\xff\xd9")
        info = media.parse(jpeg + b"junk")
        self.assertEqual((info.kind, info.end, info.problem), ("JPEG image", len(jpeg), ""))
        self.assertIn(("segment FE", b"hello"), info.texts)
        self.assertEqual(media.parse(jpeg + jpeg).end, 2 * len(jpeg), "a second picture may follow")
        gif = (b"GIF89a" + struct.pack("<HHBBB", 1, 1, 0, 0, 0) + b"\x21\xfe\x05hello\0"
               + b"\x2c" + struct.pack("<HHHHB", 0, 0, 1, 1, 0) + b"\x02\x02\x44\x01\0" + b"\x3b")
        info = media.parse(gif + b"xx")
        self.assertEqual((info.end, info.texts), (len(gif), [("extension FE", b"hello")]))
        wav = b"RIFF" + struct.pack("<I", 4 + 8 + 16 + 8 + 10) + b"WAVE" + b"fmt " + \
            struct.pack("<I", 16) + b"\0" * 16 + b"data" + struct.pack("<I", 10) + b"\x80" * 10
        self.assertEqual(media.parse(wav + b"more")[:2], ("WAV audio", len(wav)))
        oversize = wav[:4] + struct.pack("<I", 99999) + wav[8:]
        self.assertEqual((media.parse(oversize).end, media.parse(oversize).problem), (len(wav), ""))
        mp4 = struct.pack(">I4s", 16, b"ftyp") + b"M4A \0\0\0\0" + struct.pack(">I4s", 20, b"mdat") + b"\x80" * 12
        self.assertEqual(media.parse(mp4 + b"\0\0\0\x09\xff\xfe\xfd\xfc!").end, len(mp4))
        bmp = b"BM" + struct.pack("<I", 30) + b"\0" * 24
        self.assertEqual(media.parse(bmp + b"x").end, 30)
        self.assertIsNone(media.parse(b"\x00\x01\x02\x03" + b"\0" * 40))
        self.assertIsNone(media.parse(b""))
        self.assertTrue(media.blank(b"\0 \r\n\xff"))
        self.assertEqual(media.runs(b"\x80short\x80" + b"long enough\r\nline two\x80"
                                    + "wide text!".encode("utf-16-le") + b"\x80\x80"),
                         ["long enough\r\nline two", "wide text!"])

    def test_payload_after_the_end_of_the_media(self):
        s = Scanner()
        for name, body in (("pic.png", build_png()),
                           ("bgm.ogg", build_ogg([b"\x01vorbis" + self.noise(30), self.noise(500)]))):
            clean = s.scan_bytes("Graphics/" + name, body)
            self.assertEqual(clean, [], name)
            self.assertEqual(s.scan_bytes("Graphics/" + name, body + b"\0" * 300), [], "padding")
            found = s.scan_bytes("Graphics/" + name, body + self.PE)
            hidden = active(found, "MEDIA-002")
            self.assertEqual((len(hidden), hidden[0].severity), (1, Severity.HIGH), name)
            self.assertIn("after the end of the", hidden[0].evidence)
            child = [f for f in found if f.file == "Graphics/%s!appended.exe" % name]
            self.assertEqual(len(active(child, "INJ-001")), 3, "the hidden program is analysed")
            script = s.scan_bytes("Graphics/" + name, body + self.BAT)
            self.assertTrue(active(script, "MEDIA-002"), name)
            self.assertTrue([f for f in active(script, "LOL-001")
                             if f.file == "Graphics/%s!appended.bat" % name])
            other = s.scan_bytes("Graphics/" + name, body + self.noise(64))
            self.assertEqual([(f.rule_id, f.severity) for f in other], [("MEDIA-001", Severity.LOW)])

    def test_short_command_between_binary_data(self):
        s = Scanner()
        inside_page = build_ogg([b"\x01vorbis" + self.noise(30),
                                 self.noise(900) + self.COMMAND + self.noise(900), self.noise(400)])
        self.assertTrue(active(s.scan_bytes("Audio/bgm.ogg", inside_page), "LOL-001"),
                        "46 bytes of text in 2 KB of sound data")
        wide = build_ogg([self.noise(900) + self.COMMAND.decode().encode("utf-16-le") + self.noise(900)])
        self.assertTrue(active(s.scan_bytes("Audio/bgm.ogg", wide), "LOL-001"), "UTF-16 too")
        between = build_png(raw_between=self.noise(40) + self.COMMAND + self.noise(40))
        found = s.scan_bytes("Graphics/pic.png", between)
        self.assertTrue(active(found, "LOL-001"), "bytes that are not a chunk at all")
        note = active(found, "MEDIA-001")
        self.assertEqual(len(note), 1)
        self.assertIn("from where the structure breaks", note[0].evidence)
        mp3 = b"ID3\x03\0\0\0\0\0\0" + self.noise(5000) + self.COMMAND + self.noise(5000)
        self.assertTrue(active(s.scan_bytes("Audio/bgm.mp3", mp3), "LOL-001"),
                        "formats without a parser still go through the sliding window")
        buried = self.noise(3000) + self.PE + self.noise(3000)
        found = s.scan_bytes("Audio/bgm.mp3", buried)
        self.assertTrue(active(found, "MEDIA-002"))
        self.assertTrue([f for f in active(found, "INJ-001") if "!embedded_0xbb8.exe" in f.file])

    def test_the_media_data_itself_is_not_read_as_text(self):
        """phageo, 2026-10-23 (round 2, HO2-10: `wmic` by chance in the samples of two `.wav`):
        the rules read a media file's text parts and what lies beyond its own structure -
        never its picture / sound data. A program hidden in that data is still carved out."""
        s = Scanner()

        def wav(*chunks):
            body = b"WAVE" + b"".join(name + struct.pack("<I", len(data)) + data + b"\0" * (len(data) & 1)
                                      for name, data in chunks)
            return b"RIFF" + struct.pack("<I", len(body)) + body

        fmt = (b"fmt ", b"\x01\0\x02\0" + b"\0" * 12)
        samples = self.noise(900) + b"{wmic[WMD;6*" + self.noise(50) + self.COMMAND + self.noise(900)
        self.assertEqual(s.scan_bytes("game/audio/a.wav", wav(fmt, (b"data", samples))), [],
                         "words in the samples are chance")
        listed = wav(fmt, (b"LIST", b"INFO" + self.COMMAND), (b"data", self.noise(900)))
        self.assertTrue(active(s.scan_bytes("game/audio/a.wav", listed), "LOL-001"), "a text chunk is read")
        behind = wav(fmt, (b"data", self.noise(900))) + self.noise(30) + self.COMMAND
        self.assertTrue(active(s.scan_bytes("game/audio/a.wav", behind), "LOL-001"), "beyond the RIFF end")
        from gamescan.unpack import media
        whole = wav(fmt, (b"data", self.noise(100)))
        extra = b"\x01\x02\x03\x04" + struct.pack("<I", 9) + self.COMMAND      # inside the RIFF size, no chunk
        broken = whole[:4] + struct.pack("<I", len(whole) - 8 + len(extra)) + whole[8:] + extra
        self.assertIn("not a valid chunk", media.parse(broken).problem)
        self.assertTrue(active(s.scan_bytes("game/audio/a.wav", broken), "LOL-001"), "from a broken chunk on")
        pixels = build_png([(b"IDAT", self.noise(40) + self.COMMAND)])
        self.assertFalse(active(s.scan_bytes("Graphics/a.png", pixels), "LOL-001"), "picture data")
        late = build_ogg([b"\x01vorbis" + self.noise(20), self.noise(99), self.noise(99), self.noise(99),
                          self.noise(400) + self.COMMAND + self.noise(400)])
        self.assertFalse(active(s.scan_bytes("Audio/a.ogg", late), "LOL-001"), "an audio page")
        hidden = wav(fmt, (b"data", self.noise(300) + self.PE + self.noise(300)))
        self.assertTrue(active(s.scan_bytes("game/audio/a.wav", hidden), "MEDIA-002"), "a program is carved")

    def test_metadata_is_read_even_when_it_is_compressed(self):
        s = Scanner()
        packed = build_png([(b"zTXt", b"Comment\0\0" + zlib.compress(self.COMMAND))])
        self.assertNotIn(self.COMMAND, packed)
        self.assertTrue(active(s.scan_bytes("Graphics/a.png", packed), "LOL-001"), "zTXt is inflated")
        itxt = build_png([(b"iTXt", b"XML:com\0\x01\0\0\0" + zlib.compress(self.COMMAND))])
        self.assertTrue(active(s.scan_bytes("Graphics/a.png", itxt), "LOL-001"), "compressed iTXt")
        private = build_png([(b"paYl", self.noise(50) + self.COMMAND + self.noise(50))])
        found = s.scan_bytes("Graphics/a.png", private)
        self.assertTrue(active(found, "LOL-001"), "a chunk of its own")
        self.assertFalse([f for f in found if f.rule_id.startswith("MEDIA-")], "valid structure")
        comment = build_ogg([b"\x01vorbis" + self.noise(20), b"\x03vorbis" + self.COMMAND, self.noise(99)])
        self.assertTrue(active(s.scan_bytes("Audio/a.ogg", comment), "LOL-001"))
        profile = build_png([(b"tEXt", b"Software\0http://www.iec.ch sRGB")])
        self.assertFalse(active(s.scan_bytes("Graphics/a.png", profile)),
                         "ordinary metadata addresses are not findings")

    def test_named_like_media_but_something_else(self):
        s = Scanner()
        found = s.scan_bytes("Graphics/logo.png", self.BAT)
        self.assertTrue(active(found, "MEDIA-002"))
        self.assertTrue([f for f in active(found, "LOL-001") if f.file == "Graphics/logo.png!content.bat"])
        self.assertEqual(s.scan_bytes("Graphics/enc.png", b"RPGMV\0\0\0" + self.noise(500)), [],
                         "an unknown / encrypted asset format is not a finding")
        self.assertTrue(active(s.scan_bytes("Graphics/logo.png", self.PE), "NAME-002"),
                        "a plain program with a media name is the PE handler's case")

    def test_media_inside_archives_and_large_files(self):
        from gamescan import scanner as scanner_module
        rgss = RgssTests()
        game = rgss.archive_v1({"Data\\Scripts.rxdata": rgss.scripts_file([("A", "x = 1\n")]),
                                "Graphics\\Titles\\title.png": build_png() + self.PE,
                                "Audio\\BGM\\a.ogg": build_ogg([self.noise(500) + self.COMMAND])})
        found = Scanner().scan_bytes("Game.rgssad", game)
        self.assertTrue([f for f in active(found, "MEDIA-002")
                         if f.file == "Game.rgssad!Graphics/Titles/title.png"])
        self.assertTrue([f for f in active(found, "INJ-001") if f.file.endswith("title.png!appended.exe")])
        self.assertTrue([f for f in active(found, "LOL-001") if f.file == "Game.rgssad!Audio/BGM/a.ogg"])
        zipped = Scanner().scan_bytes("g.7z", build_7z({"img/x.png": build_png() + self.BAT}))
        self.assertTrue([f for f in active(zipped, "MEDIA-002") if f.file == "g.7z!img/x.png"])
        # a media file too large to be loaded is read from disk, to its end
        with tempfile.TemporaryDirectory() as tmp:
            with open(os.path.join(tmp, "movie.ogv"), "wb") as fh:
                fh.write(build_ogg([self.noise(60_000)] * 3) + self.noise(50_000) + self.COMMAND)
            scanner = Scanner()
            scanner.max_bytes = 4096
            report = scanner.scan(tmp)
        self.assertTrue(active(report.findings, "LOL-001"), "text behind the loaded part is read")
        self.assertFalse([n for n in report.notes if "only the first" in n])
        del scanner_module

