    def test_other_writes_and_deletions_stay_at_their_level(self):
        medium = {
            "a script": dict(name='"helper.js"'),
            "a program": dict(name='"update.exe"'),
            "a batch file": dict(name='"run.bat"'),
            "a native module": dict(name='"addon.node"'),
            "no extension": dict(name='"index"'),
            "a name nobody can read": dict(name="makeName()"),
            "a name that is set twice": dict(call="$._indexFilename = other; " + self.WRITE),
            "the user's profile": dict(place="path_js.join(process.env.APPDATA, this.customCursorPath)"),
            "the home folder": dict(place="require('os').homedir() + '/x/'"),
            "a drive": dict(place="'C:/Users/Public/' + this.customCursorPath"),
            "out of the game folder": dict(
                place="path_js.join(path_js.dirname(process.mainModule.filename), '../../' + this.dir)"),
            "a path nobody can read": dict(place="this.makePath()"),
            "a path that is also set elsewhere": dict(call="path = this.other; " + self.WRITE),
            "the name leads elsewhere": dict(name='"../../x.json"'),
            "a deletion": dict(call="fs.unlinkSync(path + this._indexFilename);"),
            "a folder removed": dict(call="fs.rmdirSync(path);"),
            "a rename": dict(call="fs.renameSync(path + this._indexFilename, path + 'x.js');"),
            "a copy": dict(call="fs.copyFileSync(path + this._indexFilename, path + 'x.json');"),
            "a deletion on the same line": dict(call=self.WRITE + " fs.unlinkSync(target);"),
            "the whole path from a setting": dict(call="fs.writeFileSync(this.target, text);"),
            "a file name only": dict(call="fs.writeFileSync('notes.txt', text);"),
            "a condition picks the path": dict(call="fs.writeFileSync(ok ? path + 'a.json' : other, text);"),
        }
        for label, options in medium.items():
            hits = active(self.plugin(**options), "JS-FS-001")
