    def test_protection_is_hidden_in_09_beta(self):
        from gamescan import models
        self.assertFalse(models.EXPERIMENTAL_PROTECTION)
        app = self.app
        app.settings["realtime_enabled"] = True                # a setting saved by an older version
        app.apply_settings()
        self.assertIsNone(app.monitor, "real-time protection never starts")
