class ShellMenuTests(unittest.TestCase):
    """The Explorer right-click menu (packaging session 2, phageo 2026-10-24): HKCU only, opt-in,
    nothing left behind. Written below a test key of HKEY_CURRENT_USER, never Software\\Classes."""

    BASE = r"Software\GameSafetyScannerTests\Classes"

    def setUp(self):
        if sys.platform != "win32":
            self.skipTest("Windows only")
        import winreg
        from gamescan import shellmenu
        self.reg, self.m = winreg, shellmenu
        self.wipe(r"Software\GameSafetyScannerTests")
        self.addCleanup(self.wipe, r"Software\GameSafetyScannerTests")
        winreg.CloseKey(winreg.CreateKey(winreg.HKEY_CURRENT_USER, self.BASE))

    def wipe(self, path):
        reg = self.reg
        try:
            with reg.OpenKey(reg.HKEY_CURRENT_USER, path) as handle:
                children = [reg.EnumKey(handle, i) for i in range(reg.QueryInfoKey(handle)[0])]
        except OSError:
            return
        for child in children:
            self.wipe(path + "\\" + child)
        reg.DeleteKey(reg.HKEY_CURRENT_USER, path)

    def keys(self, path=None):
        """Every key below ``path`` (default: the test's Classes), as relative names."""
        reg, path = self.reg, path or self.BASE
        out = []
        with reg.OpenKey(reg.HKEY_CURRENT_USER, path) as handle:
            for i in range(reg.QueryInfoKey(handle)[0]):
                child = reg.EnumKey(handle, i)
                out += [child] + [child + "\\" + k for k in self.keys(path + "\\" + child)]
        return sorted(out)

    @staticmethod
    def argv(command):
        """How Windows splits a command line (CommandLineToArgvW)."""
        import ctypes
        from ctypes import wintypes
        split = ctypes.windll.shell32.CommandLineToArgvW
        split.argtypes, split.restype = [wintypes.LPCWSTR, ctypes.POINTER(ctypes.c_int)], ctypes.POINTER(wintypes.LPWSTR)
        count = ctypes.c_int()
        args = split(command, ctypes.byref(count))
        try:
            return [args[i] for i in range(count.value)]
        finally:
            ctypes.windll.kernel32.LocalFree(args)

    def test_add_use_remove_leaves_no_key_behind(self):
        """One entry "Bagel" with a submenu (final polish, phageo 2026-10-25)."""
        self.assertEqual(self.m.state(self.BASE)[:2], (False, False))
        self.m.add("Scan", self.BASE, launch_label="Safe launch (test)")
        exe = "SystemFileAssociations\\.exe\\shell\\GameSafetyScanner"
        self.assertEqual(self.keys(), sorted([
            "*", "*\\shell", "*\\shell\\GameSafetyScanner", "*\\shell\\GameSafetyScanner\\shell",
            "*\\shell\\GameSafetyScanner\\shell\\1scan", "*\\shell\\GameSafetyScanner\\shell\\1scan\\command",
            "Directory", "Directory\\shell", "Directory\\shell\\GameSafetyScanner",
            "Directory\\shell\\GameSafetyScanner\\shell", "Directory\\shell\\GameSafetyScanner\\shell\\1scan",
            "Directory\\shell\\GameSafetyScanner\\shell\\1scan\\command", "SystemFileAssociations",
            "SystemFileAssociations\\.exe", "SystemFileAssociations\\.exe\\shell", exe, exe + "\\shell",
            exe + "\\shell\\1scan", exe + "\\shell\\1scan\\command", exe + "\\shell\\2launch",
            exe + "\\shell\\2launch\\command"]))
        added, here, found = self.m.state(self.BASE)
        self.assertEqual((added, here, len(found)), (True, True, 4))
        reg = self.reg
        for key in ("Directory\\shell\\GameSafetyScanner", "*\\shell\\GameSafetyScanner", exe):
            with reg.OpenKey(reg.HKEY_CURRENT_USER, self.BASE + "\\" + key) as h:
                self.assertEqual(reg.QueryValueEx(h, "MUIVerb")[0], "Bagel", key)
                self.assertEqual(reg.QueryValueEx(h, "SubCommands")[0], "", "a submenu")
                self.assertEqual(reg.QueryValueEx(h, "Icon")[0], self.m.icon_path(), "the icon on the entry")
                with self.assertRaises(OSError):
                    reg.QueryValueEx(h, "")                 # never the default action
        self.assertTrue(self.m.icon_path().endswith("bagel.ico"))
        with reg.OpenKey(reg.HKEY_CURRENT_USER, self.BASE + "\\" + exe + "\\shell\\2launch") as h:
            self.assertEqual(reg.QueryValueEx(h, "MUIVerb")[0], "Safe launch (test)")
        with reg.OpenKey(reg.HKEY_CURRENT_USER, self.BASE + "\\" + exe + "\\shell\\1scan") as h:
            self.assertEqual(reg.QueryValueEx(h, "MUIVerb")[0], "Scan")
        with reg.OpenKey(reg.HKEY_CURRENT_USER, self.BASE + r"\Directory\shell") as h:
            with self.assertRaises(OSError):
                reg.QueryValueEx(h, "")                 # no default verb set
        python, script = self.m.app_paths()
        self.assertTrue(os.path.isfile(script), script)
        self.assertEqual(os.path.basename(script), "GameSafetyScanner.pyw")
        self.assertIsNone(self.m.start_program(), "the project folder has no Bagel.exe beside app\\")
        # use: what Explorer runs for a folder with spaces, "&" and "%" in its name
        clicked = r"C:\Games\Tom & Jerry 100% (v1.0)"
        for command in found[:3]:
            self.assertEqual(self.argv(command.replace("%1", clicked)), [python, "-I", script, clicked])
        # "Safe launch" on a program: the fixed word --launch, then the clicked program only
        program = r"C:\Games\Tom & Jerry 100% (v1.0)\Game.exe"
        self.assertEqual(self.argv(found[3].replace("%1", program)), [python, "-I", script, "--launch", program])
        self.m.remove(self.BASE)
        self.assertEqual(self.keys(), [], "no key of ours left")
        self.assertEqual(self.m.state(self.BASE)[:2], (False, False))
        self.m.remove(self.BASE)                        # removing twice is no error

    def test_the_entries_of_an_older_copy_are_replaced(self):
        """Before 2026-10-25: "Scan with Bagel" with its own command, "Safe launch with Bagel" apart."""
        reg = self.reg
        old = '"C:\\Old\\python\\pythonw.exe" -I "C:\\Old\\app\\GameSafetyScanner.pyw" "%1"'
        for key in (r"Directory\shell\GameSafetyScanner", r"*\shell\GameSafetyScanner",
                    r"SystemFileAssociations\.exe\shell\GameSafetyScannerLaunch"):
            with reg.CreateKeyEx(reg.HKEY_CURRENT_USER, self.BASE + "\\" + key + r"\command", 0, reg.KEY_WRITE) as h:
                reg.SetValueEx(h, "", 0, reg.REG_SZ, old)
        added, here, found = self.m.state(self.BASE)
        self.assertEqual((added, here), (True, False), "an older copy's entries: offered to point here")
        self.assertIn(old, found)
        self.m.add("Scan", self.BASE)
        self.assertEqual(self.m.state(self.BASE)[:2], (True, True))
        self.assertNotIn("SystemFileAssociations\\.exe\\shell\\GameSafetyScannerLaunch", self.keys())
        self.m.remove(self.BASE)
        self.assertEqual(self.keys(), ["*", "*\\shell", "Directory", "Directory\\shell", "SystemFileAssociations",
                                       "SystemFileAssociations\\.exe", "SystemFileAssociations\\.exe\\shell"],
                         "only the parents the older copy made stay (their record went with its entries)")
        with reg.CreateKeyEx(reg.HKEY_CURRENT_USER, self.BASE + r"\SystemFileAssociations\.exe\shell"
                             r"\GameSafetyScannerLaunch\command", 0, reg.KEY_WRITE) as h:
            reg.SetValueEx(h, "", 0, reg.REG_SZ, old)
        self.m.remove(self.BASE)                        # remove alone takes the old one too
        self.assertNotIn("SystemFileAssociations\\.exe\\shell\\GameSafetyScannerLaunch", self.keys())

    def test_the_package_runs_bagel_exe(self):
        """A copy in a package (app\\ and python\\ beside Bagel.exe) names Bagel.exe in the menu."""
        with tempfile.TemporaryDirectory() as top:
            for name in ("Bagel.exe", "python/pythonw.exe", "app/GameSafetyScanner.pyw"):
                path = os.path.join(top, *name.split("/"))
