class RoundTwoFixTests(unittest.TestCase):
    """The fix session before 0.9-beta (phageo, 2026-10-23): the bugs and policies of the
    round-2 diagnosis (docs/benchmark/EXPECTATIONS.md)."""

    ELF = b"\x7fELF\x02\x01\x01" + b"\0" * 9 + bytes(range(256)) * 4

    @staticmethod
    def zipped(members):
        out = io.BytesIO()
        with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
            for name, data in members.items():
                z.writestr(name, data)
        return out.getvalue()

    def notes(self, found):
        return [f.evidence for f in found if f.rule_id == "ARC-002"]

    def test_a_member_that_is_left_out_is_said_unless_clearly_harmless(self):
        """Bug 3: a member without a telling ending that is not read gets the "not inspected"
        note - unless it is clearly harmless data (padding, text that is no script by its
        content, a picture / sound / font that is all media, a file of an official table)."""
        from gamescan import models
        game = {"game/script.rpy": b"label start:\n    return\n", "lib/linux/libpython.so": self.ELF}
        for name, archive in (("game.zip", self.zipped(game)), ("game.7z", build_7z(game))):
            found = Scanner().scan_bytes(name, archive)
            note, = self.notes(found)
            self.assertIn("1 member(s) of a kind the scanner does not read (Linux program or library) were "
                          "not inspected: lib/linux/libpython.so", note)
            self.assertIn("ARC-002", models.UNREAD_CONTENT, "so the verdict is at least REVIEW")
        harmless = {"a.dat": b"\0" * 300, "pic.bin": build_png(), "font.fnt": b"OTTO" + b"\x01" * 200,
                    "readme": b"Run the game with Game.exe.\n",
                    "app.ico": b"\0\0\x01\0\x01\0" + b"\x10\x10\0\0\x01\0\x20\0" + struct.pack("<II", 40, 22) + b"\x28" * 40,
                    "pic.ppm": b"P6\n2 2\n255\n" + bytes(range(12))}
        for name, archive in (("data.zip", self.zipped(harmless)), ("data.7z", build_7z(harmless))):
            self.assertEqual(self.notes(Scanner().scan_bytes(name, archive)), [], name)
        # text under an ending Windows does not run is data (measured 2026-10-23: reading every
        # text member cost four clean games SUSPICIOUS; telling scripts apart by content flagged
        # read-me texts and translations); under an ending it runs, it is read as ever
        batch = b"@echo off\r\nset X=1\r\nvssadmin delete shadows /all /quiet\r\n"
        found = Scanner().scan_bytes("data.zip", self.zipped({"notes": batch}))
        self.assertEqual((self.notes(found), [f for f in found if f.file.startswith("data.zip!notes")]), ([], []))
        found = Scanner().scan_bytes("data.zip", self.zipped({"notes.bat": batch}))
        self.assertTrue(active([f for f in found if f.file == "data.zip!notes.bat"], "EVADE-001"))
        from gamescan.handlers import containers
        self.assertEqual(containers._member_kind(b"\x0d\x0d\r\n" + b"\x80" * 20), "compiled Python")
        self.assertEqual(containers._member_kind(b"@{\r\n" + b"\x80" * 20), "data of an unknown kind")
        # compiled Python is read in an archive as on disk (it was left out unread: RPY-01..03)
        self.assertTrue(containers.Policy.keep("lib/python2.7/os.pyc", b"\x03\xf3\r\n" + b"\0" * 20))
        self.assertTrue(containers.Policy.keep("renpy/main.pyo", b"\x03\xf3\r\n" + b"\0" * 20))
        # a picture with something behind it is not "all media"
        found = Scanner().scan_bytes("data.zip", self.zipped({"pic.bin": build_png() + bytes(range(1, 200))}))
        self.assertEqual(len(self.notes(found)), 1)
        # too large to be looked at, without a telling ending: said too
        from gamescan.handlers import containers
        policy = containers.Policy()
        self.assertFalse(policy.want("big.dat", containers.MAX_UNNAMED + 1))
        self.assertIn("big.dat", " ".join(policy.problems()))

    def test_an_encrypted_7z_says_password_whatever_follows_the_encryption(self):
        """Bug 4: AES stands first in the chain (on the packed stream), LZMA after it; the note
        named the LZMA coder ("filter 030101") instead of the password."""
        content = b"MZ" + b"\0" * 200
        packed = os.urandom(208)                            # what the encryption made of it
        names = "setup.exe\0".encode("utf-16-le")
        aes = b"\x24\x06\xf1\x07\x01" + z7_number(2) + b"\x00\x00"     # id, properties: none worth reading
        lzma2 = b"\x21\x21\x01\x12"
        header = (b"\x01\x04"
                  + b"\x06" + z7_number(0) + z7_number(1) + b"\x09" + z7_number(len(packed)) + b"\x00"
                  + b"\x07\x0b" + z7_number(1) + b"\x00" + z7_number(2) + lzma2 + aes
                  + z7_number(0) + z7_number(1)                         # LZMA2 reads what AES gives
                  + b"\x0c" + z7_number(len(content)) + z7_number(len(packed)) + b"\x00"
                  + b"\x08\x0d" + z7_number(1) + b"\x00"
                  + b"\x00"
                  + b"\x05" + z7_number(1) + b"\x11" + z7_number(len(names) + 1) + b"\x00" + names + b"\x00"
                  + b"\x00")
        start = struct.pack("<QQI", len(packed), len(header), zlib.crc32(header))
        archive = b"7z\xbc\xaf\x27\x1c\x00\x04" + struct.pack("<I", zlib.crc32(start)) + start + packed + header
        notes = self.notes(Scanner().scan_bytes("data/inner.7z", archive))
        self.assertEqual(len(notes), 1, notes)
        self.assertIn("password", notes[0])
        self.assertNotIn("030101", notes[0])
        self.assertNotIn("filter", notes[0])

    def test_a_downloaded_argument_of_a_fixed_program_is_high(self):
        """Policy 6 (round 2, HO2-01's tool): a download that reaches only an argument of a
        fixed program that is no shell or interpreter, with no shell between and nothing
        downloaded run, is CHAIN-REMOTE-ARG (HIGH); cmd / PowerShell / Python ... unchanged."""
        head = ("import json, subprocess, urllib.request\n"
                "info = json.loads(urllib.request.urlopen('https://api.example.invalid/repo').read())\n"
                "url = info['git_url']\n")

        def chains(start):
            found = Scanner().scan_bytes("data/tools/fetch.py", (head + start + "\n").encode())
            return sorted((f.rule_id, f.severity.name) for f in found
                          if f.rule_id in ("CHAIN-REMOTE-CODE", "CHAIN-REMOTE-ARG") and not f.suppressed)
        self.assertEqual(chains("subprocess.check_call(['git', 'clone', url])"), [("CHAIN-REMOTE-ARG", "HIGH")])
        self.assertEqual(chains("subprocess.run(('C:\\\\Tools\\\\git.exe', 'clone', url), shell=False)"),
                         [("CHAIN-REMOTE-ARG", "HIGH")])
        for start in ("subprocess.check_call(['cmd', '/c', url])", "subprocess.call(['powershell', '-c', url])",
                      "subprocess.run(['python', '-c', url])", "subprocess.run(['node.exe', '-e', url])",
                      "subprocess.check_call(['git', 'clone', url], shell=True)",
                      "subprocess.check_call('git clone ' + url, shell=True)",
                      "subprocess.check_call([url, 'clone'])", "os.system('git clone ' + url)",
                      "subprocess.check_call(['git', 'clone', url], executable='sh')"):
            self.assertIn(("CHAIN-REMOTE-CODE", "CRITICAL"), chains(start), start)
        # ... and a download that is run as code stays CRITICAL beside it
        both = chains("subprocess.check_call(['git', 'clone', url])\nexec(url)")
        self.assertEqual(both, [("CHAIN-REMOTE-ARG", "HIGH"), ("CHAIN-REMOTE-CODE", "CRITICAL")])

    def test_a_fixed_program_list_handed_through_a_name_is_high(self):
        """phageo, 2026-10-24 (HO2-01's tool): policy 6 also when the list reaches the start through
        a name - assigned in the function, or handed as an argument to a helper that starts it
        (``self._execute(["git", "clone", url, target])`` -> ``subprocess.Popen(command, ...)``).
        Every value the name can have must be such a list; else unchanged (CRITICAL)."""
        head = ("import json, subprocess, urllib.request\n"
                "def ask():\n"
                "    return json.loads(urllib.request.urlopen('https://api.example.invalid/repo').read())\n")

        def chains(body):
            found = Scanner().scan_bytes("data/tools/fetch.py", (head + body).encode())
            return sorted((f.rule_id, f.severity.name) for f in found
                          if f.rule_id in ("CHAIN-REMOTE-CODE", "CHAIN-REMOTE-ARG") and not f.suppressed)
        helper =("class Repo:\n"
                  "    def _execute(self, command, cwd=None):\n"
                  "        p = subprocess.Popen(command, stdout=subprocess.PIPE, close_fds=True, cwd=cwd)\n"
                  "        return p.communicate()\n"
                  "    def _clone(self, name, url):\n"
                  "        return self._execute(['git', 'clone', url, name])\n"
                  "    def update(self):\n"
                  "        self._clone('a', ask()['git_url'])\n")
        self.assertEqual(chains(helper), [("CHAIN-REMOTE-ARG", "HIGH")])
        local = ("def fetch():\n"
                 "    url = ask()['git_url']\n"
                 "    cmd = ['git', 'clone', url]\n"
                 "    subprocess.check_call(cmd)\n")
        self.assertEqual(chains(local), [("CHAIN-REMOTE-ARG", "HIGH")])
        # one caller hands a shell, or the command itself is downloaded: CRITICAL as before
        for other in ("        self._execute(['cmd', '/c', ask()['run']])\n",
                      "        self._execute(ask()['command'])\n"):
            self.assertIn(("CHAIN-REMOTE-CODE", "CRITICAL"), chains(helper + other), other)
        self.assertIn(("CHAIN-REMOTE-CODE", "CRITICAL"),
                      chains(local.replace("cmd = ['git', 'clone', url]", "cmd = ['git', 'clone', url]\n"
                                                                            "    cmd = url")))
        # a name of the file: any code may set it - unchanged
        self.assertIn(("CHAIN-REMOTE-CODE", "CRITICAL"),
                      chains("CMD = ['git', 'clone', ask()['git_url']]\nsubprocess.check_call(CMD)\n"))

    def test_a_text_alone_in_a_program_stays_high(self):
        """Policy 7 (a text alone among a program's strings -> MEDIUM) was removed on 2026-10-24
        (phageo): it broke the malicious bar (45 of 51). `rundll32.exe` / `.ssh/id_rsa` among a
        library's strings stay HIGH, with or without other evidence in the program."""
        from gamescan import scanner
        self.assertFalse(hasattr(scanner, "TEXT_ONLY_MEDIUM"))
        self.assertFalse(hasattr(scanner, "_text_only"))
        strings = b"\0rundll32.exe url.dll,FileProtocolHandler %s\0C:\\Users\\x\\.ssh\\id_rsa\0"

        def levels(imports):
            found = Scanner().scan_bytes("Game/UnityPlayer.dll", build_pe(imports, strings=strings))
            return sorted({(f.rule_id, f.severity.name) for f in found if f.rule_id in ("LOL-001", "CRED-001", "INJ-001")
                           and not f.suppressed})
        self.assertEqual(levels(["ExitProcess", "Sleep"]), [("CRED-001", "HIGH"), ("LOL-001", "HIGH")])
        found = [f for f in Scanner().scan_bytes("Game/UnityPlayer.dll", build_pe(["ExitProcess"], strings=strings))
                 if f.rule_id == "LOL-001"]
        self.assertNotIn("[only a text in the program]", found[0].evidence)
        self.assertEqual(levels(["VirtualAllocEx", "WriteProcessMemory", "CreateRemoteThread", "ExitProcess"]),
                         [("CRED-001", "HIGH"), ("INJ-001", "HIGH"), ("LOL-001", "HIGH")])
        # a script: unchanged
        script = Scanner().scan_bytes("tool.bat", b"rundll32.exe url.dll,FileProtocolHandler x\r\n")
        self.assertIn(("LOL-001", "HIGH"), {(f.rule_id, f.severity.name) for f in script if not f.suppressed})

    def test_keylog_word_in_script_and_in_library(self):
        """phageo, 2026-10-23 (round-2 gate): an underscore is no part of a name again - the round-2
        change is taken back. ``start_keylogger`` in a script is found (HIGH); OpenSSL's
        ``nss_keylog_int`` among a compiled library's strings is found too - HIGH (policy 7,
        which made it MEDIUM, was removed on 2026-10-24)."""
        def levels(name, data):
            return [f.severity for f in Scanner().scan_bytes(name, data)
                    if f.rule_id == "INPUT-001" and not f.suppressed]
        self.assertEqual(levels("game/tools/helper.py", b"helper.start_keylogger()\n"),
                         [Severity.HIGH])
        library = build_pe(["ExitProcess"], strings=b"\0nss_keylog_int\0SSL_CTX_set_keylog_callback\0")
        self.assertEqual(levels("Game/libssl-1_1-x64.dll", library), [Severity.HIGH])


class PackageBuilderTests(unittest.TestCase):
    """tools/build_package.py (0.9-beta, phageo 2026-10-24): python/ + app/ + one start file, an
    allowlist, nothing of tests/, engine_archives, docs, the behaviour monitor, no real name."""

    def setUp(self):
        sys.path.insert(0, os.path.join(ROOT, "tools"))
        self.addCleanup(sys.path.remove, os.path.join(ROOT, "tools"))
        import build_package
        self.b = build_package

    def test_the_package_is_named_by_the_one_version(self):
        from gamescan import models
        self.assertEqual(self.b.package_name(), "Bagel-" + models.TOOL_VERSION)
        self.assertEqual(self.b.package_name(), "Bagel-0.9.0-beta")
        self.assertEqual(self.b.START, "Bagel.exe", "the start program (final polish, 2026-10-25)")

    def test_the_start_program_is_the_kept_bagel_exe(self):
        """Final polish (phageo, 2026-10-25): Bagel.exe (tools/build_launcher.py, Windows' own csc.exe,
        built once) replaces Bagel.bat - windowed, Bagel's version information and icon."""
        import build_launcher
        import release_check
        if not os.path.isfile(build_launcher.PROGRAM):   # a clone of the repository: built, never committed
            self.skipTest("Bagel.exe is not built here - python tools/build_launcher.py")
        self.assertEqual(build_launcher.check(), "", "Bagel.exe is the file of launcher.json")
        with open(build_launcher.PROGRAM, "rb") as fh:
            program = fh.read()
        with open(os.path.join(ROOT, "gamescan", "bagel.ico"), "rb") as fh:
            icon = fh.read()
        name, passed, detail = release_check.start_check({"Bagel.exe": program, "app/gamescan/bagel.ico": icon})
        self.assertTrue(passed, detail)
        self.assertEqual(release_check.version_texts(program)["FileVersion"], "0.9.0-beta")
        self.assertEqual(build_launcher.numeric("0.9.0-beta"), "0.9.0.0")
        with open(build_launcher.SOURCE, encoding="utf-8") as fh:
            source = fh.read()
        for words in ('"pythonw.exe"', '"GameSafetyScanner.pyw"', '"-I \\""', "WaitForExit()", "return child.ExitCode;",
                      "UseShellExecute = false"):
            self.assertIn(words, source)
        self.assertIn('[assembly: AssemblyCompany("phageo")]', build_launcher.assembly_info())
        # source release (phageo, 2026-10-25): no debug data, deterministic, nothing of a folder path
        self.assertFalse(build_launcher.has_debug_directory(program))
        self.assertEqual(build_launcher.deterministic(program), program, "time stamp and MVID from the content")
        self.assertTrue(build_launcher.record().get("deterministic"))
        for text in (b".pdb", b"RSDS", b"\\Users\\", "\\Users\\".encode("utf-16-le")):
            self.assertNotIn(text, program)
        changed = bytearray(program)
        place = build_launcher._pe_places(program)["mvid"]
        changed[place] ^= 0xFF
        self.assertEqual(build_launcher.deterministic(bytes(changed)), program, "a random MVID is replaced")

