class IndicatorStringsTests(unittest.TestCase):
    """gamescan/indicators.py and tools/move_indicators.py (phageo, 2026-10-24, antivirus false
    positives): the indicator strings are compressed data decoded in memory, moving them changes
    no code, and none is left as text in a shipped module."""

    def setUp(self):
        sys.path.insert(0, os.path.join(ROOT, "tools"))
        self.addCleanup(sys.path.remove, os.path.join(ROOT, "tools"))
        import move_indicators
        self.m = move_indicators

    def test_the_file_reads_back_what_was_written(self):
        from gamescan import indicators
        tables = {"gamescan/a.py": ("plain", "Türkçe", b"\x00\xffbytes"), "gamescan/b/c.py": ()}
        data = indicators.encode(tables)
        self.assertTrue(data.startswith(indicators.MAGIC))
        self.assertEqual(indicators.decode(data), tables)
        self.assertEqual(indicators.encode(tables), data, "same tables, same bytes")

    def test_a_damaged_or_oversized_file_is_refused(self):
        from gamescan import indicators
        data = indicators.encode({"gamescan/a.py": ("x" * 100,)})
        for bad in (b"", indicators.MAGIC + b"\x00garbage", data[:-3], data + b"tail", b"other" + data,
                    indicators.MAGIC + zlib.compress(b'{"modules": {"a": [{"c": 1}]}}')[2:-4]):
            with self.assertRaises(indicators.IndicatorError):
                indicators.decode(bad)
        bomb = indicators.encode({"gamescan/a.py": ("a" * (indicators.DECODED_CAP + 1),)})
        self.assertLess(len(bomb), 1 << 20)
        with self.assertRaises(indicators.IndicatorError):
            indicators.decode(bomb)

    def test_a_moved_module_is_the_same_code(self):
        import ast
        patterns = [("word", re.compile(rb"secretword", re.IGNORECASE))]
        source = (b'"""Docstring: secretword stays."""\r\n'
                  b"from __future__ import annotations\r\n"
                  b"import re\r\n"
                  b'A = re.compile(r"SecretWord\\s+x")\r\n'
                  b"B = ('secretword', b'secretword', 'other',\r\n"
                  b"     'secret' 'word')\r\n"
                  b"def f(x: 'secretword') -> str:\r\n"
                  b'    return f"{x} secretword" + "secretword"\r\n')
        key = "gamescan/dataflow/x.py"
        new, table, count = self.m.move(source, key, (), patterns)
        self.assertEqual(count, 5)                     # A, three in B, the one after the f-string
        self.assertEqual(len(table), 3)                # each value once: str, bytes, the pattern
        self.assertEqual(new.lower().count(b"secretword"), 3, "docstring, annotation, f-string stay")
        self.assertIn(b"from ..indicators import strings as _indicator_strings", new)
        self.assertIn(b'_IND = _indicator_strings("gamescan/dataflow/x.py")\r\n', new)
        self.assertEqual(self.m.resolved(ast.parse(new), table), ast.dump(ast.parse(source)))
        self.assertEqual(self.m.move(new, key, table, patterns), (new, table, 0), "a second run moves nothing")
        self.assertIn(b"from .indicators import", self.m.move(source, "gamescan/x.py", (), patterns)[0])
        self.assertIn(b"from .indicators import", self.m.move(source, "gamescan/__init__.py", (), patterns)[0])
        from gamescan import cache                       # the loader only, not the whole package
        imported = cache._imports("gamescan.dataflow.x", "x.py", new)
        self.assertIn("gamescan.indicators", imported)
        self.assertNotIn("gamescan", imported)
        with self.assertRaises(self.m.MoveError):
            self.m.move(b"_IND = 1\nA = 'secretword'\n", key, (), patterns)
        self.assertEqual(self.m.left_in({"app/gamescan/x.py": source, "app/gamescan/y.py": new}, patterns),
                         ["app/gamescan/x.py"])

    def test_no_indicator_literal_is_left_in_the_shipped_modules(self):
        self.assertEqual(self.m.run_check(say=lambda *_: None), 0, "run tools/move_indicators.py")
        import build_package
        self.assertIn("app/gamescan/indicators.bin", [n for n, _p in build_package.app_files()])
        from gamescan import known_findings
        self.assertIn("indicators.bin", known_findings.CODE_DATA, "the strings are part of the code")

    def test_the_shipped_file_holds_no_moved_string_as_text(self):
        from gamescan import indicators
        with open(indicators.path(), "rb") as fh:
            data = fh.read()
        modules = indicators.decode(data)
        self.assertEqual(indicators.load(), modules)
        values = [v for t in modules.values() for v in t]
        self.assertGreater(len(values), 100)
        for number, value in enumerate(values):
            raw = value.encode("utf-8") if isinstance(value, str) else value
            if len(raw) >= 8:
                self.assertFalse(raw in data, "string %d stands as text" % number)   # (never printed)
        for module in modules:
            self.assertTrue(os.path.isfile(os.path.join(ROOT, *module.split("/"))), module)


class ShippedSourceFormTests(unittest.TestCase):
    """tools/source_form.py and the package's code fingerprint (phageo, 2026-10-24, antivirus false
    positives, second test build): shipped modules lose comments and docstrings - the same code by
    syntax tree - and keep the project's fingerprint, so their kept readings stay current."""

    def setUp(self):
        sys.path.insert(0, os.path.join(ROOT, "tools"))
        self.addCleanup(sys.path.remove, os.path.join(ROOT, "tools"))
        import source_form
        self.f = source_form

    def test_comments_and_docstrings_go_the_code_stays(self):
        import ast
        source = ('"""Module text."""\r\n'
                  "from __future__ import annotations\r\n"
                  "# a whole comment line\r\n"
                  "X = '# not a comment'  # a comment\r\n"
                  "def f(a):\r\n"
                  '    """Only a docstring."""\r\n'
                  "class C:\r\n"
                  '    """Class text,\r\n'
                  '    two lines."""\r\n'
                  "    y = 'kept'\r\n"
                  "    \"\"\"a string statement that is no docstring\"\"\"\r\n"
                  "s = '\u00e7 text'  # \u00e7\r\n").encode("utf-8")
        out = self.f.strip(source)
        for gone in (b"Module text", b"whole comment", b"# a comment", b"Only a docstring", b"Class text"):
            self.assertNotIn(gone, out)
        for kept in (b"'# not a comment'", b"'kept'", b"no docstring", "'\u00e7 text'".encode("utf-8")):
            self.assertIn(kept, out)
        self.assertTrue(out.startswith(b"from __future__ import annotations\r\n"), "nothing before __future__")
        self.assertIn(b"def f(a):\r\n    pass\r\n", out)
        self.assertNotIn(b"\n", out.replace(b"\r\n", b""), "line ends as they were")
        self.assertEqual(self.f.strip(out), out, "a second strip changes nothing")
        tree = ast.parse(source)
        tree.body.pop(0)
        tree.body[2].body[0] = ast.Pass()
        tree.body[3].body.pop(0)
        tree.body[3].body.insert(0, ast.Pass())
        self.assertEqual(ast.dump(ast.parse(out)), ast.dump(tree))

    def test_a_module_that_reads_docstrings_keeps_them(self):
        source = b'"""Usage text."""\nimport argparse\np = argparse.ArgumentParser(description=__doc__)  # c\n'
        out = self.f.strip(source)
        self.assertIn(b"Usage text", out)
        self.assertNotIn(b"# c", out)

    def test_the_package_keeps_the_projects_fingerprint(self):
        from unittest import mock
        from gamescan import known_findings
        self.assertFalse(os.path.exists(os.path.join(ROOT, "gamescan", known_findings.SHIPPED_PRINT)),
                         "only the package holds it")
        import build_package
        self.assertEqual(build_package.SHIPPED_PRINT, "app/gamescan/" + known_findings.SHIPPED_PRINT)
        self.assertEqual(build_package.refusal(build_package.SHIPPED_PRINT), "")
        real_open, held = open, known_findings._print
        shipped = "ab" * 32

        def fake_open(path, *args, **kwargs):
            if str(path).endswith(known_findings.SHIPPED_PRINT):
                return io.BytesIO((shipped + "\n").encode("ascii"))
            return real_open(path, *args, **kwargs)

        try:
            known_findings._print = None
            with mock.patch("builtins.open", fake_open):
                self.assertEqual(known_findings.fingerprint(), shipped)
            known_findings._print = None
            shipped = "not a fingerprint"
            with mock.patch("builtins.open", fake_open):
                self.assertNotEqual(known_findings.fingerprint(), shipped, "a damaged one is not taken")
        finally:
            known_findings._print = held

    def test_every_shipped_module_strips_to_the_same_code(self):
        import build_package
        count = 0
        for name, path in build_package.app_files():
            if name.endswith((".py", ".pyw")):
                with open(path, "rb") as fh:
                    out = self.f.strip(fh.read())          # (raises if the code would differ)
                self.assertEqual(self.f.strip(out), out, name)
                count += 1
        self.assertGreater(count, 100)


class IconBuilderTests(unittest.TestCase):
    """tools/build_icon.py (0.9-beta polish, phageo 2026-10-24): stdlib only; the black background
    goes, specks go, dark pixels inside the bagel stay; small sizes nearest-neighbour."""

    def setUp(self):
        sys.path.insert(0, os.path.join(ROOT, "tools"))
        self.addCleanup(sys.path.remove, os.path.join(ROOT, "tools"))
        import build_icon
        self.b = build_icon

    def ring(self):
        """40x40 on black: a brown ring with an open top, a dark spot inside its body, a speck."""
        w = h = 40
        px = [(0, 0, 0, 255)] * (w * h)
        for y in range(h):
            for x in range(w):
                d = ((x - 20) ** 2 + (y - 20) ** 2) ** 0.5
                if 10 <= d <= 16 and not (y < 14 and 16 <= x <= 24):
                    px[y * w + x] = (180, 100, 50, 255)
        px[20 * w + 6] = (10, 8, 6, 255)                    # dark pixel inside the ring's body
        px[20 * w + 7] = (12, 9, 7, 255)
        for x, y in ((2, 2), (3, 2), (2, 3)):                # a dark speck, apart from the ring
            px[y * w + x] = (60, 60, 60, 255)               # (just above "dark": the fill keeps it)
        return w, h, px

    def test_background_and_specks_go_dark_pixels_inside_stay(self):
        w, h, px = self.ring()
        out, counts = self.b.remove_background(w, h, px)
        self.assertEqual(out[0][3], 0, "the corner is background")
        self.assertEqual(out[20 * w + 20][3], 0, "the hole is reached through the gap")
        self.assertEqual(out[20 * w + 6], (10, 8, 6, 255), "a dark pixel inside the bagel is never touched")
        self.assertEqual(out[20 * w + 7], (12, 9, 7, 255))
        self.assertEqual([out[y * w + x][3] for x, y in ((2, 2), (3, 2), (2, 3))], [0, 0, 0], "the speck")
        self.assertEqual(counts["specks"], 1)
        self.assertEqual(out[20 * w + 8], (180, 100, 50, 255), "the bagel's colour kept")

    def test_nearest_neighbour_and_area_shrink(self):
        px = [(x * 10, y * 10, 0, 255) for y in range(4) for x in range(4)]
        self.assertEqual(self.b.nearest(4, px, 2), [px[1 * 4 + 1], px[1 * 4 + 3], px[3 * 4 + 1], px[3 * 4 + 3]])
        self.assertTrue(set(self.b.nearest(4, px, 3)) <= set(px), "only source pixels, never mixed")
        half = [(255, 0, 0, 255), (0, 0, 0, 0)] * 2
        self.assertEqual(self.b.shrink(2, half, 1), [(255, 0, 0, 128)], "no dark halo from transparency")

    def test_png_and_ico_round_trip(self):
        w, h, px = self.ring()
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "x.png")
            with open(path, "wb") as fh:
                fh.write(self.b.write_png(w, h, px))
            self.assertEqual(self.b.read_png(path), (w, h, px))
            with open(path, "wb") as fh:
                fh.write(b"not a png")
            with self.assertRaises(self.b.IconError):
                self.b.read_png(path)
        data = self.b.ico([(16, px[:256]), (256, [(1, 2, 3, 255)] * 65536)])
        self.assertEqual(self.b.read_ico_sizes(data), [16, 256])

    def test_the_shipped_icon_has_every_size(self):
        with open(os.path.join(ROOT, "gamescan", "bagel.ico"), "rb") as fh:
            self.assertEqual(self.b.read_ico_sizes(fh.read()), [16, 24, 32, 48, 64, 128, 256])


class BagelInstallerTests(unittest.TestCase):
    """tools/build_installer.py (0.9-beta polish; final polish 2026-10-25): only for me or for all
    users, folder page; Start menu to Bagel.exe; the one "Bagel" entry with its submenu, gone at
    uninstall; older entries replaced; nothing left, and nothing it did not install."""

