    def test_only_for_me_or_for_all_users_with_a_folder_page(self):
        for line in ("PrivilegesRequired=lowest", "PrivilegesRequiredOverridesAllowed=dialog",
                     "DefaultDirName={autopf}\\Bagel", "DisableDirPage=no",
                     "AppName=Bagel", "AppPublisher=phageo", "OutputBaseFilename=Bagel-0.9.0-beta-setup",
                     "UninstallFilesDir={app}\\uninstall", "UninstallDisplayIcon={app}\\Bagel.exe",
                     "SetupIconFile=C:\\work\\Bagel-0.9.0-beta\\app\\gamescan\\bagel.ico"):
            self.assertIn("\r\n" + line + "\r\n", self.text, line)
