        entries = [i for i, l in enumerate(lines) if "deletekey uninsdeletekey" in l]
        self.assertEqual(len(parents), 7, "Directory, *, SystemFileAssociations and their shell keys, .exe")
        self.assertEqual(len(entries), 3, "one entry per place")
        self.assertLess(max(parents), min(entries), "parents first: the uninstaller works backwards")
        self.assertNotIn('Type: filesandordirs; Name: "{app}"', self.text, "a folder the user chose is not wiped")
        self.assertIn('Type: dirifempty; Name: "{app}"', self.text)
        self.assertIn("ExpandConstant('{%USERPROFILE}\\.game_safety_scanner')", self.text)
