        self.assertIn("tr.PurgeQuestion=Bagel'ın ayarları", self.text)
        with tempfile.TemporaryDirectory() as tmp:
            for name in ("Bagel.exe", "app/GameSafetyScanner.pyw", "app/gamescan/scanner.py",
                         "app/gamescan/dataflow/remote.py", "python/python.exe", "python/tkinter/__init__.py",
                         "python/tcl/tk8.6/tk.tcl"):
                path = os.path.join(tmp, *name.split("/"))
                os.makedirs(os.path.dirname(path), exist_ok=True)
